#include <bits/stdc++.h>
using namespace std;

int main() {
    long long a, b, c;
    cin >> a >> b >> c;
    if (a > b) swap(a, b);       // three swaps sort a <= b <= c
    if (b > c) swap(b, c);
    if (a > b) swap(a, b);
    if (a + b <= c) { cout << "Not triangle\n"; return 0; }
    if (a * a + b * b == c * c) cout << "Right\n";
    else if (a * a + b * b > c * c) cout << "Acute\n";
    else cout << "Obtuse\n";
    if (a == c) cout << "Equilateral\n";
    else if (a == b || b == c) cout << "Isosceles\n";
    return 0;
}

