#include <bits/stdc++.h>
using namespace std;
#define int long long

signed main() {
    int n;
    cin >> n;
    int sum = 0, mn = LLONG_MAX, mx = LLONG_MIN;
    int prev = 0, cur = 0, best = 0;   // longest run of +1 steps
    for (int i = 0; i < n; i++) {
        int x;
        cin >> x;
        sum += x;
        mn = min(mn, x);
        mx = max(mx, x);
        cur = (i > 0 && x == prev + 1) ? cur + 1 : 1;
        best = max(best, cur);
        prev = x;
    }
    cout << sum << " " << mn << " " << mx << " " << best << "\n";
    return 0;
}

