signed main() {
    int n, m;
    cin >> n >> m;
    bool prime = n >= 2;
    for (int i = 2; i * i <= n; i++)       // only up to sqrt(n)
        if (n % i == 0) { prime = false; break; }
    int p = 2;
    while (n % p != 0) p++;                // smallest factor of n
    int a = n, b = m;
    while (b != 0) { int r = a % b; a = b; b = r; }   // Euclid
    cout << (prime ? "prime" : "not prime") << " "
         << p << " " << a << "\n";
    return 0;
}

