        if (x >= 1000 && x < 10000) x = 10000;          // even length:
        if (x >= 100000 && x < 1000000) x = 1000000;    // divisible by 11,
        if (x >= 10000000 && x < 100000000) x = 100000000; // never prime
        if (x > b) break;
        int r = 0;
        for (int t = x; t > 0; t /= 10) r = r * 10 + t % 10;
