int dx[4] = {0, 1, 0, -1};       // right, down, left, up (row change)
int dy[4] = {1, 0, -1, 0};       //                       (col change)

int main() {
    int n;
    cin >> n;
    int x = 1, y = 1, d = 0;     // 1-based grid
    for (int k = 1; k <= n * n; k++) {
        a[x][y] = k;
        int nx = x + dx[d], ny = y + dy[d];
        if (nx < 1 || nx > n || ny < 1 || ny > n || a[nx][ny] != 0)
            d = (d + 1) % 4;     // blocked: turn right
        x += dx[d];
        y += dy[d];
    }
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= n; j++) cout << setw(3) << a[i][j];
        cout << "\n";
    }
    return 0;
}

