#include <bits/stdc++.h>
using namespace std;

int g[1030][1030];

// square of side s with top-left corner (r, c)
void solve(int r, int c, int s) {
    if (s == 1) return;                       // base case
    int h = s / 2;
    for (int i = 0; i < h; i++)               // top-left quarter: 0
        for (int j = 0; j < h; j++) g[r + i][c + j] = 0;
    solve(r, c + h, h);                       // the other three
    solve(r + h, c, h);                       // quarters repeat the
    solve(r + h, c + h, h);                   // same rule, smaller
}

int main() {
    int n;
    cin >> n;
    int s = 1 << n;                           // 2^n
    for (int i = 0; i < s; i++)
        for (int j = 0; j < s; j++) g[i][j] = 1;
    solve(0, 0, s);
    for (int i = 0; i < s; i++) {
        for (int j = 0; j < s; j++) cout << g[i][j] << " ";
        cout << "\n";
    }
    return 0;
}

