// true if a < b (both trimmed)
bool less_(const vector<int> &a, const vector<int> &b) {
    if (a.size() != b.size()) return a.size() < b.size();
    for (int i = int(a.size()) - 1; i >= 0; i--)
        if (a[i] != b[i]) return a[i] < b[i];
    return false;
}

vector<int> sub(vector<int> a, const vector<int> &b) {  // a >= b
    for (size_t i = 0; i < a.size(); i++) {
        if (i < b.size()) a[i] -= b[i];
        if (a[i] < 0) { a[i] += 10; a[i + 1]--; }    // borrow
    }
    trim(a);
    return a;
}

