vector<int> mul(const vector<int> &a, const vector<int> &b) {
    vector<long long> c(a.size() + b.size(), 0);
    for (size_t i = 0; i < a.size(); i++)
        for (size_t j = 0; j < b.size(); j++)
            c[i + j] += 1LL * a[i] * b[j];     // same column: i + j
    vector<int> r;
    long long carry = 0;
    for (size_t k = 0; k < c.size(); k++) {   // carry once at the end
        long long t = c[k] + carry;
        r.push_back(t % 10);
        carry = t / 10;
    }
    trim(r);
    return r;
}

