// q = a / k, returns the remainder; works from the top digit down
long long divSmall(const vector<int> &a, long long k, vector<int> &q) {
    q.assign(a.size(), 0);
    long long rem = 0;
    for (int i = int(a.size()) - 1; i >= 0; i--) {
        rem = rem * 10 + a[i];
        q[i] = rem / k;
        rem %= k;
    }
    trim(q);
    return rem;
}

