int a[100005];

void quickSort(int l, int r) {            // sorts a[l..r]
    if (l >= r) return;
    int pivot = a[(l + r) / 2], i = l, j = r;
    while (i <= j) {
        while (a[i] < pivot) i++;         // find a big one on the left
        while (a[j] > pivot) j--;         // find a small one on the right
        if (i <= j) { swap(a[i], a[j]); i++; j--; }
    }
    quickSort(l, j);                      // left part
    quickSort(i, r);                      // right part
}

int main() {
    int n;
    cin >> n;
    for (int i = 0; i < n; i++) cin >> a[i];
    quickSort(0, n - 1);
    for (int i = 0; i < n; i++) cout << a[i] << " ";
