// decode from s[pos] until ']' or the end
string decode() {
    string out;
    while (pos < s.size() && s[pos] != ']') {
        if (s[pos] == '[') {
            pos++;                            // skip '['
            int k = 0;
            while ('0' <= s[pos] && s[pos] <= '9') k = k * 10 + (s[pos++] - '0');
            string inner = decode();          // the bracket's content
            pos++;                            // skip ']'
            for (int i = 0; i < k; i++) out += inner;
        } else {
            out += s[pos++];
        }
    }
    return out;
}

