int n, part[20], len = 0;

// remaining sum to split; next part must be >= minPart
void split(int remaining, int minPart) {
    if (remaining == 0) {
        if (len < 2) return;              // "n" alone does not count
        for (int i = 0; i < len; i++) cout << part[i] << (i + 1 < len ? "+" : "\n");
        return;
    }
    for (int p = minPart; p <= remaining; p++) {
        part[len++] = p;                  // choose p
        split(remaining - p, p);          // later parts are not smaller
        len--;                            // undo
    }
}

