int main() {
    string s;
    cin >> s;                         // numbers end with '.', '@' ends all
    stack<long long> st;
    long long num = 0;
    for (int i = 0; i < int(s.size()) && s[i] != '@'; i++) {
        char ch = s[i];
        if ('0' <= ch && ch <= '9') num = num * 10 + (ch - '0');
        else if (ch == '.') { st.push(num); num = 0; }   // a number ends
        else {
            long long b = st.top(); st.pop();            // right operand
            long long a = st.top(); st.pop();            // left operand
            if (ch == '+') st.push(a + b);
            if (ch == '-') st.push(a - b);
            if (ch == '*') st.push(a * b);
            if (ch == '/') st.push(a / b);
        }
    }
    cout << st.top() << "\n";
    return 0;
}

