#include <bits/stdc++.h>
using namespace std;

int main() {
    int n;
    cin >> n;
    set<int> wood;
    while (n--) {
        int op, len;
        cin >> op >> len;
        if (op == 1) {
            if (wood.count(len)) cout << "Already Exist\n";
            else wood.insert(len);
            continue;
        }
        if (wood.empty()) { cout << "Empty\n"; continue; }
        set<int>::iterator it = wood.lower_bound(len);   // first >= len
        int pick;
        if (it == wood.end()) pick = *prev(it);          // all are smaller
        else if (it == wood.begin()) pick = *it;         // all are larger
        else {
            int big = *it, small = *prev(it);
            pick = (len - small <= big - len) ? small : big;   // tie: smaller
        }
        cout << pick << "\n";
        wood.erase(pick);
    }
