const int MOD = 80112002;
vector<int> adj[5005];
int indeg[5005], outdeg[5005];
long long ways[5005];                  // chains from a producer to here

int main() {
    int n, m;
    cin >> n >> m;
    for (int i = 0; i < m; i++) {
        int a, b;
        cin >> a >> b;                 // a is eaten by b: edge a -> b
        adj[a].push_back(b);
        indeg[b]++;
        outdeg[a]++;
    }
    queue<int> q;
    for (int u = 1; u <= n; u++)
        if (indeg[u] == 0) { ways[u] = 1; q.push(u); }   // producers
    long long total = 0;
    while (!q.empty()) {
        int u = q.front();
        q.pop();
        if (outdeg[u] == 0) total = (total + ways[u]) % MOD;   // top predator
        for (int k = 0; k < int(adj[u].size()); k++) {
            int v = adj[u][k];
            ways[v] = (ways[v] + ways[u]) % MOD;   // every chain to u extends to v
            if (--indeg[v] == 0) q.push(v);        // all inputs of v are done
        }
    }
    cout << total << "\n";
    return 0;
}

