        }
        h[0] = h[m + 1] = -1;                        // walls
        stack<int> st;
        for (int j = 1; j <= m + 1; j++) {           // nearest lower to the right
            while (!st.empty() && h[st.top()] > h[j]) { rgt[st.top()] = j; st.pop(); }
            st.push(j);
        }
        while (!st.empty()) st.pop();
        for (int j = m; j >= 0; j--) {               // nearest lower to the left
            while (!st.empty() && h[st.top()] > h[j]) { lft[st.top()] = j; st.pop(); }
            st.push(j);
        }
        for (int j = 1; j <= m; j++)
