long long power(long long a, long long b, long long p) {
    long long res = 1 % p;
    a %= p;
    while (b > 0) {
        if (b & 1) res = res * a % p;   // this bit of b is 1
        a = a * a % p;                   // a, a^2, a^4, a^8, ...
        b >>= 1;
    }
    return res;
}

