#include <bits/stdc++.h>
using namespace std;

struct P { double x, y; };
P p[10005];

double dist(P a, P b) { return sqrt((a.x - b.x) * (a.x - b.x) + (a.y - b.y) * (a.y - b.y)); }

double solve(int l, int r) {              // p[l..r] sorted by x
    if (r - l <= 2) {                     // tiny: try all pairs
        double d = 1e18;
        for (int i = l; i <= r; i++)
            for (int j = i + 1; j <= r; j++) d = min(d, dist(p[i], p[j]));
        return d;
    }
    int m = (l + r) / 2;
    double midX = p[m].x;
    double d = min(solve(l, m), solve(m + 1, r));
    vector<P> strip;                      // points within d of the middle line
    for (int i = l; i <= r; i++)
        if (fabs(p[i].x - midX) < d) strip.push_back(p[i]);
    sort(strip.begin(), strip.end(), [](const P &a, const P &b) { return a.y < b.y; });
    for (int i = 0; i < int(strip.size()); i++)
        for (int j = i + 1; j < int(strip.size()) && strip[j].y - strip[i].y < d; j++)
            d = min(d, dist(strip[i], strip[j]));   // only a few j per i
    return d;
}

int main() {
    int n;
    cin >> n;
    for (int i = 0; i < n; i++) cin >> p[i].x >> p[i].y;
    sort(p, p + n, [](const P &a, const P &b) { return a.x < b.x; });
    cout << fixed << setprecision(4) << solve(0, n - 1) << "\n";
    return 0;
}

