using namespace std;

int n, len[70], target, total;
bool used[70];

// built `done` full sticks; the current one has length cur; try pieces from index `from`
bool dfs(int done, int cur, int from) {
    if (done * target == total) return true;
    if (cur == target) return dfs(done + 1, 0, 0);          // start a new stick
    int lastFailed = -1;
    for (int i = from; i < n; i++) {
        if (used[i] || cur + len[i] > target) continue;      // feasibility
        if (len[i] == lastFailed) continue;                  // same length just failed
        used[i] = true;
        if (dfs(done, cur + len[i], i + 1)) return true;
        used[i] = false;
        lastFailed = len[i];
        if (cur == 0 || cur + len[i] == target) return false; // see the key point
    }
    return false;
}

int main() {
    cin >> n;
    for (int i = 0; i < n; i++) { cin >> len[i]; total += len[i]; }
    sort(len, len + n, greater<int>());                      // longest first
    for (target = len[0]; target <= total; target++) {
        if (total % target != 0) continue;                   // must divide the total
        fill(used, used + n, false);
        if (dfs(0, 0, 0)) { cout << target << "\n"; return 0; }
    }
    return 0;
}

