int n, chain[30], limit;

// chain[0..k] is built; can we reach n within `limit` additions?
bool dfs(int k) {
    if (chain[k] == n) return true;
    if (k == limit) return false;
    if ((1LL * chain[k] << (limit - k)) < n) return false;      // even doubling is too slow
    for (int i = k; i >= 0; i--)
        for (int j = i; j >= 0; j--) {
            int next = chain[i] + chain[j];
            if (next <= chain[k] || next > n) continue;      // keep it increasing
            chain[k + 1] = next;
            if (dfs(k + 1)) return true;
        }
    return false;
}

