#include <bits/stdc++.h>
using namespace std;

const string goal = "123804765";
int gx[9], gy[9];                         // goal position of each tile

int h(const string &s) {                  // total Manhattan distance, blank excluded
    int d = 0;
    for (int i = 0; i < 9; i++)
        if (s[i] != '0') { int t = s[i] - '0'; d += abs(i / 3 - gx[t]) + abs(i % 3 - gy[t]); }
    return d;
}

int main() {
    for (int i = 0; i < 9; i++) { gx[goal[i] - '0'] = i / 3; gy[goal[i] - '0'] = i % 3; }
    string start;
    cin >> start;
    map<string, int> g;                   // best known cost to each state
    priority_queue<pair<int, string>, vector<pair<int, string>>, greater<pair<int, string>>> pq;
    g[start] = 0;
    pq.push(make_pair(h(start), start));
    int dx[4] = {-1, 1, 0, 0}, dy[4] = {0, 0, -1, 1};
    while (!pq.empty()) {
        string s = pq.top().second;
        int f = pq.top().first;
        pq.pop();
        if (s == goal) { cout << g[s] << "\n"; return 0; }
        if (f > g[s] + h(s)) continue;     // an outdated queue entry
        int z = s.find('0');
        for (int k = 0; k < 4; k++) {
            int nx = z / 3 + dx[k], ny = z % 3 + dy[k];
            if (nx < 0 || nx > 2 || ny < 0 || ny > 2) continue;
            string t = s;
            swap(t[z], t[nx * 3 + ny]);
            if (!g.count(t) || g[s] + 1 < g[t]) {
                g[t] = g[s] + 1;
                pq.push(make_pair(g[t] + h(t), t));
            }
        }
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int h[1000005], sz = 0;

void push(int x) {
    h[++sz] = x;
    for (int i = sz; i > 1 && h[i] < h[i / 2]; i /= 2) swap(h[i], h[i / 2]);   // sift up
}

void pop() {
    h[1] = h[sz--];                                  // last value to the root
    int i = 1;
    while (2 * i <= sz) {                            // sift down
        int c = 2 * i;
        if (c + 1 <= sz && h[c + 1] < h[c]) c++;     // the smaller child
        if (h[i] <= h[c]) break;
        swap(h[i], h[c]);
        i = c;
    }
}

