using namespace std;

long long a[100005], sum[400005], tag[400005];

void pushup(int p) { sum[p] = sum[2 * p] + sum[2 * p + 1]; }

void apply(int p, int l, int r, long long v) {   // add v to every element of node p
    sum[p] += v * (r - l + 1);
    tag[p] += v;
}

void pushdown(int p, int l, int r) {
    if (tag[p] == 0) return;
    int m = (l + r) / 2;
    apply(2 * p, l, m, tag[p]);
    apply(2 * p + 1, m + 1, r, tag[p]);
    tag[p] = 0;
}

void build(int p, int l, int r) {
    if (l == r) { sum[p] = a[l]; return; }
    int m = (l + r) / 2;
    build(2 * p, l, m);
    build(2 * p + 1, m + 1, r);
    pushup(p);
}

void update(int p, int l, int r, int x, int y, long long v) {
    if (y < l || r < x) return;                    // outside
    if (x <= l && r <= y) { apply(p, l, r, v); return; }   // fully inside
    pushdown(p, l, r);
    int m = (l + r) / 2;
    update(2 * p, l, m, x, y, v);
    update(2 * p + 1, m + 1, r, x, y, v);
    pushup(p);
}

long long query(int p, int l, int r, int x, int y) {
    if (y < l || r < x) return 0;
    if (x <= l && r <= y) return sum[p];
    pushdown(p, l, r);
    int m = (l + r) / 2;
    return query(2 * p, l, m, x, y) + query(2 * p + 1, m + 1, r, x, y);
}

