    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

long long P, a[100005], sum[400005], mul[400005], add[400005];

void apply(int p, int l, int r, long long m, long long c) {   // x -> x * m + c
    sum[p] = (sum[p] * m + c * (r - l + 1)) % P;
    mul[p] = mul[p] * m % P;
    add[p] = (add[p] * m + c) % P;
}

void pushdown(int p, int l, int r) {
    int m = (l + r) / 2;
    apply(2 * p, l, m, mul[p], add[p]);
    apply(2 * p + 1, m + 1, r, mul[p], add[p]);
    mul[p] = 1; add[p] = 0;
}

void build(int p, int l, int r) {
    mul[p] = 1; add[p] = 0;
    if (l == r) { sum[p] = a[l] % P; return; }
    int m = (l + r) / 2;
    build(2 * p, l, m); build(2 * p + 1, m + 1, r);
    sum[p] = (sum[2 * p] + sum[2 * p + 1]) % P;
}

void update(int p, int l, int r, int x, int y, long long m, long long c) {
    if (y < l || r < x) return;
    if (x <= l && r <= y) { apply(p, l, r, m, c); return; }
    pushdown(p, l, r);
    int md = (l + r) / 2;
    update(2 * p, l, md, x, y, m, c); update(2 * p + 1, md + 1, r, x, y, m, c);
    sum[p] = (sum[2 * p] + sum[2 * p + 1]) % P;
}

long long query(int p, int l, int r, int x, int y) {
    if (y < l || r < x) return 0;
    if (x <= l && r <= y) return sum[p];
    pushdown(p, l, r);
    int md = (l + r) / 2;
    return (query(2 * p, l, md, x, y) + query(2 * p + 1, md + 1, r, x, y)) % P;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, q;
    cin >> n >> q >> P;
    for (int i = 1; i <= n; i++) cin >> a[i];
    build(1, 1, n);
    while (q--) {
        int op, x, y;
        cin >> op >> x >> y;
        if (op == 1) { long long k; cin >> k; update(1, 1, n, x, y, k % P, 0); }   // multiply
        else if (op == 2) { long long k; cin >> k; update(1, 1, n, x, y, 1, k % P); }  // add
        else cout << query(1, 1, n, x, y) << "\n";
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

struct Node { long long sum, pre, suf, best; };   // best = max subarray inside
Node t[2000005];
long long a[500005];

Node merge(const Node &L, const Node &R) {
    Node res;
    res.sum = L.sum + R.sum;
    res.pre = max(L.pre, L.sum + R.pre);            // prefix may cross into R
    res.suf = max(R.suf, R.sum + L.suf);
    res.best = max(max(L.best, R.best), L.suf + R.pre);   // or crosses the middle
    return res;
}

void build(int p, int l, int r) {
    if (l == r) { t[p].sum = t[p].pre = t[p].suf = t[p].best = a[l]; return; }
    int m = (l + r) / 2;
    build(2 * p, l, m); build(2 * p + 1, m + 1, r);
    t[p] = merge(t[2 * p], t[2 * p + 1]);
}

void change(int p, int l, int r, int x, long long v) {
    if (l == r) { t[p].sum = t[p].pre = t[p].suf = t[p].best = v; return; }
    int m = (l + r) / 2;
    if (x <= m) change(2 * p, l, m, x, v); else change(2 * p + 1, m + 1, r, x, v);
    t[p] = merge(t[2 * p], t[2 * p + 1]);
}

Node query(int p, int l, int r, int x, int y) {   // [x, y] overlaps [l, r]
    if (x <= l && r <= y) return t[p];
    int m = (l + r) / 2;
    if (y <= m) return query(2 * p, l, m, x, y);
    if (x > m) return query(2 * p + 1, m + 1, r, x, y);
    return merge(query(2 * p, l, m, x, y), query(2 * p + 1, m + 1, r, x, y));
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, q;
    cin >> n >> q;
    for (int i = 1; i <= n; i++) cin >> a[i];
    build(1, 1, n);
    while (q--) {
        int k, x, y;
        cin >> k >> x >> y;
        if (k == 1) { if (x > y) swap(x, y); cout << query(1, 1, n, x, y).best << "\n"; }
        else change(1, 1, n, x, y);
    }
    return 0;
}

