    int mid = (l + r) / 2;
    ls[p] = build(l, mid);
    rs[p] = build(mid + 1, r);
    return p;
}

// a copy of tree `pre` with position pos set to v; returns the new root
int modify(int pre, int l, int r, int pos, int v) {
    int p = ++tot;
    ls[p] = ls[pre]; rs[p] = rs[pre]; val[p] = val[pre];   // copy the node
    if (l == r) { val[p] = v; return p; }
    int mid = (l + r) / 2;
    if (pos <= mid) ls[p] = modify(ls[pre], l, mid, pos, v);
    else rs[p] = modify(rs[pre], mid + 1, r, pos, v);
    return p;
}

int query(int p, int l, int r, int pos) {
    if (l == r) return val[p];
    int mid = (l + r) / 2;
    if (pos <= mid) return query(ls[p], l, mid, pos);
    return query(rs[p], mid + 1, r, pos);
}

