const int N = 200005;
int n, m, K, a[N], rt[N];
const int POOL = 20000000;                             // about (n + 2m)·log n·log K nodes
int ls[POOL], rs[POOL], cnt[POOL], tot = 0;
char op[N];
int qa[N], qb[N], qc[N];
vector<int> v, A, B;

int id(int x) { return lower_bound(v.begin(), v.end(), x) - v.begin() + 1; }

void upd(int &p, int l, int r, int x, int d) {          // created on demand
    if (!p) p = ++tot;
    cnt[p] += d;
    if (l == r) return;
    int mid = (l + r) / 2;
    if (x <= mid) upd(ls[p], l, mid, x, d);
    else upd(rs[p], mid + 1, r, x, d);
}

void change(int i, int x, int d) { for (; i <= n; i += i & -i) upd(rt[i], 1, K, x, d); }

int kth(int l, int r, int k) {
    A.clear(); B.clear();
    for (int i = r; i > 0; i -= i & -i) A.push_back(rt[i]);       // + these trees
    for (int i = l - 1; i > 0; i -= i & -i) B.push_back(rt[i]);   // - these trees
    int lo = 1, hi = K;
    while (lo < hi) {
        int mid = (lo + hi) / 2, left = 0;
        for (int j = 0; j < int(A.size()); j++) left += cnt[ls[A[j]]];
        for (int j = 0; j < int(B.size()); j++) left -= cnt[ls[B[j]]];
        bool goLeft = k <= left;
        if (!goLeft) k -= left;
        for (int j = 0; j < int(A.size()); j++) A[j] = goLeft ? ls[A[j]] : rs[A[j]];
        for (int j = 0; j < int(B.size()); j++) B[j] = goLeft ? ls[B[j]] : rs[B[j]];
        if (goLeft) hi = mid; else lo = mid + 1;
    }
    return lo;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> n >> m;
    for (int i = 1; i <= n; i++) { cin >> a[i]; v.push_back(a[i]); }
    for (int i = 1; i <= m; i++) {                       // read all first: new values too
        cin >> op[i];
        if (op[i] == 'Q') cin >> qa[i] >> qb[i] >> qc[i];
        else { cin >> qa[i] >> qb[i]; v.push_back(qb[i]); }
    }
    sort(v.begin(), v.end());
    v.erase(unique(v.begin(), v.end()), v.end());
    K = v.size();
    for (int i = 1; i <= n; i++) change(i, id(a[i]), 1);
    for (int i = 1; i <= m; i++) {
        if (op[i] == 'Q') cout << v[kth(qa[i], qb[i], qc[i]) - 1] << "\n";
        else {
            change(qa[i], id(a[qa[i]]), -1);             // remove the old value
            a[qa[i]] = qb[i];
            change(qa[i], id(a[qa[i]]), 1);              // add the new one 
        }
    }
    return 0;
}

