const int N = 500005, LOG = 20;
vector<int> g[N];
int dep[N], up[N][LOG];

void dfs(int u, int parent) {
    up[u][0] = parent;
    for (int k = 1; k < LOG; k++) up[u][k] = up[up[u][k - 1]][k - 1];
    for (int i = 0; i < int(g[u].size()); i++) {
        int v = g[u][i];
        if (v == parent) continue;
        dep[v] = dep[u] + 1;
        dfs(v, u);
    }
}

int lca(int u, int v) {
    if (dep[u] < dep[v]) swap(u, v);
    for (int k = LOG - 1; k >= 0; k--)               // lift u to v's depth
        if (dep[u] - (1 << k) >= dep[v]) u = up[u][k];
    if (u == v) return u;
    for (int k = LOG - 1; k >= 0; k--)               // jump both, staying below the LCA
        if (up[u][k] != up[v][k]) { u = up[u][k]; v = up[v][k]; }
    return up[u][0];
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m, root;
    cin >> n >> m >> root;
    for (int i = 1; i < n; i++) {
        int u, v;
        cin >> u >> v;
        g[u].push_back(v);
        g[v].push_back(u);
    }
    dfs(root, 0);                                    // up[root][*] = 0, a sentinel
    while (m--) {
        int u, v;
        cin >> u >> v;
        int a = lca(u, v);
        cout << a << " (distance " << dep[u] + dep[v] - 2 * dep[a] << ")\n";
    }
    return 0;
}

