const int N = 50005, LOG = 17;
vector<int> g[N];
int dep[N], up[N][LOG], cnt[N], best = 0;

void dfs(int u, int parent) {
    up[u][0] = parent;
    for (int k = 1; k < LOG; k++) up[u][k] = up[up[u][k - 1]][k - 1];
    for (int i = 0; i < int(g[u].size()); i++) {
        int v = g[u][i];
        if (v != parent) { dep[v] = dep[u] + 1; dfs(v, u); }
    }
}

int lca(int u, int v) {
    if (dep[u] < dep[v]) swap(u, v);
    for (int k = LOG - 1; k >= 0; k--) if (dep[u] - (1 << k) >= dep[v]) u = up[u][k];
    if (u == v) return u;
    for (int k = LOG - 1; k >= 0; k--) if (up[u][k] != up[v][k]) { u = up[u][k]; v = up[v][k]; }
    return up[u][0];
}

void sum(int u, int parent) {                  // subtree sums turn marks into counts
    for (int i = 0; i < int(g[u].size()); i++) {
        int v = g[u][i];
        if (v != parent) { sum(v, u); cnt[u] += cnt[v]; }
    }
    best = max(best, cnt[u]);
}

int main() {
