    }
    dfs(1, 0);
    while (k--) {
        int s, t;
        cin >> s >> t;
        int a = lca(s, t);
        cnt[s]++; cnt[t]++; cnt[a]--; cnt[up[a][0]]--;   // +1 on every node of s..t
    }
    sum(1, 0);
    cout << best << "\n";
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

const int N = 100005;
int n, m, root;
long long P, a[N];
vector<int> g[N];
int fa[N], dep[N], sz[N], son[N], top[N], dfn[N], cnt = 0;
long long w[N], sum[4 * N], tag[4 * N];

void dfs1(int u, int parent) {                    // fa, dep, sz, heavy son
    fa[u] = parent; dep[u] = dep[parent] + 1; sz[u] = 1;
    for (int i = 0; i < int(g[u].size()); i++) {
        int v = g[u][i];
        if (v == parent) continue;
        dfs1(v, u);
        sz[u] += sz[v];
        if (sz[v] > sz[son[u]]) son[u] = v;
    }
}

void dfs2(int u, int t) {                         // t = top of u's chain
    top[u] = t; dfn[u] = ++cnt; w[cnt] = a[u];
    if (son[u]) dfs2(son[u], t);                  // heavy son first: same chain
    for (int i = 0; i < int(g[u].size()); i++) {
        int v = g[u][i];
        if (v != fa[u] && v != son[u]) dfs2(v, v);    // light son starts a chain
    }
}

// ---- segment tree over dfn: range add, range sum ( 第 6 章 ) ----
void apply(int p, int l, int r, long long v) { sum[p] = (sum[p] + v * (r - l + 1)) % P; tag[p] = (tag[p] + v) % P; }
void push(int p, int l, int r) {
    int mid = (l + r) / 2;
    if (tag[p]) { apply(2 * p, l, mid, tag[p]); apply(2 * p + 1, mid + 1, r, tag[p]); tag[p] = 0; }
}
void build(int p, int l, int r) {
    if (l == r) { sum[p] = w[l] % P; return; }
    int mid = (l + r) / 2;
    build(2 * p, l, mid); build(2 * p + 1, mid + 1, r);
    sum[p] = (sum[2 * p] + sum[2 * p + 1]) % P;
}
void add(int p, int l, int r, int x, int y, long long v) {
    if (y < l || r < x) return;
    if (x <= l && r <= y) { apply(p, l, r, v); return; }
    push(p, l, r);
    int mid = (l + r) / 2;
    add(2 * p, l, mid, x, y, v); add(2 * p + 1, mid + 1, r, x, y, v);
    sum[p] = (sum[2 * p] + sum[2 * p + 1]) % P;
}
long long ask(int p, int l, int r, int x, int y) {
    if (y < l || r < x) return 0;
    if (x <= l && r <= y) return sum[p];
    push(p, l, r);
    int mid = (l + r) / 2;
    return (ask(2 * p, l, mid, x, y) + ask(2 * p + 1, mid + 1, r, x, y)) % P;
}

// ---- paths: climb chain by chain ----
void pathAdd(int x, int y, long long v) {
    while (top[x] != top[y]) { 
        if (dep[top[x]] < dep[top[y]]) swap(x, y);   // move the deeper chain top
        add(1, 1, n, dfn[top[x]], dfn[x], v);
        x = fa[top[x]];
    }
    if (dep[x] > dep[y]) swap(x, y);
    add(1, 1, n, dfn[x], dfn[y], v);               // same chain now
}
long long pathSum(int x, int y) {
    long long s = 0;
    while (top[x] != top[y]) {
        if (dep[top[x]] < dep[top[y]]) swap(x, y);
        s += ask(1, 1, n, dfn[top[x]], dfn[x]);
        x = fa[top[x]];
    }
    if (dep[x] > dep[y]) swap(x, y);
    return (s + ask(1, 1, n, dfn[x], dfn[y])) % P;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> n >> m >> root >> P;
    for (int i = 1; i <= n; i++) cin >> a[i];
    for (int i = 1; i < n; i++) {
        int u, v;
        cin >> u >> v;
        g[u].push_back(v);
        g[v].push_back(u);
    }
    dfs1(root, 0);
    dfs2(root, root);
    build(1, 1, n);
    while (m--) {
        int op, x, y;
        long long z;
        cin >> op;
        if (op == 1) { cin >> x >> y >> z; pathAdd(x, y, z % P); }
        else if (op == 2) { cin >> x >> y; cout << pathSum(x, y) << "\n"; }
        else if (op == 3) { cin >> x >> z; add(1, 1, n, dfn[x], dfn[x] + sz[x] - 1, z % P); }  // subtree
        else { cin >> x; cout << ask(1, 1, n, dfn[x], dfn[x] + sz[x] - 1) << "\n"; }
    }
    return 0;
}

