const int N = 100005;
vector<pair<int, int>> g[N];                 // (to, weight)
long long dist[N];
bool done[N];

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m, s;
    cin >> n >> m >> s;
    for (int i = 0; i < m; i++) {
        int u, v, w;
        cin >> u >> v >> w;
        g[u].push_back(make_pair(v, w));     // directed
    }
    for (int i = 1; i <= n; i++) dist[i] = LLONG_MAX;
    // (distance, node), smallest distance on top
    priority_queue<pair<long long, int>, vector<pair<long long, int>>, greater<pair<long long, int>>> pq;
    dist[s] = 0;
    pq.push(make_pair(0LL, s));
    while (!pq.empty()) {
        int u = pq.top().second;
        pq.pop();
        if (done[u]) continue;               // an outdated entry
        done[u] = true;
        for (int k = 0; k < int(g[u].size()); k++) {
            int v = g[u][k].first, w = g[u][k].second;
            if (dist[u] + w < dist[v]) {     // relax
                dist[v] = dist[u] + w;
                pq.push(make_pair(dist[v], v));
            }
        }
    }
    for (int i = 1; i <= n; i++) cout << dist[i] << " ";
    cout << "\n";
    return 0;
}

