const int N = 10005, K = 11;
vector<pair<int, int>> g[N];
long long dist[N][K];                        // dist[v][j]: at v, j free flights used
bool done[N][K];

int main() {
    int n, m, k, s, t;
    cin >> n >> m >> k >> s >> t;
    for (int i = 0; i < m; i++) {
        int a, b, c;
        cin >> a >> b >> c;
        g[a].push_back(make_pair(b, c));
        g[b].push_back(make_pair(a, c));
    }
    for (int v = 0; v < n; v++) for (int j = 0; j <= k; j++) dist[v][j] = LLONG_MAX;
    priority_queue<pair<long long, pair<int, int>>, vector<pair<long long, pair<int, int>>>,
                   greater<pair<long long, pair<int, int>>>> pq;
    dist[s][0] = 0;
    pq.push(make_pair(0LL, make_pair(s, 0)));
    while (!pq.empty()) {
        int u = pq.top().second.first, j = pq.top().second.second;
        pq.pop();
        if (done[u][j]) continue;
        done[u][j] = true;
        for (int e = 0; e < int(g[u].size()); e++) {
            int v = g[u][e].first, w = g[u][e].second;
            if (dist[u][j] + w < dist[v][j]) {                       // pay
                dist[v][j] = dist[u][j] + w;
                pq.push(make_pair(dist[v][j], make_pair(v, j)));
            }
            if (j < k && dist[u][j] < dist[v][j + 1]) {             // fly free: next layer
                dist[v][j + 1] = dist[u][j];
                pq.push(make_pair(dist[v][j + 1], make_pair(v, j + 1)));
            }
        }
    }
    long long best = LLONG_MAX;
    for (int j = 0; j <= k; j++) best = min(best, dist[t][j]);
    cout << best << "\n";
    return 0;
}

