int main() {
    int n, m;
    cin >> n >> m;
    for (int i = 0; i < m; i++) {
        int a, b, c;
        cin >> a >> b >> c;
        g[a].push_back(make_pair(b, c));
        g[b].push_back(make_pair(a, c));
    }
    for (int i = 1; i <= n; i++) d1[i] = d2[i] = LLONG_MAX;
    priority_queue<pair<long long, int>, vector<pair<long long, int>>, greater<pair<long long, int>>> pq;
    d1[1] = 0;
    pq.push(make_pair(0LL, 1));
    while (!pq.empty()) {
        long long du = pq.top().first;
        int u = pq.top().second;
        pq.pop();
        if (du > d2[u]) continue;                    // outdated
        for (int k = 0; k < int(g[u].size()); k++) {
            int v = g[u][k].first;
            long long L = du + g[u][k].second;
            if (L < d1[v]) {                         // new best; old best becomes second
                swap(d1[v], L);
                pq.push(make_pair(d1[v], v));
            }
            if (L > d1[v] && L < d2[v]) {            // strictly between
                d2[v] = L;
                pq.push(make_pair(d2[v], v));
            }
        }
    }
    cout << d2[n] << "\n";
    return 0;
}

