    cin >> n >> m;
    const long long INF = 1e18;
    for (int i = 1; i <= n; i++)
        for (int j = 1; j <= n; j++) d[i][j] = (i == j ? 0 : INF);
    for (int i = 0; i < m; i++) {
        int u, v;
        long long w;
        cin >> u >> v >> w;
        d[u][v] = min(d[u][v], w);               // keep the cheapest parallel edge
        d[v][u] = min(d[v][u], w);
