#include <bits/stdc++.h>
using namespace std;

const int N = 10005, LOG = 15;
struct Edge { int u, v, w; };
bool heavier(const Edge &a, const Edge &b) { return a.w > b.w; }
int fa[N], dep[N], up[N][LOG], low[N][LOG], comp[N];
vector<pair<int, int>> g[N];
int find(int x) { return fa[x] == x ? x : fa[x] = find(fa[x]); }

void dfs(int u, int p, int w, int c) {
    comp[u] = c;
    up[u][0] = p; low[u][0] = w;               // low = smallest edge on the jump
    for (int k = 1; k < LOG; k++) {
        up[u][k] = up[up[u][k - 1]][k - 1];
        low[u][k] = min(low[u][k - 1], low[up[u][k - 1]][k - 1]);
    }
    for (int i = 0; i < int(g[u].size()); i++) {
        int v = g[u][i].first;
        if (v != p) { dep[v] = dep[u] + 1; dfs(v, u, g[u][i].second, c); }
    }
}

int query(int u, int v) {                      // smallest edge on the tree path u..v
    int r = INT_MAX;
    if (dep[u] < dep[v]) swap(u, v);
    for (int k = LOG - 1; k >= 0; k--)
        if (dep[u] - (1 << k) >= dep[v]) { r = min(r, low[u][k]); u = up[u][k]; }
    if (u == v) return r;
    for (int k = LOG - 1; k >= 0; k--)
        if (up[u][k] != up[v][k]) { r = min(r, min(low[u][k], low[v][k])); u = up[u][k]; v = up[v][k]; }
    return min(r, min(low[u][0], low[v][0]));
}

int main() {
    int n, m;
    cin >> n >> m;
    vector<Edge> e(m);
    for (int i = 0; i < m; i++) cin >> e[i].u >> e[i].v >> e[i].w;
    sort(e.begin(), e.end(), heavier);         // MAXIMUM spanning forest
    for (int i = 1; i <= n; i++) fa[i] = i;
    for (int i = 0; i < m; i++) {
        int a = find(e[i].u), b = find(e[i].v);
        if (a == b) continue;
        fa[a] = b;
        g[e[i].u].push_back(make_pair(e[i].v, e[i].w));
        g[e[i].v].push_back(make_pair(e[i].u, e[i].w));
    }
    for (int i = 0; i < LOG; i++) low[0][i] = INT_MAX;
    for (int i = 1; i <= n; i++) if (!comp[i]) dfs(i, 0, INT_MAX, i);   // each tree
    int q;
    cin >> q;
    while (q--) {
        int x, y;
        cin >> x >> y;
        if (comp[x] != comp[y]) cout << -1 << "\n";
        else cout << query(x, y) << "\n";
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

const int N = 100005, LOG = 17;
struct Edge { int u, v; long long w; bool inTree; };
bool byWeight(const Edge &a, const Edge &b) { return a.w < b.w; }
int fa[N], dep[N], up[N][LOG];
long long m1[N][LOG], m2[N][LOG];               // largest, strictly second largest
vector<pair<int, long long>> g[N];
int find(int x) { return fa[x] == x ? x : fa[x] = find(fa[x]); }

void add(long long &a, long long &b, long long x) {   // put x into the pair (a > b)
    if (x > a) { b = a; a = x; }
    else if (x < a && x > b) b = x;
}

void dfs(int u, int p) {
    for (int k = 1; k < LOG; k++) {
        int mid = up[u][k - 1];
        up[u][k] = up[mid][k - 1];
        m1[u][k] = m1[u][k - 1]; m2[u][k] = m2[u][k - 1];
        add(m1[u][k], m2[u][k], m1[mid][k - 1]);
        add(m1[u][k], m2[u][k], m2[mid][k - 1]);
    }
    for (int i = 0; i < int(g[u].size()); i++) {
        int v = g[u][i].first;
        if (v == p) continue;
        dep[v] = dep[u] + 1; up[v][0] = u; m1[v][0] = g[u][i].second; m2[v][0] = -1;
        dfs(v, u);
    }
}

void pathMax(int u, int v, long long &a, long long &b) {   // top two on path u..v
    a = b = -1;
    if (dep[u] < dep[v]) swap(u, v);
    for (int k = LOG - 1; k >= 0; k--)
        if (dep[u] - (1 << k) >= dep[v]) { add(a, b, m1[u][k]); add(a, b, m2[u][k]); u = up[u][k]; }
    if (u == v) return;
    for (int k = LOG - 1; k >= 0; k--)
        if (up[u][k] != up[v][k]) {
            add(a, b, m1[u][k]); add(a, b, m2[u][k]); add(a, b, m1[v][k]); add(a, b, m2[v][k]);
            u = up[u][k]; v = up[v][k];
        }
    add(a, b, m1[u][0]); add(a, b, m1[v][0]);
}

int main() {
    int n, m;
    cin >> n >> m;
    vector<Edge> e(m);
    for (int i = 0; i < m; i++) { cin >> e[i].u >> e[i].v >> e[i].w; e[i].inTree = false; }
    sort(e.begin(), e.end(), byWeight);
    for (int i = 1; i <= n; i++) fa[i] = i;
    long long mst = 0;
    for (int i = 0; i < m; i++) {
        int a = find(e[i].u), b = find(e[i].v);
        if (a == b) continue;
        fa[a] = b; mst += e[i].w; e[i].inTree = true;
        g[e[i].u].push_back(make_pair(e[i].v, e[i].w));
        g[e[i].v].push_back(make_pair(e[i].u, e[i].w));
    }
    for (int k = 0; k < LOG; k++) m1[1][k] = m2[1][k] = -1; 
    dfs(1, 0);
    long long best = LLONG_MAX;
    for (int i = 0; i < m; i++) {
        if (e[i].inTree || e[i].u == e[i].v) continue;
        long long a, b;
        pathMax(e[i].u, e[i].v, a, b);
        if (e[i].w > a) best = min(best, mst - a + e[i].w);           // swap out the largest
        else if (b != -1) best = min(best, mst - b + e[i].w);        // w == a: use the second
    }
    cout << best << "\n";
    return 0;
}

