const int N = 20005;
vector<int> g[N];
int dfn[N], low[N], timer = 0;
bool cut[N];

void tarjan(int u, int root) {
    dfn[u] = low[u] = ++timer;
    int children = 0;
    for (int k = 0; k < int(g[u].size()); k++) {
        int v = g[u][k];
        if (!dfn[v]) {
            children++;
            tarjan(v, root);
            low[u] = min(low[u], low[v]);
            if (u != root && low[v] >= dfn[u]) cut[u] = true;
        } else low[u] = min(low[u], dfn[v]);   // the parent too: harmless here
    }
    if (u == root && children >= 2) cut[u] = true;
}

