const int N = 10005;
vector<int> g[N], dag[N];
int n, m, w[N], dfn[N], low[N], timer = 0, scc[N], cnt = 0;
long long sw[N], best[N];
bool onStack[N];
vector<int> stk;

void tarjan(int u) {
    dfn[u] = low[u] = ++timer;
    stk.push_back(u); onStack[u] = true;
    for (int k = 0; k < int(g[u].size()); k++) {
        int v = g[u][k];
        if (!dfn[v]) { tarjan(v); low[u] = min(low[u], low[v]); }
        else if (onStack[v]) low[u] = min(low[u], dfn[v]);   // finished SCCs are ignored
    }
    if (low[u] == dfn[u]) {                     // u is the root of an SCC
        cnt++;
        while (true) {
            int x = stk.back();
            stk.pop_back(); onStack[x] = false;
            scc[x] = cnt; sw[cnt] += w[x];
            if (x == u) break;
        }
    }
}

int main() {
    cin >> n >> m;
    for (int i = 1; i <= n; i++) cin >> w[i];
    vector<int> ea(m), eb(m);
    for (int i = 0; i < m; i++) { cin >> ea[i] >> eb[i]; g[ea[i]].push_back(eb[i]); }
    for (int i = 1; i <= n; i++) if (!dfn[i]) tarjan(i);
    for (int i = 0; i < m; i++)
        if (scc[ea[i]] != scc[eb[i]]) dag[scc[ea[i]]].push_back(scc[eb[i]]);
    long long ans = 0;
    for (int c = cnt; c >= 1; c--) {            // topological order: high numbers first
        best[c] = max(best[c], 0LL) + sw[c];    // best path ending in c
        ans = max(ans, best[c]);
        for (int k = 0; k < int(dag[c].size()); k++) {
            int t = dag[c][k];
            best[t] = max(best[t], best[c]);
        }
    }
    cout << ans << "\n";
    return 0;
}

