const int MOD = 1000000007;
int f[10005];
long long g[10005], h[10005];

int main() {
    int n, w;
    cin >> n >> w;
    vector<int> c(n);
    for (int i = 0; i < n; i++) cin >> c[i];
    // fewest coins
    for (int x = 1; x <= w; x++) {
        f[x] = INT_MAX;
        for (int i = 0; i < n; i++)
            if (c[i] <= x && f[x - c[i]] != INT_MAX) f[x] = min(f[x], f[x - c[i]] + 1);
    }
    // ordered ways: for each total, try every last coin
    g[0] = 1;
    for (int x = 1; x <= w; x++)
        for (int i = 0; i < n; i++)
            if (c[i] <= x) g[x] = (g[x] + g[x - c[i]]) % MOD;
    // unordered ways: coin types in a fixed order
    h[0] = 1;
    for (int i = 0; i < n; i++)
        for (int x = c[i]; x <= w; x++) h[x] = (h[x] + h[x - c[i]]) % MOD;
