int dx[4] = {1, -1, 0, 0}, dy[4] = {0, 0, 1, -1};

int longest(int x, int y) {                   // longest slide starting at (x, y)
    if (f[x][y]) return f[x][y];              // already known
    f[x][y] = 1;
    for (int k = 0; k < 4; k++) {
        int nx = x + dx[k], ny = y + dy[k];
        if (nx >= 1 && nx <= R && ny >= 1 && ny <= C && h[nx][ny] < h[x][y])
            f[x][y] = max(f[x][y], longest(nx, ny) + 1);
    }
    return f[x][y];
}

