const int MOD = 80112002;
const int N = 5005;
vector<int> g[N];
int indeg[N], outdeg[N];
long long ways[N];

int main() {
    int n, m;
    cin >> n >> m;
    for (int i = 0; i < m; i++) {
        int a, b;
        cin >> a >> b;                        // a is eaten by b: a -> b
        g[a].push_back(b);
        indeg[b]++; outdeg[a]++;
    }
    queue<int> q;
    for (int i = 1; i <= n; i++)
        if (indeg[i] == 0) { ways[i] = 1; q.push(i); }   // producers start chains
    long long ans = 0;
    while (!q.empty()) {
        int u = q.front();
        q.pop();
        if (outdeg[u] == 0) ans = (ans + ways[u]) % MOD;   // top consumer ends chains
        for (int k = 0; k < int(g[u].size()); k++) {
            int v = g[u][k];
            ways[v] = (ways[v] + ways[u]) % MOD;           // push forward
            if (--indeg[v] == 0) q.push(v);
        }
    }
    cout << ans << "\n";
    return 0;
}

