const int N = 100005;
int n;
long long c[N], cnt[N], down[N], all[N], total = 0;
vector<pair<int, int>> g[N];

void dfs1(int u, int p) {                        // cnt: cows in subtree; down: cost to bring them to u
    cnt[u] = c[u];
    for (int k = 0; k < int(g[u].size()); k++) {
        int v = g[u][k].first, w = g[u][k].second;
        if (v == p) continue;
        dfs1(v, u);
        cnt[u] += cnt[v];
        down[u] += down[v] + cnt[v] * w;
    }
}

void dfs2(int u, int p) {                        // move the meeting point from u to each child v
    for (int k = 0; k < int(g[u].size()); k++) {
        int v = g[u][k].first, w = g[u][k].second;
        if (v == p) continue;
        all[v] = all[u] + (total - 2 * cnt[v]) * w;   // cnt[v] cows get closer, the rest farther
        dfs2(v, u);
    }
}

int main() {
    cin >> n;
    for (int i = 1; i <= n; i++) { cin >> c[i]; total += c[i]; }
    for (int i = 1; i < n; i++) {
        int a, b, w;
        cin >> a >> b >> w;
        g[a].push_back(make_pair(b, w));
        g[b].push_back(make_pair(a, w));
    }
    dfs1(1, 0);
    all[1] = down[1];
    dfs2(1, 0);
    long long best = all[1];
    for (int i = 2; i <= n; i++) best = min(best, all[i]);
    cout << best << "\n";
    return 0;
}

