double solve(int u) {                         // expected remaining length from u
    if (seen[u]) return f[u];
    seen[u] = true;
    int d = g[u].size();
    f[u] = 0;
    for (int k = 0; k < d; k++)
        f[u] += (g[u][k].second + solve(g[u][k].first)) / d;
    return f[u];                              // d = 0 at the end: 0
}

