long long phi(long long n) {                     // O(sqrt n) by trial division
    long long r = n;
    for (long long p = 2; p * p <= n; p++)
        if (n % p == 0) {
            r = r / p * (p - 1);                 // multiply by (1 - 1/p), divide first
            while (n % p == 0) n /= p;
        }
    if (n > 1) r = r / n * (n - 1);              // one prime factor > sqrt(n) left
    return r;
}

