const double EPS = 1e-8;
double a[55][55];

int main() {
    int n;
    cin >> n;
    for (int i = 0; i < n; i++)
        for (int j = 0; j <= n; j++) cin >> a[i][j];     // last column: right-hand side
    int row = 0;
    for (int col = 0; col < n && row < n; col++) {
        int p = row;
        for (int i = row; i < n; i++) if (fabs(a[i][col]) > fabs(a[p][col])) p = i;   // largest pivot
        if (fabs(a[p][col]) < EPS) continue;             // no pivot: a free variable
        for (int j = 0; j <= n; j++) swap(a[p][j], a[row][j]);
        double piv = a[row][col];
        for (int j = col; j <= n; j++) a[row][j] /= piv;
        for (int i = 0; i < n; i++)
            if (i != row && fabs(a[i][col]) > EPS) {
                double f = a[i][col];
                for (int j = col; j <= n; j++) a[i][j] -= f * a[row][j];
            }
        row++;
    }
    for (int i = row; i < n; i++)                        // rows that became all zero on the left
        if (fabs(a[i][n]) > EPS) { cout << -1 << "\n"; return 0; }   // 0 = non-zero: no solution
    if (row < n) { cout << 0 << "\n"; return 0; }        // a free variable: infinitely many
    for (int i = 0; i < n; i++) cout << "x" << i + 1 << "=" << fixed << setprecision(2) << a[i][n] << "\n";
    return 0;
}

