    long long det = 1;
    for (int c = 0; c < n; c++) {
        for (int i = c + 1; i < n; i++) {
            while (a[i][c] != 0) {                      // Euclid on rows c and i: no inverses needed
                long long t = a[c][c] / a[i][c];
                for (int j = c; j < n; j++) a[c][j] = ((a[c][j] - t * a[i][j]) % p + p) % p;
                for (int j = c; j < n; j++) swap(a[c][j], a[i][j]);
                det = (p - det) % p;                    // a row swap flips the sign
            }
        }
        det = det * a[c][c] % p;                        // triangular: product of the diagonal
    }
