using namespace std;

const long long INF = LLONG_MAX;
struct Edge { int to; long long cap; };
vector<Edge> e;                    // edge i and i ^ 1 are a pair (forward, reverse)
vector<int> g[205];
int n, m, s, t, level[205], it[205];

void addEdge(int u, int v, long long c) {
    g[u].push_back(e.size()); e.push_back(Edge{v, c});
    g[v].push_back(e.size()); e.push_back(Edge{u, 0});    // reverse edge starts empty
}

bool bfs() {                        // levels in the residual network
    fill(level, level + n + 1, -1);
    queue<int> q;
    level[s] = 0; q.push(s);
    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (int k = 0; k < int(g[u].size()); k++) {
            Edge &x = e[g[u][k]];
            if (x.cap > 0 && level[x.to] < 0) { level[x.to] = level[u] + 1; q.push(x.to); }
        }
    }
    return level[t] >= 0;
}

long long dfs(int u, long long f) { // push at most f from u towards t
    if (u == t) return f;
    for (int &k = it[u]; k < int(g[u].size()); k++) {     // current-arc: never retry a dead edge
        int id = g[u][k];
        Edge &x = e[id];
        if (x.cap > 0 && level[x.to] == level[u] + 1) {
            long long got = dfs(x.to, min(f, x.cap));
            if (got > 0) { x.cap -= got; e[id ^ 1].cap += got; return got; }
        }
    }
    return 0;
}

int main() {
    cin >> n >> m >> s >> t;
    for (int i = 0; i < m; i++) { int u, v; long long c; cin >> u >> v >> c; addEdge(u, v, c); }
    long long flow = 0;
    while (bfs()) {
        fill(it, it + n + 1, 0);
        while (long long f = dfs(s, INF)) flow += f;
    }
    cout << flow << "\n";
    return 0;
}

