#include <bits/stdc++.h>
using namespace std;

struct Edge { int to; long long cap, cost; };
vector<Edge> e;
vector<int> g[5005];
int n, m, s, t, pre[5005];
long long dist[5005], push_[5005];
bool inq[5005];

void addEdge(int u, int v, long long c, long long w) {
    g[u].push_back(e.size()); e.push_back(Edge{v, c, w});
    g[v].push_back(e.size()); e.push_back(Edge{u, 0, -w});    // undo = refund the cost
}

bool spfa() {                                     // cheapest path s -> t with room left
    fill(dist, dist + n + 1, LLONG_MAX);
    queue<int> q;
    dist[s] = 0; push_[s] = LLONG_MAX; q.push(s); inq[s] = true;
    while (!q.empty()) {
        int u = q.front(); q.pop(); inq[u] = false;
        for (int k = 0; k < int(g[u].size()); k++) {
            int id = g[u][k]; Edge &x = e[id];
            if (x.cap > 0 && dist[u] + x.cost < dist[x.to]) {
                dist[x.to] = dist[u] + x.cost;
                pre[x.to] = id;                   // edge used to reach x.to
                push_[x.to] = min(push_[u], x.cap);
                if (!inq[x.to]) { q.push(x.to); inq[x.to] = true; }
            }
        }
    }
    return dist[t] != LLONG_MAX;
}

int main() {
    cin >> n >> m >> s >> t;
    for (int i = 0; i < m; i++) { int u, v; long long c, w; cin >> u >> v >> c >> w; addEdge(u, v, c, w); }
    long long flow = 0, cost = 0;
    while (spfa()) {
        long long f = push_[t];
        flow += f; cost += f * dist[t];
        for (int v = t; v != s; v = e[pre[v] ^ 1].to) {   // walk the path back
            e[pre[v]].cap -= f;
            e[pre[v] ^ 1].cap += f;
        }
    }
    cout << flow << " " << cost << "\n";
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

const int N = 1000005;
int ch[N][26], fail[N], endCnt[N], tot = 0;

void insert(const string &w) {
    int u = 0;
    for (int i = 0; i < int(w.size()); i++) {
        int c = w[i] - 'a';
        if (!ch[u][c]) ch[u][c] = ++tot;
        u = ch[u][c];
    }
    endCnt[u]++;                                    // patterns may repeat
}

void build() {
    queue<int> q;
    for (int c = 0; c < 26; c++) if (ch[0][c]) q.push(ch[0][c]);   // fail = root
    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (int c = 0; c < 26; c++) {
            int v = ch[u][c];
            if (v) { fail[v] = ch[fail[u]][c]; q.push(v); }
            else ch[u][c] = ch[fail[u]][c];         // complete the trie graph
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    for (int i = 0; i < n; i++) { string w; cin >> w; insert(w); }
    build();
    string s;
    cin >> s;
    int u = 0, ans = 0;
    for (int i = 0; i < int(s.size()); i++) {
        u = ch[u][s[i] - 'a'];
        for (int v = u; v && endCnt[v] != -1; v = fail[v]) {   // every suffix that is a pattern
            ans += endCnt[v];
            endCnt[v] = -1;                                       // count each pattern once
        }
    }
    cout << ans << "\n";
    return 0;
}

