    for (int c = 0; c < 26; c++) if (ch[0][c]) q.push(ch[0][c]);
    while (!q.empty()) {
        int u = q.front(); q.pop();
        bad[u] = bad[u] || bad[fail[u]];              // a pattern ends on the fail chain
        for (int c = 0; c < 26; c++) {
            int v = ch[u][c];
            if (v) { fail[v] = ch[fail[u]][c]; q.push(v); }
            else ch[u][c] = ch[fail[u]][c];
        }
    }
    f[0][0] = 1;
    for (int i = 0; i < m; i++)
        for (int u = 0; u <= tot; u++) {
            if (!f[i][u] || bad[u]) continue;
            for (int c = 0; c < 26; c++) {
                int v = ch[u][c];
                if (!bad[v]) f[i + 1][v] = (f[i + 1][v] + f[i][u]) % MOD;   // stay safe
            }
        }
    int safe = 0, all = 1;
    for (int u = 0; u <= tot; u++) safe = (safe + f[m][u]) % MOD;
    for (int i = 0; i < m; i++) all = all * 26 % MOD;
    cout << ((all - safe) % MOD + MOD) % MOD << "\n";  // contain at least one = all - none
    return 0;
}

