const long long M1 = 1000000007, M2 = 998244353, B = 131;

pair<long long, long long> hashOf(const string &s) {
    long long a = 0, b = 0;
    for (int i = 0; i < int(s.size()); i++) {
        a = (a * B + s[i]) % M1;                 // two independent hashes
        b = (b * B + s[i]) % M2;
    }
    return make_pair(a, b);
}

