    for (int i = 1; i < n - 1; i++) {
        if (i < r) p[i] = min(r - i, p[2 * c - i]);   // mirror inside the known palindrome
        while (t[i + p[i] + 1] == t[i - p[i] - 1]) p[i]++;
        if (i + p[i] > r) { c = i; r = i + p[i]; }
        best = max(best, p[i]);                       // radius in t = length in s
    }
    cout << best << "\n";
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    string s;
    cin >> s;
    int n = s.size(), m = 128;                        // m: number of different ranks
    vector<int> sa(n), rk(n), tmp(n), cnt(max(n, m) + 1);
    for (int i = 0; i < n; i++) cnt[rk[i] = s[i]]++;
    for (int i = 1; i <= m; i++) cnt[i] += cnt[i - 1];
    for (int i = n - 1; i >= 0; i--) sa[--cnt[rk[i]]] = i;
    for (int k = 1; ; k <<= 1) {
        int p = 0;                                    // order by the second key (rank of i + k)
        for (int i = n - k; i < n; i++) tmp[p++] = i;            // no second half: smallest
        for (int i = 0; i < n; i++) if (sa[i] >= k) tmp[p++] = sa[i] - k;
        fill(cnt.begin(), cnt.end(), 0);              // stable counting sort by the first key
        for (int i = 0; i < n; i++) cnt[rk[i]]++;
        for (int i = 1; i <= m; i++) cnt[i] += cnt[i - 1];
        for (int i = n - 1; i >= 0; i--) sa[--cnt[rk[tmp[i]]]] = tmp[i];
        tmp[sa[0]] = 1; p = 1;                        // new ranks (tmp reused)
        for (int i = 1; i < n; i++) {
            int a = sa[i - 1], b = sa[i];
            bool same = rk[a] == rk[b] && (a + k < n ? rk[a + k] : -1) == (b + k < n ? rk[b + k] : -1);
            tmp[b] = same ? p : ++p;
        }
        rk = tmp;
        if (p == n) break;                            // all ranks distinct: done
        m = p;
    }
    for (int i = 0; i < n; i++) rk[sa[i]] = i;        // 0-based rank
    vector<int> height(n, 0);
    for (int i = 0, h = 0; i < n; i++) {              // Kasai: text order
        if (rk[i] == 0) { h = 0; continue; }
        if (h > 0) h--;
        int j = sa[rk[i] - 1];
        while (i + h < n && j + h < n && s[i + h] == s[j + h]) h++;
        height[rk[i]] = h;
    }
    long long distinct = 1LL * n * (n + 1) / 2;
    for (int i = 0; i < n; i++) { cout << sa[i] + 1 << " "; distinct -= height[i]; }
    cout << "\n" << distinct << "\n";
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

const int N = 2000005;
int len_[N], link_[N], nxt[N][26], cnt[N], sz = 1, last = 0;   // state 0 = empty string

void extend(int c) {
    int cur = sz++;
    len_[cur] = len_[last] + 1;
    cnt[cur] = 1;                                     // a new end position
    int p = last;
    while (p != -1 && !nxt[p][c]) { nxt[p][c] = cur; p = link_[p]; }
    if (p == -1) link_[cur] = 0;
    else {
        int q = nxt[p][c];
        if (len_[p] + 1 == len_[q]) link_[cur] = q;
        else {                                        // split q: clone keeps the shorter strings
            int cl = sz++;
            len_[cl] = len_[p] + 1;
            memcpy(nxt[cl], nxt[q], sizeof(nxt[q]));
            link_[cl] = link_[q];
            while (p != -1 && nxt[p][c] == q) { nxt[p][c] = cl; p = link_[p]; }
            link_[q] = link_[cur] = cl;
        }
    }
    last = cur;
}

int main() {
    string s;
    cin >> s;
    link_[0] = -1;
    for (int i = 0; i < int(s.size()); i++) extend(s[i] - 'a');
    vector<int> order_(sz), bucket(s.size() + 1, 0);
    for (int v = 0; v < sz; v++) bucket[len_[v]]++;  // sort states by len (counting sort)
    for (int i = 1; i <= int(s.size()); i++) bucket[i] += bucket[i - 1];
    for (int v = sz - 1; v >= 0; v--) order_[--bucket[len_[v]]] = v;
    long long best = 0, distinct = 0;
    for (int i = sz - 1; i > 0; i--) {                // longest first: children before parents
        int v = order_[i];
        cnt[link_[v]] += cnt[v];
        if (cnt[v] > 1) best = max(best, 1LL * cnt[v] * len_[v]);
        distinct += len_[v] - len_[link_[v]];
    }
    cout << best << "\n" << distinct << "\n";
    return 0;
}

