}

#include <bits/stdc++.h>
using namespace std;

const int N = 100005;
int ls[N], rs[N], val[N], pri[N], sz[N], cnt = 0, root = 0;
mt19937 rng(20251117);

int newNode(int v) { val[++cnt] = v; pri[cnt] = rng(); sz[cnt] = 1; return cnt; }
void up(int t) { sz[t] = sz[ls[t]] + sz[rs[t]] + 1; }

void split(int t, int k, int &a, int &b) {          // a: keys <= k, b: keys > k
    if (!t) { a = b = 0; return; }
    if (val[t] <= k) { a = t; split(rs[t], k, rs[t], b); }
    else { b = t; split(ls[t], k, a, ls[t]); }
    up(t);
}
int merge(int a, int b) {                            // all keys of a <= all keys of b
    if (!a || !b) return a | b;
    if (pri[a] > pri[b]) { rs[a] = merge(rs[a], b); up(a); return a; }
    ls[b] = merge(a, ls[b]); up(b); return b;
}
int kth(int t, int k) {                              // k-th smallest in t
    while (true) {
        if (k <= sz[ls[t]]) t = ls[t];
        else if (k == sz[ls[t]] + 1) return val[t];
        else { k -= sz[ls[t]] + 1; t = rs[t]; }
    }
}

int main() {
    int n;
    cin >> n;
    while (n--) {
        int op, x, a, b, c;
        cin >> op >> x;
        if (op == 1) { split(root, x, a, b); root = merge(merge(a, newNode(x)), b); }
        else if (op == 2) {                          // remove ONE copy of x
            split(root, x, a, c); split(a, x - 1, a, b);
            b = merge(ls[b], rs[b]);
            root = merge(merge(a, b), c);
        }
        else if (op == 3) { split(root, x - 1, a, b); cout << sz[a] + 1 << "\n"; root = merge(a, b); }
        else if (op == 4) cout << kth(root, x) << "\n";
        else if (op == 5) { split(root, x - 1, a, b); cout << kth(a, sz[a]) << "\n"; root = merge(a, b); }
        else { split(root, x, a, b); cout << kth(b, 1) << "\n"; root = merge(a, b); }
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

const int N = 100005;
int ls[N], rs[N], pri[N], sz[N], val[N], cnt = 0;
bool rev[N];
mt19937 rng(7);

void up(int t) { sz[t] = sz[ls[t]] + sz[rs[t]] + 1; }
void down(int t) {                                   // push the reverse flag
    if (rev[t]) { swap(ls[t], rs[t]); rev[ls[t]] ^= 1; rev[rs[t]] ^= 1; rev[t] = false; }
}
void split(int t, int k, int &a, int &b) {          // a: first k elements
    if (!t) { a = b = 0; return; }
    down(t);
    if (sz[ls[t]] < k) { a = t; split(rs[t], k - sz[ls[t]] - 1, rs[t], b); }
    else { b = t; split(ls[t], k, a, ls[t]); }
    up(t);
}
int merge(int a, int b) {
    if (!a || !b) return a | b;
    if (pri[a] > pri[b]) { down(a); rs[a] = merge(rs[a], b); up(a); return a; }
    down(b); ls[b] = merge(a, ls[b]); up(b); return b;
}
void print(int t) {                                  // in-order = the sequence
    if (!t) return;
    down(t);
    print(ls[t]); cout << val[t] << " "; print(rs[t]);
}

int main() {
    int n, m, root = 0;
    cin >> n >> m;
    for (int i = 1; i <= n; i++) {
        val[++cnt] = i; pri[cnt] = rng(); sz[cnt] = 1;
        root = merge(root, cnt);                     // append at the end
    }
    while (m--) {
        int l, r, a, b, c;
        cin >> l >> r;
        split(root, r, a, c);                        // [1, r] and the rest
        split(a, l - 1, a, b);                       // [1, l-1] and [l, r]
        rev[b] ^= 1;
        root = merge(merge(a, b), c);
    }
    print(root);
    cout << "\n";
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int n, m, B, bl[100005];
long long a[100005], sum[400], add_[400];

void update(int l, int r, long long v) {
    if (bl[l] == bl[r]) { for (int i = l; i <= r; i++) { a[i] += v; sum[bl[i]] += v; } return; }
    for (int i = l; bl[i] == bl[l]; i++) { a[i] += v; sum[bl[i]] += v; }        // left end
    for (int i = r; bl[i] == bl[r]; i--) { a[i] += v; sum[bl[i]] += v; }        // right end
    for (int b = bl[l] + 1; b < bl[r]; b++) add_[b] += v;                       // whole blocks
}
long long query(int l, int r) {
    long long s = 0;
    if (bl[l] == bl[r]) { for (int i = l; i <= r; i++) s += a[i] + add_[bl[i]]; return s; }
    for (int i = l; bl[i] == bl[l]; i++) s += a[i] + add_[bl[i]];
    for (int i = r; bl[i] == bl[r]; i--) s += a[i] + add_[bl[i]];
    for (int b = bl[l] + 1; b < bl[r]; b++) s += sum[b] + add_[b] * B;          // full block of size B
    return s;
}

int main() {
    cin >> n >> m;
    B = max(1, int(sqrt(n)));
    for (int i = 1; i <= n; i++) { cin >> a[i]; bl[i] = (i - 1) / B; sum[bl[i]] += a[i]; }
    while (m--) {
        int op, x, y;
        cin >> op >> x >> y;
        if (op == 1) { long long k; cin >> k; update(x, y, k); }
        else cout << query(x, y) << "\n";
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int n, q, B, bl[1000005];
long long a[1000005], add_[1005];
vector<long long> sorted_[1005];                 // each block, sorted (without its add_)

void rebuild(int b) {
    sorted_[b].clear();
    for (int i = b * B + 1; i <= min(n, (b + 1) * B); i++) sorted_[b].push_back(a[i]);
    sort(sorted_[b].begin(), sorted_[b].end());
}

int main() {
    cin >> n >> q;
    B = max(1, int(sqrt(n)));
    for (int i = 1; i <= n; i++) { cin >> a[i]; bl[i] = (i - 1) / B; }
    for (int b = 0; b <= bl[n]; b++) rebuild(b);
    while (q--) {
        char op; int l, r; long long w;
        cin >> op >> l >> r >> w;
        if (op == 'M') {                         // add w to [l, r]
            if (bl[l] == bl[r]) { for (int i = l; i <= r; i++) a[i] += w; rebuild(bl[l]); continue; }
            for (int i = l; bl[i] == bl[l]; i++) a[i] += w;
            for (int i = r; bl[i] == bl[r]; i--) a[i] += w;
            rebuild(bl[l]); rebuild(bl[r]);
            for (int b = bl[l] + 1; b < bl[r]; b++) add_[b] += w;    // order inside is unchanged
        } else {                                 // how many in [l, r] are >= w
            int cnt = 0;
            if (bl[l] == bl[r]) { for (int i = l; i <= r; i++) cnt += a[i] + add_[bl[i]] >= w; }
            else {
                for (int i = l; bl[i] == bl[l]; i++) cnt += a[i] + add_[bl[i]] >= w;
                for (int i = r; bl[i] == bl[r]; i--) cnt += a[i] + add_[bl[i]] >= w;
                for (int b = bl[l] + 1; b < bl[r]; b++)          // binary search in the sorted block
                    cnt += sorted_[b].end() - lower_bound(sorted_[b].begin(), sorted_[b].end(), w - add_[b]);
            }
            cout << cnt << "\n";
        }
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int n, m, k, B, a[50005], cnt[50005];
long long cur = 0, ans[50005];
struct Q { int l, r, id; };

bool cmp(const Q &x, const Q &y) {
    if (x.l / B != y.l / B) return x.l / B < y.l / B;
    return (x.l / B) % 2 ? x.r > y.r : x.r < y.r;     // odd blocks: r goes back (fewer moves)
}
void add(int i) { cur += 2 * cnt[a[i]] + 1; cnt[a[i]]++; }      // (c+1)^2 - c^2
void remove_(int i) { cnt[a[i]]--; cur -= 2 * cnt[a[i]] + 1; }

int main() {
    cin >> n >> m >> k;
    B = max(1, int(sqrt(n)));
    for (int i = 1; i <= n; i++) cin >> a[i];
    vector<Q> qs(m);
    for (int i = 0; i < m; i++) { cin >> qs[i].l >> qs[i].r; qs[i].id = i; }
    sort(qs.begin(), qs.end(), cmp);
    int L = 1, R = 0;                                 // empty window
    for (int i = 0; i < m; i++) {
        while (R < qs[i].r) add(++R);                 // grow first,
        while (L > qs[i].l) add(--L);
        while (R > qs[i].r) remove_(R--);             // then shrink
        while (L < qs[i].l) remove_(L++);
        ans[qs[i].id] = cur;
    }
    for (int i = 0; i < m; i++) cout << ans[i] << "\n";
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

const int N = 10005, MAXK = 10000001;
vector<pair<int, int>> g[N];
int n, m, q[105], sz[N], mx[N], total, root;
bool removed[N], ok[105];
bool has[MAXK];                                   // distances seen from earlier pieces
vector<int> dists, allDists;

void findCentroid(int u, int p) {                 // root = node with the smallest largest piece
    sz[u] = 1; mx[u] = 0;
    for (int k = 0; k < int(g[u].size()); k++) {
        int v = g[u][k].first;
        if (v == p || removed[v]) continue;
        findCentroid(v, u);
        sz[u] += sz[v]; mx[u] = max(mx[u], sz[v]);
    }
    mx[u] = max(mx[u], total - sz[u]);
    if (mx[u] < mx[root]) root = u;
}
int pieceSize(int u, int p) {
    int s = 1;
    for (int k = 0; k < int(g[u].size()); k++) {
        int v = g[u][k].first;
        if (v != p && !removed[v]) s += pieceSize(v, u);
    }
    return s;
}
void collect(int u, int p, int d) {               // distances from the centroid in one piece
    if (d >= MAXK) return;
    dists.push_back(d);
    for (int k = 0; k < int(g[u].size()); k++) {
        int v = g[u][k].first;
        if (v != p && !removed[v]) collect(v, u, d + g[u][k].second);
    }
}
void solve(int c) {
    removed[c] = true;
    has[0] = true; allDists.push_back(0);         // the centroid itself
    for (int k = 0; k < int(g[c].size()); k++) {
        int v = g[c][k].first;
        if (removed[v]) continue;
        dists.clear();
        collect(v, c, g[c][k].second);
        for (int i = 0; i < int(dists.size()); i++)            // pair with earlier pieces only
            for (int j = 0; j < m; j++)
                if (q[j] >= dists[i] && has[q[j] - dists[i]]) ok[j] = true;
        for (int i = 0; i < int(dists.size()); i++) { has[dists[i]] = true; allDists.push_back(dists[i]); }
    }
    for (int i = 0; i < int(allDists.size()); i++) has[allDists[i]] = false;   // clean up cheaply
    allDists.clear();
    for (int k = 0; k < int(g[c].size()); k++) {
        int v = g[c][k].first;
        if (removed[v]) continue;
        total = pieceSize(v, c);                  // measure this piece afresh
        root = 0; mx[0] = INT_MAX;
        findCentroid(v, c);
        solve(root);
    }
} 

int main() {
    cin >> n >> m;
    for (int i = 1; i < n; i++) {
        int a, b, w; cin >> a >> b >> w;
        g[a].push_back(make_pair(b, w)); g[b].push_back(make_pair(a, w));
    }
    for (int j = 0; j < m; j++) cin >> q[j];
    total = n; root = 0; mx[0] = INT_MAX;
    findCentroid(1, 0);
    solve(root);
    for (int j = 0; j < m; j++) cout << (ok[j] ? "AYE" : "NAY") << "\n";
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

const int N = 100005;
vector<int> g[N];
int n, col[N], sz[N], heavy[N], cnt[N], distinctNow = 0, ans[N];

void sizes(int u, int p) {
    sz[u] = 1;
    for (int k = 0; k < int(g[u].size()); k++) {
        int v = g[u][k];
        if (v == p) continue;
        sizes(v, u); sz[u] += sz[v];
        if (sz[v] > sz[heavy[u]]) heavy[u] = v;
    }
}
void change(int u, int p, int d) {                // add (d = 1) or remove (d = -1) a whole subtree
    if (d == 1 && cnt[col[u]]++ == 0) distinctNow++;
    if (d == -1 && --cnt[col[u]] == 0) distinctNow--;
    for (int k = 0; k < int(g[u].size()); k++) if (g[u][k] != p) change(g[u][k], u, d);
}
void dfs(int u, int p, bool keep) {
    for (int k = 0; k < int(g[u].size()); k++) {  // light children: solve, then forget
        int v = g[u][k];
        if (v != p && v != heavy[u]) dfs(v, u, false);
    }
    if (heavy[u]) dfs(heavy[u], u, true);         // heavy child: keep its counts
    if (cnt[col[u]]++ == 0) distinctNow++;
    for (int k = 0; k < int(g[u].size()); k++) {  // add the light subtrees again
        int v = g[u][k];
        if (v != p && v != heavy[u]) change(v, u, 1);
    }
    ans[u] = distinctNow;
    if (!keep) change(u, p, -1);
}

int main() {
    cin >> n;
    for (int i = 1; i < n; i++) { int a, b; cin >> a >> b; g[a].push_back(b); g[b].push_back(a); }
    for (int i = 1; i <= n; i++) cin >> col[i];
    sizes(1, 0);
    dfs(1, 0, true);
    for (int i = 1; i <= n; i++) cout << ans[i] << " ";
    cout << "\n";
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

const int N = 250005, LOG = 19;
vector<pair<int, int>> g[N];
vector<int> vt[N];
int n, dep[N], up[N][LOG], dfn[N], timer_ = 0;
long long mn[N];                                  // cheapest edge on the path root -> v
bool key_[N];

void dfs(int u, int p) {
    dfn[u] = ++timer_;
    up[u][0] = p;
    for (int k = 1; k < LOG; k++) up[u][k] = up[up[u][k - 1]][k - 1];
    for (int i = 0; i < int(g[u].size()); i++) {
        int v = g[u][i].first;
        if (v == p) continue;
        dep[v] = dep[u] + 1;
        mn[v] = min(mn[u], 1LL * g[u][i].second);
        dfs(v, u);
    }
}
int lca(int a, int b) {
    if (dep[a] < dep[b]) swap(a, b);
    for (int k = LOG - 1; k >= 0; k--) if (dep[a] - (1 << k) >= dep[b]) a = up[a][k];
    if (a == b) return a;
    for (int k = LOG - 1; k >= 0; k--) if (up[a][k] != up[b][k]) { a = up[a][k]; b = up[b][k]; }
    return up[a][0];
}
bool byDfn(int a, int b) { return dfn[a] < dfn[b]; }

long long dp(int u) {                             // cheapest way to cut all key nodes below u from the root
    long long sub = 0;
    for (int i = 0; i < int(vt[u].size()); i++) sub += dp(vt[u][i]);
    vt[u].clear();                                // reset for the next query
    long long res = key_[u] ? mn[u] : min(mn[u], sub);
    key_[u] = false;
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> n;
    for (int i = 1; i < n; i++) {
        int a, b, w; cin >> a >> b >> w;
        g[a].push_back(make_pair(b, w)); g[b].push_back(make_pair(a, w));
    }
    mn[1] = LLONG_MAX;
    dfs(1, 0);
    int q;
    cin >> q;
    while (q--) {
        int k; cin >> k;
        vector<int> h(k);
        for (int i = 0; i < k; i++) { cin >> h[i]; key_[h[i]] = true; }
        sort(h.begin(), h.end(), byDfn);
        vector<int> st(1, 1);                     // stack = current root-to-leaf chain, root 1 always in
        for (int i = 0; i < k; i++) {
            int v = h[i], l = lca(v, st.back()); 
            while (st.size() >= 2 && dep[st[st.size() - 2]] >= dep[l]) {   // close finished branches
                vt[st[st.size() - 2]].push_back(st.back()); st.pop_back();
            }
            if (st.back() != l) { vt[l].push_back(st.back()); st.back() = l; }
            st.push_back(v);
        }
        while (st.size() >= 2) { vt[st[st.size() - 2]].push_back(st.back()); st.pop_back(); }
        long long ans = 0;
        for (int i = 0; i < int(vt[1].size()); i++) ans += dp(vt[1][i]);
        vt[1].clear();
        cout << ans << "\n";
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

const int N = 100005, K = 200005;
struct E { int a, b, c, cnt, res; };
E e[N], tmp[N];
int n, k, m, bit[K], ans[N];

void add(int i, int v) { for (; i <= k; i += i & -i) bit[i] += v; }
int sum(int i) { int s = 0; for (; i > 0; i -= i & -i) s += bit[i]; return s; }
bool byABC(const E &x, const E &y) {
    if (x.a != y.a) return x.a < y.a;
    if (x.b != y.b) return x.b < y.b;
    return x.c < y.c;
}

void cdq(int l, int r) {
    if (l == r) return;
    int mid = (l + r) / 2;
    cdq(l, mid); cdq(mid + 1, r);                 // each half is now sorted by b
    int i = l, p = l;
    for (int j = mid + 1; j <= r; j++) {          // right element j collects every left with b <= b_j
        while (i <= mid && e[i].b <= e[j].b) { add(e[i].c, e[i].cnt); tmp[p++] = e[i++]; }
        e[j].res += sum(e[j].c);
        tmp[p++] = e[j];
    }
    for (int t = l; t < i; t++) add(e[t].c, -e[t].cnt);   // undo the Fenwick changes
    while (i <= mid) tmp[p++] = e[i++];
    for (int t = l; t <= r; t++) e[t] = tmp[t];   // merge by b (merge sort on the way back)
}

int main() {
    cin >> n >> k;
    vector<E> raw(n);
    for (int i = 0; i < n; i++) { cin >> raw[i].a >> raw[i].b >> raw[i].c; raw[i].cnt = 1; raw[i].res = 0; }
    sort(raw.begin(), raw.end(), byABC);
    m = 0;                                        // merge identical triples (they all count each other)
    for (int i = 0; i < n; i++) {
        if (m > 0 && e[m].a == raw[i].a && e[m].b == raw[i].b && e[m].c == raw[i].c) e[m].cnt++;
        else e[++m] = raw[i];
    }
    cdq(1, m);
    for (int i = 1; i <= m; i++) ans[e[i].res + e[i].cnt - 1] += e[i].cnt;   // equal copies count too
    for (int d = 0; d < n; d++) cout << ans[d] << "\n";
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

const int N = 200005;
int n, m, bit[N], ans[N];
struct Item { int type, l, r, k, id; };      // type 0: value a[l] = k at position l; type 1: query

void add(int i, int v) { for (; i <= n; i += i & -i) bit[i] += v; }
int sum(int i) { int s = 0; for (; i > 0; i -= i & -i) s += bit[i]; return s; }

void solve(int lo, int hi, vector<Item> &v) {
    if (v.empty()) return;
    if (lo == hi) { for (int i = 0; i < int(v.size()); i++) if (v[i].type) ans[v[i].id] = lo; return; }
    int mid = lo + (hi - lo) / 2;
    vector<Item> L, R;
    for (int i = 0; i < int(v.size()); i++) {
        Item it = v[i];
        if (!it.type) {                           // a number: does it go left (<= mid)?
            if (it.k <= mid) { add(it.l, 1); L.push_back(it); } else R.push_back(it);
        } else {
            int c = sum(it.r) - sum(it.l - 1);    // numbers <= mid inside [l, r]
            if (it.k <= c) L.push_back(it);
            else { it.k -= c; R.push_back(it); }
        }
    }
    for (int i = 0; i < int(L.size()); i++) if (!L[i].type) add(L[i].l, -1);   // undo
    solve(lo, mid, L);
    solve(mid + 1, hi, R);
}

int main() {
    cin >> n >> m;
    vector<Item> v;
    for (int i = 1; i <= n; i++) { int x; cin >> x; v.push_back(Item{0, i, i, x, 0}); }
    for (int i = 0; i < m; i++) { int l, r, k; cin >> l >> r >> k; v.push_back(Item{1, l, r, k, i}); }
    solve(-1000000000, 1000000000, v);
    for (int i = 0; i < m; i++) cout << ans[i] << "\n";
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

typedef complex<double> cd;
const double PI = acos(-1.0);

void fft(vector<cd> &a, bool invert) {
    int n = a.size();
    for (int i = 1, j = 0; i < n; i++) {               // bit-reversal order: leaves of the recursion
        int bit = n >> 1;
        for (; j & bit; bit >>= 1) j ^= bit;
        j ^= bit;
        if (i < j) swap(a[i], a[j]);
    }
    for (int len = 2; len <= n; len <<= 1) {           // combine halves of size len / 2
        double ang = 2 * PI / len * (invert ? -1 : 1);
        cd wl(cos(ang), sin(ang));
        for (int i = 0; i < n; i += len) {
            cd w(1);
            for (int j = 0; j < len / 2; j++) {
                cd u = a[i + j], v = a[i + j + len / 2] * w;   // butterfly
                a[i + j] = u + v;
                a[i + j + len / 2] = u - v;
                w *= wl;
            }
        }
    }
    if (invert) for (int i = 0; i < n; i++) a[i] /= n;
}

int main() {
    int n, m;
    cin >> n >> m;                                     // degrees
    int N = 1;
    while (N < n + m + 1) N <<= 1;                     // room for the product, power of two
    vector<cd> a(N), b(N);
    for (int i = 0; i <= n; i++) { int x; cin >> x; a[i] = x; }
    for (int i = 0; i <= m; i++) { int x; cin >> x; b[i] = x; }
    fft(a, false); fft(b, false);
    for (int i = 0; i < N; i++) a[i] *= b[i];          // multiply the values
    fft(a, true);
    for (int i = 0; i <= n + m; i++) cout << llround(a[i].real()) << " ";   // round off errors
    cout << "\n";
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

const long long MOD = 998244353, G = 3;

long long power(long long a, long long b) {
    long long r = 1;
    for (a %= MOD; b > 0; b >>= 1, a = a * a % MOD) if (b & 1) r = r * a % MOD;
    return r;
}

void ntt(vector<long long> &a, bool invert) {
    int n = a.size();
    for (int i = 1, j = 0; i < n; i++) {
        int bit = n >> 1;
        for (; j & bit; bit >>= 1) j ^= bit;
        j ^= bit;
        if (i < j) swap(a[i], a[j]);
    }
    for (int len = 2; len <= n; len <<= 1) {
        long long wl = power(G, (MOD - 1) / len);      // a len-th root of unity mod p
        if (invert) wl = power(wl, MOD - 2);
        for (int i = 0; i < n; i += len) {
            long long w = 1;
            for (int j = 0; j < len / 2; j++) {
                long long u = a[i + j], v = a[i + j + len / 2] * w % MOD;
                a[i + j] = (u + v) % MOD;
                a[i + j + len / 2] = (u - v + MOD) % MOD;
                w = w * wl % MOD;
            }
        }
    }
    if (invert) {
        long long inv = power(n, MOD - 2);
        for (int i = 0; i < n; i++) a[i] = a[i] * inv % MOD;
    }
}

int main() {
    string s, t;
    cin >> s >> t;
    int N = 1;
    while (N < int(s.size() + t.size())) N <<= 1;
    vector<long long> a(N, 0), b(N, 0);
    for (int i = 0; i < int(s.size()); i++) a[i] = s[s.size() - 1 - i] - '0';   // lowest digit first
    for (int i = 0; i < int(t.size()); i++) b[i] = t[t.size() - 1 - i] - '0';
    ntt(a, false); ntt(b, false);
    for (int i = 0; i < N; i++) a[i] = a[i] * b[i] % MOD;
    ntt(a, true);
    for (int i = 0; i + 1 < N; i++) { a[i + 1] += a[i] / 10; a[i] %= 10; }       // carries
    int top = N - 1;
    while (top > 0 && a[top] == 0) top--;
    for (int i = top; i >= 0; i--) cout << a[i];
    cout << "\n";
    return 0;
}

