const int N = 50005;
int mu[N], pre[N], primes[N], cnt = 0;
bool comp[N];

int main() {
    mu[1] = 1;
    for (int i = 2; i < N; i++) {                      // linear sieve for mu
        if (!comp[i]) { primes[cnt++] = i; mu[i] = -1; }
        for (int j = 0; j < cnt && i * primes[j] < N; j++) {
            comp[i * primes[j]] = true;
            if (i % primes[j] == 0) { mu[i * primes[j]] = 0; break; }
            mu[i * primes[j]] = -mu[i];
        }
    }
    for (int i = 1; i < N; i++) pre[i] = pre[i - 1] + mu[i];
    int T;
    cin >> T;
    while (T--) {
        long long a, b, d;
        cin >> a >> b >> d;
        a /= d; b /= d;                                // gcd = d  <=>  gcd of (i/d, j/d) = 1
        long long ans = 0;
        for (long long l = 1, r; l <= min(a, b); l = r + 1) {
            r = min(a / (a / l), b / (b / l));         // both quotients constant on [l, r]
            ans += (pre[r] - pre[l - 1]) * (a / l) * (b / l);
        }
        cout << ans << "\n";
    }
    return 0;
}

