#include <bits/stdc++.h>
using namespace std;

int dig[20], len_;
long long memo[20][20];
bool vis[20][20];
int target;

// count occurrences of `target` in all numbers formed from position pos downward
long long dfs(int pos, int cnt, bool limit, bool lead) {
    if (pos == 0) return cnt;
    if (!limit && !lead && vis[pos][cnt]) return memo[pos][cnt];
    long long res = 0;
    int up = limit ? dig[pos] : 9;
    for (int x = 0; x <= up; x++) {
        bool nowLead = lead && x == 0;
        int add = (x == target && !nowLead) ? 1 : 0;   // leading zeros are not digits
        res += dfs(pos - 1, cnt + add, limit && x == up, nowLead);
    }
    if (!limit && !lead) { vis[pos][cnt] = true; memo[pos][cnt] = res; }
    return res;
}
long long countUpTo(long long n) {
    if (n < 0) return 0;
    len_ = 0;
    while (n > 0) { dig[++len_] = n % 10; n /= 10; }
    if (len_ == 0) dig[++len_] = 0;
    memset(vis, 0, sizeof(vis));
    return dfs(len_, 0, true, true);
}

int main() {
    long long a, b;
    cin >> a >> b;
    for (target = 0; target <= 9; target++) cout << countUpTo(b) - countUpTo(a - 1) << " ";
    cout << "\n";
    return 0;
}

