using namespace std;

int dig[12];
long long memo[12][12];
bool vis[12][12];

long long dfs(int pos, int last, bool limit, bool lead) {   // last digit placed (10: none yet)
    if (pos == 0) return lead ? 0 : 1;                       // the number 0 is not counted
    if (!limit && !lead && vis[pos][last]) return memo[pos][last];
    long long res = 0;
    int up = limit ? dig[pos] : 9;
    for (int x = 0; x <= up; x++) {
        if (!lead && abs(x - last) < 2) continue;            // neighbours must differ by >= 2
        bool nowLead = lead && x == 0;
        res += dfs(pos - 1, nowLead ? 10 : x, limit && x == up, nowLead);
    }
    if (!limit && !lead) { vis[pos][last] = true; memo[pos][last] = res; }
    return res;
}
long long countUpTo(long long n) {
    int len = 0;
    while (n > 0) { dig[++len] = n % 10; n /= 10; }
    return dfs(len, 10, true, true);
}

