#include <bits/stdc++.h>
using namespace std;

struct P { double x, y; };
P operator-(P a, P b) { return P{a.x - b.x, a.y - b.y}; }
double cross(P a, P b) { return a.x * b.y - a.y * b.x; }
double dist(P a, P b) { return sqrt((a.x - b.x) * (a.x - b.x) + (a.y - b.y) * (a.y - b.y)); }
bool byXY(P a, P b) { return a.x < b.x || (a.x == b.x && a.y < b.y); }

int main() {
    int n;
    cin >> n;
    vector<P> p(n);
    for (int i = 0; i < n; i++) cin >> p[i].x >> p[i].y;
    sort(p.begin(), p.end(), byXY);
    vector<P> h;                                       // Andrew's monotone chain
    for (int pass = 0; pass < 2; pass++) {             // lower hull, then upper hull
        int start = h.size();
        for (int i = 0; i < n; i++) {
            P c = pass == 0 ? p[i] : p[n - 1 - i];
            while (int(h.size()) >= start + 2 && cross(h.back() - h[h.size() - 2], c - h.back()) <= 0)
                h.pop_back();                          // not a left turn: drop the middle point
            h.push_back(c);
        }
        h.pop_back();                                  // the last point starts the other chain
    }
    double per = 0;
    for (int i = 0; i < int(h.size()); i++) per += dist(h[i], h[(i + 1) % h.size()]);
    double area = 0;
    for (int i = 0; i < int(h.size()); i++) area += cross(h[i], h[(i + 1) % h.size()]);
    cout << fixed << setprecision(2) << per << "\n" << fabs(area) / 2 << "\n";
    return 0;
}

