    for (int i = 0; i < n; i++) cin >> p[i].first >> p[i].second;
    sort(p.begin(), p.end());
    set<pair<double, double>> active;                        // (y, x) of points with x within h
    double h = 1e18;
    int left = 0;
    for (int i = 0; i < n; i++) {
        while (left < i && p[i].first - p[left].first >= h) {  // too far to the left
            active.erase(make_pair(p[left].second, p[left].first));
            left++;
        }
        auto it = active.lower_bound(make_pair(p[i].second - h, -1e18));
        for (; it != active.end() && it->first < p[i].second + h; it++) {
            double dx = p[i].first - it->second, dy = p[i].second - it->first;
            h = min(h, sqrt(dx * dx + dy * dy));
        }
        active.insert(make_pair(p[i].second, p[i].first));
    }
    cout << fixed << setprecision(4) << h << "\n";
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

const int N = 100005;
int ch[N][2], fa[N], val[N], sum_[N];
bool rev[N];

bool isRoot(int x) { return ch[fa[x]][0] != x && ch[fa[x]][1] != x; }   // root of its splay tree
void up(int x) { sum_[x] = sum_[ch[x][0]] ^ sum_[ch[x][1]] ^ val[x]; }
void flip(int x) { swap(ch[x][0], ch[x][1]); rev[x] ^= 1; }
void down(int x) { if (rev[x]) { if (ch[x][0]) flip(ch[x][0]); if (ch[x][1]) flip(ch[x][1]); rev[x] = false; } }

void rotate(int x) {
    int y = fa[x], z = fa[y], k = ch[y][1] == x;
    if (!isRoot(y)) ch[z][ch[z][1] == y] = x;
    fa[x] = z;
    ch[y][k] = ch[x][!k]; if (ch[x][!k]) fa[ch[x][!k]] = y;
    ch[x][!k] = y; fa[y] = x;
    up(y); up(x);
}
void pushAll(int x) { if (!isRoot(x)) pushAll(fa[x]); down(x); }
void splay(int x) {
    pushAll(x);
    while (!isRoot(x)) {
        int y = fa[x], z = fa[y];
        if (!isRoot(y)) rotate((ch[y][1] == x) == (ch[z][1] == y) ? y : x);
        rotate(x);
    }
}
void access(int x) { for (int last = 0; x; last = x, x = fa[x]) { splay(x); ch[x][1] = last; up(x); } }
void makeRoot(int x) { access(x); splay(x); flip(x); }
int findRoot(int x) { access(x); splay(x); while (ch[x][0]) { down(x); x = ch[x][0]; } splay(x); return x; }
void link(int x, int y) { makeRoot(x); if (findRoot(y) != x) fa[x] = y; }          // ignore if already connected
void cut(int x, int y) {
    makeRoot(x);
    if (findRoot(y) == x && fa[y] == x && !ch[y][0]) { fa[y] = ch[x][1] = 0; up(x); }   // only a real edge
}

int main() {
    int n, m;
    cin >> n >> m;
    for (int i = 1; i <= n; i++) { cin >> val[i]; sum_[i] = val[i]; }
    while (m--) {
        int op, x, y;
        cin >> op >> x >> y;
        if (op == 0) { makeRoot(x); access(y); splay(y); cout << sum_[y] << "\n"; }   // XOR on path x..y
        else if (op == 1) link(x, y);
        else if (op == 2) cut(x, y);
        else { splay(x); val[x] = y; up(x); }
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

struct P { double x, y; };
double dist(P a, P b) { return hypot(a.x - b.x, a.y - b.y); }
P center3(P a, P b, P c) {                         // circumcentre of three points
    double bx = b.x - a.x, by = b.y - a.y, cx = c.x - a.x, cy = c.y - a.y;
    double d = 2 * (bx * cy - by * cx);
    double ux = (cy * (bx * bx + by * by) - by * (cx * cx + cy * cy)) / d;
    double uy = (bx * (cx * cx + cy * cy) - cx * (bx * bx + by * by)) / d;
    return P{a.x + ux, a.y + uy};
}

int main() {
    int n;
    cin >> n;
    vector<P> p(n);
    for (int i = 0; i < n; i++) cin >> p[i].x >> p[i].y;
    mt19937 rng(chrono::steady_clock::now().time_since_epoch().count());
    shuffle(p.begin(), p.end(), rng);              // random order: expected O(n)
    P c = p[0];
    double r = 0;
    const double EPS = 1e-9;
    for (int i = 1; i < n; i++) {
        if (dist(c, p[i]) <= r + EPS) continue;
        c = p[i]; r = 0;                           // p[i] must be on the circle
        for (int j = 0; j < i; j++) {
            if (dist(c, p[j]) <= r + EPS) continue;
            c = P{(p[i].x + p[j].x) / 2, (p[i].y + p[j].y) / 2}; r = dist(c, p[i]);   // p[i], p[j] on it
            for (int k = 0; k < j; k++)
                if (dist(c, p[k]) > r + EPS) { c = center3(p[i], p[j], p[k]); r = dist(c, p[i]); }
        }
    }
    cout << fixed << setprecision(10) << r << "\n" << c.x << " " << c.y << "\n";
    return 0;
}

