const int N = 200005, LOG = 19;
int fa[N], val[N], up[N][LOG], dep[N];
vector<int> kids[N];
int find(int x) { return fa[x] == x ? x : fa[x] = find(fa[x]); }

void dfs(int u, int p) {
    up[u][0] = p;
    for (int k = 1; k < LOG; k++) up[u][k] = up[up[u][k - 1]][k - 1];
    for (int i = 0; i < int(kids[u].size()); i++) { dep[kids[u][i]] = dep[u] + 1; dfs(kids[u][i], u); }
}
int lca(int a, int b) {
    if (dep[a] < dep[b]) swap(a, b);
    for (int k = LOG - 1; k >= 0; k--) if (dep[a] - (1 << k) >= dep[b]) a = up[a][k];
    if (a == b) return a;
    for (int k = LOG - 1; k >= 0; k--) if (up[a][k] != up[b][k]) { a = up[a][k]; b = up[b][k]; }
    return up[a][0];
}

