        int a = find(e[i][1]), b = find(e[i][2]);
        if (a == b) continue;
        val[++cnt] = e[i][0];                       // new node for this merge
        kids[cnt].push_back(a); kids[cnt].push_back(b);
        fa[a] = fa[b] = cnt;
    }
    dfs(cnt, 0);                                    // the last node is the root (graph connected)
    while (q--) { int a, b; cin >> a >> b; cout << val[lca(a, b)] << "\n"; }
