const int N = 400005;
vector<long long> ys;
int cnt[N * 4];
long long len_[N * 4];
struct Ev { long long x, y1, y2; int d; };
bool byX(const Ev &a, const Ev &b) { return a.x < b.x; }

void pull(int p, int l, int r) {                 // node covers ys[l] .. ys[r+1]
    if (cnt[p] > 0) len_[p] = ys[r + 1] - ys[l];
    else if (l == r) len_[p] = 0;
    else len_[p] = len_[2 * p] + len_[2 * p + 1];
}
void update(int p, int l, int r, int x, int y, int d) {
    if (y < l || r < x) return;
    if (x <= l && r <= y) { cnt[p] += d; pull(p, l, r); return; }
    int mid = (l + r) / 2;
    update(2 * p, l, mid, x, y, d); update(2 * p + 1, mid + 1, r, x, y, d);
    pull(p, l, r);
}

int main() {
    int n;
    cin >> n;
    vector<Ev> ev;
    for (int i = 0; i < n; i++) {
        long long x1, y1, x2, y2;
        cin >> x1 >> y1 >> x2 >> y2;
        ev.push_back(Ev{x1, y1, y2, 1}); ev.push_back(Ev{x2, y1, y2, -1});
        ys.push_back(y1); ys.push_back(y2);
    }
    sort(ys.begin(), ys.end()); ys.erase(unique(ys.begin(), ys.end()), ys.end());
    sort(ev.begin(), ev.end(), byX);
    int m = ys.size() - 1;                           // elementary y-intervals 0 .. m-1
    long long area = 0;
    for (int i = 0; i < int(ev.size()); i++) {
        if (i > 0) area += len_[1] * (ev[i].x - ev[i - 1].x);   // strip since the last event
        int a = lower_bound(ys.begin(), ys.end(), ev[i].y1) - ys.begin();
        int b = lower_bound(ys.begin(), ys.end(), ev[i].y2) - ys.begin() - 1;
        update(1, 0, m - 1, a, b, ev[i].d);
    }
    cout << area << "\n";
    return 0;
}

