const int LO = -100000, HI = 100000;
struct Line { long long k, b; long long at(long long x) const { return k * x + b; } };
vector<Line> t;                                  // node line
vector<int> lc, rc;
vector<bool> has;

int newNode() { t.push_back(Line{0, 0}); lc.push_back(-1); rc.push_back(-1); has.push_back(false); return t.size() - 1; }

void insert(int p, int l, int r, Line ln) {
    if (!has[p]) { t[p] = ln; has[p] = true; return; }
    int mid = l + (r - l) / 2;                   // floor for negatives too
    if (ln.at(mid) > t[p].at(mid)) swap(ln, t[p]);   // keep the better one at mid
    if (l == r) return;
    if (ln.at(l) > t[p].at(l)) {                 // the loser can only win on the left
        if (lc[p] < 0) { int c = newNode(); lc[p] = c; }
        insert(lc[p], l, mid, ln);
    } else if (ln.at(r) > t[p].at(r)) {          // ... or only on the right
        if (rc[p] < 0) { int c = newNode(); rc[p] = c; }
        insert(rc[p], mid + 1, r, ln);
    }
}
long long query(int p, int l, int r, long long x) {
    if (p < 0 || !has[p]) return LLONG_MIN;
    long long res = t[p].at(x);
    if (l == r) return res;
    int mid = l + (r - l) / 2;
    return max(res, x <= mid ? query(lc[p], l, mid, x) : query(rc[p], mid + 1, r, x));
}

int main() {
    newNode();                                   // root
    int n, q;
    cin >> n >> q;
    for (int i = 0; i < n; i++) { long long k, b; cin >> k >> b; insert(0, LO, HI, Line{k, b}); }
    while (q--) { long long x; cin >> x; cout << query(0, LO, HI, x) << "\n"; }
    return 0;
}

