using namespace std;

const int N = 100005, V = 100000, M = N * 20;
int ls[M], rs[M], mx[M], who[M], tot = 0;     // mx: highest count in range, who: smallest value with it
int root[N], val[N], ans[N];
vector<int> g[N];

void pull(int p) {
    if (mx[ls[p]] >= mx[rs[p]]) { mx[p] = mx[ls[p]]; who[p] = who[ls[p]]; }   // tie: smaller value
    else { mx[p] = mx[rs[p]]; who[p] = who[rs[p]]; }
}
int add(int p, int l, int r, int x) {          // count of value x += 1
    if (!p) p = ++tot;
    if (l == r) { mx[p]++; who[p] = l; return p; }
    int mid = (l + r) / 2;
    if (x <= mid) ls[p] = add(ls[p], l, mid, x); else rs[p] = add(rs[p], mid + 1, r, x);
    pull(p); return p;
}
int merge(int a, int b, int l, int r) {
    if (!a || !b) return a | b;                  // only one side: reuse it
    if (l == r) { mx[a] += mx[b]; return a; }
    int mid = (l + r) / 2;
    ls[a] = merge(ls[a], ls[b], l, mid);
    rs[a] = merge(rs[a], rs[b], mid + 1, r);
    pull(a); return a;
}
void dfs(int u, int p) {
    root[u] = add(0, 1, V, val[u]);
    for (int k = 0; k < int(g[u].size()); k++) {
        int v = g[u][k];
        if (v == p) continue;
        dfs(v, u);
        root[u] = merge(root[u], root[v], 1, V);
    }
    ans[u] = who[root[u]];
}

