#include <bits/stdc++.h>
using namespace std;

const int N = 200005;
int n, m, k, fa[N], sz[N], par[N];               // par: parity of the edge to fa
vector<pair<int, int>> seg[N * 4];               // edges living on each node
struct Op { int child, root, oldSize; };
vector<Op> ops;

pair<int, int> find(int x) {                     // (root, parity from x to root), no compression
    int p = 0;
    while (fa[x] != x) { p ^= par[x]; x = fa[x]; }
    return make_pair(x, p);
}
bool unite(int u, int v) {                       // false if an odd cycle appears
    pair<int, int> a = find(u), b = find(v);
    if (a.first == b.first) return a.second != b.second;
    if (sz[a.first] < sz[b.first]) swap(a, b);
    fa[b.first] = a.first; par[b.first] = a.second ^ b.second ^ 1;   // u and v get different colours
    ops.push_back(Op{b.first, a.first, sz[a.first]});
    sz[a.first] += sz[b.first];
    return true;
}
void rollback(int to) {
    while (int(ops.size()) > to) {
        Op o = ops.back(); ops.pop_back();
        fa[o.child] = o.child; par[o.child] = 0; sz[o.root] = o.oldSize;
    }
}
void addEdge(int p, int l, int r, int x, int y, pair<int, int> e) {
    if (y < l || r < x) return;
    if (x <= l && r <= y) { seg[p].push_back(e); return; }
    int mid = (l + r) / 2;
    addEdge(2 * p, l, mid, x, y, e); addEdge(2 * p + 1, mid + 1, r, x, y, e);
}
void solve(int p, int l, int r, bool ok) {
    int mark = ops.size();
    for (int i = 0; ok && i < int(seg[p].size()); i++) ok = unite(seg[p][i].first, seg[p][i].second);
    if (l == r) cout << (ok ? "Yes" : "No") << "\n";
    else { int mid = (l + r) / 2; solve(2 * p, l, mid, ok); solve(2 * p + 1, mid + 1, r, ok); }
    rollback(mark);                              // leave the node: undo its merges
}

int main() {
    cin >> n >> m >> k;
    for (int i = 1; i <= n; i++) { fa[i] = i; sz[i] = 1; }
    for (int i = 0; i < m; i++) {
        int x, y, l, r;
        cin >> x >> y >> l >> r;                 // the edge exists at times l+1 .. r
        if (l + 1 <= r) addEdge(1, 1, k, l + 1, r, make_pair(x, y));
    }
    solve(1, 1, k, true);
    return 0;
}

