int n, m, need, fa[50005];
struct E { int u, v, c, col; };
vector<E> e;
long long cost; int whites;
int find(int x) { return fa[x] == x ? x : fa[x] = find(fa[x]); }

void run(int lambda) {                            // MST with white edges costing c + lambda
    vector<E> s = e;
    for (int i = 0; i < m; i++) if (s[i].col == 0) s[i].c += lambda;
    stable_sort(s.begin(), s.end(), [](const E &a, const E &b) {
        return a.c != b.c ? a.c < b.c : a.col < b.col;   // ties: white first (more whites)
    });
    for (int i = 0; i < n; i++) fa[i] = i;
    cost = 0; whites = 0;
    for (int i = 0; i < m; i++) {
        int a = find(s[i].u), b = find(s[i].v);
        if (a == b) continue;
        fa[a] = b; cost += s[i].c; whites += s[i].col == 0;
    }
}

int main() {
