    e.resize(m);
    for (int i = 0; i < m; i++) cin >> e[i].u >> e[i].v >> e[i].c >> e[i].col;
    int lo = -105, hi = 105, best = hi;
    while (lo <= hi) {                            // largest whites count as lambda grows: decreasing
        int mid = lo + (hi - lo) / 2;
        run(mid);
        if (whites >= need) { best = mid; lo = mid + 1; } else hi = mid - 1;
    }
    run(best);
    cout << cost - 1LL * best * need << "\n";     // take the penalty back off
    return 0;
}

