#include <bits/stdc++.h>
using namespace std;

const int N = 300005;
int ch[N][26], fail_[N], len_[N], num[N], cnt[N], tot, last;
string s;

int getFail(int v, int i) {                     // longest palindrome suffix that can be wrapped by s[i]
    while (i - len_[v] - 1 < 0 || s[i - len_[v] - 1] != s[i]) v = fail_[v];
    return v;
}

int main() {
    cin >> s;
    int n = s.size();
    len_[0] = 0; fail_[0] = 1;                  // node 0: empty palindrome
    len_[1] = -1; fail_[1] = 0;                 // node 1: the imaginary length -1 root
    tot = 1; last = 0;
    for (int i = 0; i < n; i++) {
        int c = s[i] - 'a';
        int p = getFail(last, i);
        if (!ch[p][c]) {                        // a palindrome never seen before
            int v = ++tot;
            len_[v] = len_[p] + 2;
            fail_[v] = ch[getFail(fail_[p], i)][c];   // 0 if none: the empty palindrome
            num[v] = num[fail_[v]] + 1;         // palindromic suffixes ending here
            ch[p][c] = v;
        }
        last = ch[p][c];
        cnt[last]++;                            // one more end position of this palindrome
        cout << (i ? " " : "") << num[last];
    }
    cout << "\n";
    long long best = 0;
    for (int v = tot; v >= 2; v--) {            // nodes are created in increasing length order
        cnt[fail_[v]] += cnt[v];                // occurrences pass to the palindromic suffix
        best = max(best, 1LL * cnt[v] * len_[v]);
    }
    cout << tot - 1 << "\n" << best << "\n";    // distinct palindromes, best occurrences x length
