    long long r = 1;
    for (a %= p; b > 0; b >>= 1, a = a * a % p) if (b & 1) r = r * a % p;
    return r;
}
long long C(long long n, long long m) {          // n, m < p: plain formula
    if (m < 0 || m > n) return 0;
    return fact[n] * power(fact[m], p - 2) % p * power(fact[n - m], p - 2) % p;
}
long long lucas(long long n, long long m) {
    if (m == 0) return 1;
    return C(n % p, m % p) * lucas(n / p, m / p) % p;   // last digit times the rest
}

