long long power(long long a, long long b, long long p) {
    long long r = 1 % p;
    for (a %= p; b > 0; b >>= 1, a = a * a % p) if (b & 1) r = r * a % p;
    return r;
}

long long bsgs(long long a, long long b, long long p) {   // smallest x >= 0 with a^x = b (mod p)
    a %= p; b %= p;
    if (b == 1 % p) return 0;
    long long t = ceil(sqrt(double(p)));
    unordered_map<long long, long long> baby;
    long long cur = b;
    for (long long j = 0; j < t; j++) { baby[cur] = j; cur = cur * a % p; }   // later j overwrite: keep largest
    long long giant = power(a, t, p), g = 1;
    for (long long i = 1; i <= t; i++) {
        g = g * giant % p;                                 // a^(i t)
        auto it = baby.find(g);
        if (it != baby.end()) return i * t - it->second;
    }
    return -1;
}

