const long long MOD = 1000000007;
long long power(long long a, long long b) {
    long long r = 1;
    for (a %= MOD; b > 0; b >>= 1, a = a * a % MOD) if (b & 1) r = r * a % MOD;
    return r;
}
long long phi(long long n) {
    long long r = n;
    for (long long p = 2; p * p <= n; p++)
        if (n % p == 0) { r = r / p * (p - 1); while (n % p == 0) n /= p; }
    if (n > 1) r = r / n * (n - 1);
    return r;
}

