                ans = (ans + phi(n / d) % MOD * power(n, d)) % MOD;          // gcd = d: phi(n/d) rotations
                if (d * d != n) ans = (ans + phi(d) % MOD * power(n, n / d)) % MOD;
            }
        cout << ans * power(n, MOD - 2) % MOD << "\n";  // divide by the n rotations
    }
