    for (a %= MOD; b > 0; b >>= 1, a = a * a % MOD) if (b & 1) r = r * a % MOD;
    return r;
}

int main() {
    int n, m;
    cin >> n >> m;
    vector<vector<long long>> L(n, vector<long long>(n, 0));
    for (int i = 0; i < m; i++) {
        int u, v; cin >> u >> v; u--; v--;
        L[u][u]++; L[v][v]++;                         // degrees
        L[u][v] = (L[u][v] - 1 + MOD) % MOD;          // -1 per edge
        L[v][u] = (L[v][u] - 1 + MOD) % MOD;
    }
    int k = n - 1;                                    // drop the last row and column
    long long det = 1;
    for (int c = 0; c < k; c++) {
        int piv = -1;
        for (int r = c; r < k; r++) if (L[r][c]) { piv = r; break; }
        if (piv < 0) { cout << 0 << "\n"; return 0; } // disconnected graph
        if (piv != c) { swap(L[piv], L[c]); det = (MOD - det) % MOD; }
        det = det * L[c][c] % MOD;
        long long inv = power(L[c][c], MOD - 2);
        for (int r = c + 1; r < k; r++) {
            long long f = L[r][c] * inv % MOD;
            for (int j = c; j < k; j++) L[r][j] = ((L[r][j] - f * L[c][j]) % MOD + MOD) % MOD;
        }
    }
    cout << det << "\n";
    return 0;
}

