int limit;

int h() {                                        // misplaced knights: each move fixes at most one
    int c = 0;
    for (int i = 0; i < 5; i++) for (int j = 0; j < 5; j++) if (b[i][j] != goal[i][j] && b[i][j] != '*') c++;
    return c;
}
bool dfs(int g, int x, int y, int lastK) {
    int est = h();
    if (est == 0) return true;
    if (g + est > limit) return false;           // the IDA* cut
    for (int k = 0; k < 8; k++) {
        if (lastK >= 0 && k == (lastK ^ 1)) continue;   // do not undo the previous move
        int a = x + dx[k], c = y + dy[k];
        if (a < 0 || a > 4 || c < 0 || c > 4) continue;
        swap(b[x][y], b[a][c]);                  // move a knight into the empty square
        if (dfs(g + 1, a, c, k)) return true;
        swap(b[x][y], b[a][c]);
    }
    return false;
}

