const int B = 4;                              // block size (about sqrt(n) in real use)
list<vector<int>> blocks;

void insertAt(int pos, int x) {               // after the first pos elements
    for (auto it = blocks.begin(); it != blocks.end(); it++) {
        if (pos <= int(it->size())) {
            it->insert(it->begin() + pos, x);
            if (int(it->size()) > 2 * B) {    // too big: split in half
                vector<int> right(it->begin() + B, it->end());
                it->resize(B);
                blocks.insert(next(it), right);
            }
            return;
        }
        pos -= it->size();
    }
}
int kth(int k) {                              // 1-based
    for (auto it = blocks.begin(); it != blocks.end(); it++) {
        if (k <= int(it->size())) return (*it)[k - 1];
        k -= it->size();
    }
    return -1;
}

