int n, m;
long long t[4][105][105];                     // d, d*i, d*j, d*i*j

void add(int x, int y, long long v) {
    for (int i = x; i <= n; i += i & -i)
        for (int j = y; j <= m; j += j & -j) {
            t[0][i][j] += v; t[1][i][j] += v * x; t[2][i][j] += v * y; t[3][i][j] += v * x * y;
        }
}
long long prefix(int x, int y) {              // sum of the rectangle (1,1)..(x,y)
    long long s0 = 0, s1 = 0, s2 = 0, s3 = 0;
    for (int i = x; i > 0; i -= i & -i)
        for (int j = y; j > 0; j -= j & -j) { s0 += t[0][i][j]; s1 += t[1][i][j]; s2 += t[2][i][j]; s3 += t[3][i][j]; }
    return s0 * (x + 1) * (y + 1) - s1 * (y + 1) - s2 * (x + 1) + s3;
}
void rangeAdd(int a, int b, int c, int d, long long v) {
    add(a, b, v); add(a, d + 1, -v); add(c + 1, b, -v); add(c + 1, d + 1, v);
}
long long rangeSum(int a, int b, int c, int d) {
    return prefix(c, d) - prefix(a - 1, d) - prefix(c, b - 1) + prefix(a - 1, b - 1);
}

