void findCycle(int u, int fromEdge) {            // any edge reaching a visited vertex closes the cycle
    vis[u] = true;
    for (int k = 0; k < int(g[u].size()); k++) {
        int v = g[u][k].first, id = g[u][k].second;
        if (id == fromEdge) continue;
        if (vis[v]) { cu = u; cv = v; cutId = id; }
        else findCycle(v, id);
    }
}
void dp(int u, int fromEdge) {
    f[u][0] = 0; f[u][1] = w[u];
    for (int k = 0; k < int(g[u].size()); k++) {
        int v = g[u][k].first, id = g[u][k].second;
        if (id == fromEdge || id == cutId) continue;   // the cut edge does not exist
        dp(v, id);
        f[u][0] += max(f[v][0], f[v][1]);
        f[u][1] += f[v][0];
    }
}

