#include <bits/stdc++.h>
using namespace std;

const int N = 200005;
const double ALPHA = 0.7;
int ls[N], rs[N], val[N], cnt[N], s[N], sz[N], sd[N], tot = 0, root = 0;
// s: nodes in subtree, sz: copies of values, sd: nodes with cnt > 0
vector<int> buf;

void up(int x) {
    s[x] = s[ls[x]] + s[rs[x]] + 1;
    sz[x] = sz[ls[x]] + sz[rs[x]] + cnt[x];
    sd[x] = sd[ls[x]] + sd[rs[x]] + (cnt[x] > 0);
}
bool needRebuild(int x) {
    return cnt[x] && (ALPHA * s[x] <= max(s[ls[x]], s[rs[x]]) || ALPHA * s[x] >= sd[x]);
}
void flatten(int x) {                               // in-order, keep only live nodes
    if (!x) return;
    flatten(ls[x]);
    if (cnt[x]) buf.push_back(x);
    flatten(rs[x]);
}
int build(int l, int r) {                           // perfectly balanced from buf[l..r]
    if (l > r) return 0;
    int mid = (l + r) / 2, x = buf[mid];
    ls[x] = build(l, mid - 1); rs[x] = build(mid + 1, r);
    up(x); return x;
}
void rebuild(int &x) { buf.clear(); flatten(x); x = build(0, int(buf.size()) - 1); }

void insert(int &x, int v) {
    if (!x) { x = ++tot; val[x] = v; cnt[x] = 1; up(x); return; }
    if (v == val[x]) cnt[x]++;
    else if (v < val[x]) insert(ls[x], v);
    else insert(rs[x], v);
    up(x);
    if (needRebuild(x)) rebuild(x);
}
void remove_(int &x, int v) {
    if (v == val[x]) cnt[x]--;                      // lazy: the node stays
    else if (v < val[x]) remove_(ls[x], v);
    else remove_(rs[x], v);
    up(x);
    if (needRebuild(x)) rebuild(x);
}
int countLess(int x, int v) {
    if (!x) return 0;
    if (v <= val[x]) return countLess(ls[x], v);
    return sz[ls[x]] + cnt[x] + countLess(rs[x], v);
}
int kth(int x, int k) {
    while (true) {
        if (k <= sz[ls[x]]) x = ls[x];
        else if (k <= sz[ls[x]] + cnt[x]) return val[x];
        else { k -= sz[ls[x]] + cnt[x]; x = rs[x]; }
    }
}

