        else if (op == 3) cout << countLess(root, x) + 1 << "\n";
        else if (op == 4) cout << kth(root, x) << "\n";
        else if (op == 5) cout << kth(root, countLess(root, x)) << "\n";          // predecessor
        else cout << kth(root, countLess(root, x + 1) + 1) << "\n";                // successor
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

const int N = 200005;
int rt = 0, tot = 0, fa[N], ch[N][2], val[N], cnt[N], sz[N];

void up(int x) { sz[x] = sz[ch[x][0]] + sz[ch[x][1]] + cnt[x]; }
bool side(int x) { return ch[fa[x]][1] == x; }
void rotate(int x) {
    int y = fa[x], z = fa[y], k = side(x);
    ch[y][k] = ch[x][!k]; if (ch[x][!k]) fa[ch[x][!k]] = y;
    ch[x][!k] = y; fa[y] = x; fa[x] = z;
    if (z) ch[z][ch[z][1] == y] = x;
    up(y); up(x);
}
void splay(int x) {                                 // bring x to the root
    for (int f; (f = fa[x]) != 0; rotate(x))
        if (fa[f]) rotate(side(x) == side(f) ? f : x);   // zig-zig: parent first
    rt = x;
}
void insert(int v) {
    if (!rt) { rt = ++tot; val[rt] = v; cnt[rt] = sz[rt] = 1; return; }
    int x = rt, f = 0;
    while (x && val[x] != v) { f = x; x = ch[x][v > val[x]]; }
    if (x) cnt[x]++;
    else { x = ++tot; val[x] = v; cnt[x] = 1; fa[x] = f; ch[f][v > val[f]] = x; }
    up(x); splay(x);
}
int countLess(int v) {                              // values < v, splays the last node visited
    int x = rt, res = 0, last = 0;
    while (x) {
        last = x;
        if (v <= val[x]) x = ch[x][0];
        else { res += sz[ch[x][0]] + cnt[x]; x = ch[x][1]; }
    }
    if (last) splay(last);
    return res;
}
int kth(int k) {
    int x = rt;
    while (true) {
        if (k <= sz[ch[x][0]]) x = ch[x][0];
        else if (k <= sz[ch[x][0]] + cnt[x]) { splay(x); return val[x]; }
        else { k -= sz[ch[x][0]] + cnt[x]; x = ch[x][1]; }
    }
}
void remove_(int v) {
    int x = rt;
    while (val[x] != v) x = ch[x][v > val[x]];
    splay(x);
    if (cnt[x] > 1) { cnt[x]--; up(x); return; }
    int L = ch[x][0], R = ch[x][1];
    fa[L] = fa[R] = 0;
    if (!L) { rt = R; return; }
    int p = L;
    while (ch[p][1]) p = ch[p][1];                  // largest of the left part
    splay(p);                                       // now root of the left part, no right child
    ch[p][1] = R; if (R) fa[R] = p;
    up(p);
}

int main() { 
    int n;
    cin >> n;
    while (n--) {
        int op, x;
        cin >> op >> x;
        if (op == 1) insert(x);
        else if (op == 2) remove_(x);
        else if (op == 3) cout << countLess(x) + 1 << "\n";
        else if (op == 4) cout << kth(x) << "\n";
        else if (op == 5) cout << kth(countLess(x)) << "\n";
        else cout << kth(countLess(x + 1) + 1) << "\n";
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

const int N = 200005;
struct P { long long c[2]; };
P p[N];
int lc[N], rc[N];
long long lo[N][2], hi[N][2], best;
int K;                                        // current split dimension (used by the comparator)

bool cmpK(const P &a, const P &b) { return a.c[K] < b.c[K]; }
int build(int l, int r, int dim) {            // node = index of the median point
    if (l > r) return -1;
    int mid = (l + r) / 2;
    K = dim;
    nth_element(p + l, p + mid, p + r + 1, cmpK);
    lc[mid] = build(l, mid - 1, dim ^ 1);
    rc[mid] = build(mid + 1, r, dim ^ 1);
    for (int d = 0; d < 2; d++) {
        lo[mid][d] = hi[mid][d] = p[mid].c[d];
        if (lc[mid] >= 0) { lo[mid][d] = min(lo[mid][d], lo[lc[mid]][d]); hi[mid][d] = max(hi[mid][d], hi[lc[mid]][d]); }
        if (rc[mid] >= 0) { lo[mid][d] = min(lo[mid][d], lo[rc[mid]][d]); hi[mid][d] = max(hi[mid][d], hi[rc[mid]][d]); }
    }
    return mid;
}
long long boxDist(int t, const P &q) {        // squared distance from q to t's bounding box
    long long s = 0;
    for (int d = 0; d < 2; d++) {
        long long g = 0;
        if (q.c[d] < lo[t][d]) g = lo[t][d] - q.c[d];
        else if (q.c[d] > hi[t][d]) g = q.c[d] - hi[t][d];
        s += g * g;
    }
    return s;
}
void query(int t, const P &q) {
    if (t < 0 || boxDist(t, q) >= best) return;              // the whole box is too far
    long long dx = p[t].c[0] - q.c[0], dy = p[t].c[1] - q.c[1];
    best = min(best, dx * dx + dy * dy);
    long long dl = lc[t] >= 0 ? boxDist(lc[t], q) : LLONG_MAX, dr = rc[t] >= 0 ? boxDist(rc[t], q) : LLONG_MAX;
    if (dl < dr) { query(lc[t], q); query(rc[t], q); }        // nearer box first
    else { query(rc[t], q); query(lc[t], q); }
}

int main() {
    int n, m;
    cin >> n >> m;
    for (int i = 0; i < n; i++) cin >> p[i].c[0] >> p[i].c[1];
    int root = build(0, n - 1, 0);
    while (m--) {
        P q; cin >> q.c[0] >> q.c[1];
        best = LLONG_MAX;
        query(root, q);
        cout << best << "\n";                                 // squared distance
    }
    return 0;
}

