int n, s[9][9];
double avg, f[16][9][9][9][9];
bool vis[16][9][9][9][9];

double piece(int a, int b, int c, int d) {        // (sum of the rectangle - avg)^2
    double x = s[c][d] - s[a - 1][d] - s[c][b - 1] + s[a - 1][b - 1] - avg;
    return x * x;
}
double solve(int k, int a, int b, int c, int d) { // best for cutting this rectangle into k pieces
    if (k == 1) return piece(a, b, c, d);
    if (vis[k][a][b][c][d]) return f[k][a][b][c][d];
    double r = 1e18;
    for (int x = a; x < c; x++)                   // horizontal cut after row x
        r = min(r, min(solve(k - 1, a, b, x, d) + piece(x + 1, b, c, d), piece(a, b, x, d) + solve(k - 1, x + 1, b, c, d)));
    for (int y = b; y < d; y++)                   // vertical cut after column y
        r = min(r, min(solve(k - 1, a, b, c, y) + piece(a, y + 1, c, d), piece(a, b, c, y) + solve(k - 1, a, y + 1, c, d)));
    vis[k][a][b][c][d] = true;
    return f[k][a][b][c][d] = r;
}

