#include <bits/stdc++.h>
using namespace std;

const int M = 2000000;                          // sieve directly below M (about N^(2/3))
long long sphi[M + 1], smu[M + 1];
int pr[M], cnt = 0;
bool comp[M + 1];
unordered_map<long long, long long> memoPhi, memoMu;

long long Sphi(long long n) {
    if (n <= M) return sphi[n];
    if (memoPhi.count(n)) return memoPhi[n];
    long long res = n * (n + 1) / 2;             // sum of id = sum of (phi * 1)
    for (long long l = 2, r; l <= n; l = r + 1) {
        r = n / (n / l);
        res -= (r - l + 1) * Sphi(n / l);        // g = 1: subtract S(n/d) for d >= 2
    }
    return memoPhi[n] = res;
}
long long Smu(long long n) {
    if (n <= M) return smu[n];
    if (memoMu.count(n)) return memoMu[n];
    long long res = 1;                           // sum of epsilon = 1
    for (long long l = 2, r; l <= n; l = r + 1) {
        r = n / (n / l);
        res -= (r - l + 1) * Smu(n / l);
    }
    return memoMu[n] = res;
}

int main() {
    vector<long long> phi(M + 1), mu(M + 1);
    phi[1] = mu[1] = 1;
    for (int i = 2; i <= M; i++) {               // linear sieve
        if (!comp[i]) { pr[cnt++] = i; phi[i] = i - 1; mu[i] = -1; }
        for (int j = 0; j < cnt && 1LL * i * pr[j] <= M; j++) {
            comp[i * pr[j]] = true;
            if (i % pr[j] == 0) { phi[i * pr[j]] = phi[i] * pr[j]; mu[i * pr[j]] = 0; break; }
            phi[i * pr[j]] = phi[i] * (pr[j] - 1); mu[i * pr[j]] = -mu[i];
        }
    }
    for (int i = 1; i <= M; i++) { sphi[i] = sphi[i - 1] + phi[i]; smu[i] = smu[i - 1] + mu[i]; }
    int T;
    cin >> T;
    while (T--) { long long n; cin >> n; cout << Sphi(n) << " " << Smu(n) << "\n"; }
    return 0;
}

