typedef long long ll;
ll exgcd(ll a, ll b, ll &x, ll &y) {
    if (!b) { x = 1; y = 0; return a; }
    ll g = exgcd(b, a % b, y, x);
    y -= a / b * x;
    return g;
}

int main() {
    int n;
    cin >> n;
    ll M = 1, R = 0;                                  // x = R (mod M) so far
    for (int i = 0; i < n; i++) {
        ll m, r;
        cin >> m >> r;                                // x = r (mod m)
        ll t, k, g = exgcd(M, m, t, k);
        ll diff = ((r - R) % m + m) % m;
        if (diff % g) { cout << -1 << "\n"; return 0; }
        ll mod = m / g;
        t = ll(__int128(t % mod + mod) % mod * (diff / g) % mod);   // M t = diff (mod m)
        R += M * t;
        M = M / g * m;                                // lcm
        R = (R % M + M) % M;
    }
    cout << R << "\n";
    return 0;
}

