using namespace std;

const long long MOD = 1000000007;
long long power(long long a, long long b) { long long r = 1; for (a %= MOD; b; b >>= 1, a = a * a % MOD) if (b & 1) r = r * a % MOD; return r; }

int main() {
    int n;
    cin >> n;
    vector<long long> fact(n + 1, 1), inv(n + 1, 1);
    for (int i = 1; i <= n; i++) fact[i] = fact[i - 1] * i % MOD;
    for (int i = 0; i <= n; i++) inv[i] = power(fact[i], MOD - 2);
    vector<long long> A(n + 1, 0), B(n + 1, 0), C(n + 1, 0);
    for (int k = 0; k <= n; k++) {
        if (k % 2 == 0) A[k] = inv[k];             // 'a': even number of times
        if (k >= 1) B[k] = inv[k];                 // 'b': at least once
        C[k] = inv[k];                             // 'c': any number of times
    }
    vector<long long> AB(n + 1, 0), ABC(n + 1, 0);
    for (int i = 0; i <= n; i++) for (int j = 0; i + j <= n; j++) AB[i + j] = (AB[i + j] + A[i] * B[j]) % MOD;
    for (int i = 0; i <= n; i++) for (int j = 0; i + j <= n; j++) ABC[i + j] = (ABC[i + j] + AB[i] * C[j]) % MOD;
    cout << ABC[n] * fact[n] % MOD << "\n";        // n! times the x^n coefficient
    return 0;
}

