typedef long long ll;
struct P { ll x, y; };
ll cross(P o, P a, P b) { return (a.x - o.x) * (b.y - o.y) - (a.y - o.y) * (b.x - o.x); }   // orientation
int sgn(ll v) { return (v > 0) - (v < 0); }
bool onSeg(P a, P b, P c) {                     // c on segment ab, given collinear
    return min(a.x, b.x) <= c.x && c.x <= max(a.x, b.x) && min(a.y, b.y) <= c.y && c.y <= max(a.y, b.y);
}
bool intersect(P a, P b, P c, P d) {
    int d1 = sgn(cross(a, b, c)), d2 = sgn(cross(a, b, d)), d3 = sgn(cross(c, d, a)), d4 = sgn(cross(c, d, b));
    if (d1 * d2 < 0 && d3 * d4 < 0) return true;             // proper crossing
    if (d1 == 0 && onSeg(a, b, c)) return true;              // touching / overlapping cases
    if (d2 == 0 && onSeg(a, b, d)) return true;
    if (d3 == 0 && onSeg(c, d, a)) return true;
    if (d4 == 0 && onSeg(c, d, b)) return true;
    return false;
}

int main() {
    int T;
    cin >> T;
    while (T--) {
        P a, b, c, d;
        cin >> a.x >> a.y >> b.x >> b.y >> c.x >> c.y >> d.x >> d.y;
        cout << (intersect(a, b, c, d) ? "Yes" : "No") << "\n";
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
struct P { ll x, y; };
ll cross(P o, P a, P b) { return (a.x - o.x) * (b.y - o.y) - (a.y - o.y) * (b.x - o.x); }

int main() {
    int n, q;
    cin >> n;
    vector<P> poly(n);
    for (int i = 0; i < n; i++) cin >> poly[i].x >> poly[i].y;
    cin >> q;
    while (q--) {
        P p; cin >> p.x >> p.y;
        bool on = false, inside = false;
        for (int i = 0; i < n; i++) {
            P a = poly[i], b = poly[(i + 1) % n];
            if (cross(a, b, p) == 0 && min(a.x, b.x) <= p.x && p.x <= max(a.x, b.x) && min(a.y, b.y) <= p.y && p.y <= max(a.y, b.y)) on = true;
            if ((a.y > p.y) != (b.y > p.y)) {                   // edge straddles the horizontal line
                // x of the crossing > p.x ?  compare without division
                ll lhs = (b.x - a.x) * (p.y - a.y), rhs = (p.x - a.x) * (b.y - a.y);
                if ((b.y > a.y) ? lhs > rhs : lhs < rhs) inside = !inside;
            }
        }
        cout << (on ? "on" : inside ? "in" : "out") << "\n";
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
struct P { ll x, y; };
P operator-(P a, P b) { return P{a.x - b.x, a.y - b.y}; }
ll cross(P a, P b) { return a.x * b.y - a.y * b.x; }
ll dist2(P a, P b) { return (a.x - b.x) * (a.x - b.x) + (a.y - b.y) * (a.y - b.y); }
bool byXY(P a, P b) { return a.x < b.x || (a.x == b.x && a.y < b.y); }

int main() {
    int n;
    cin >> n;
    vector<P> p(n);
    for (int i = 0; i < n; i++) cin >> p[i].x >> p[i].y;
    sort(p.begin(), p.end(), byXY);
    vector<P> h;
    for (int pass = 0; pass < 2; pass++) {               // monotone chain ( 第 13 章 )
        int start = h.size();
        for (int i = 0; i < n; i++) {
            P c = pass == 0 ? p[i] : p[n - 1 - i];
            while (int(h.size()) >= start + 2 && cross(h.back() - h[h.size() - 2], c - h.back()) <= 0) h.pop_back();
            h.push_back(c);
        }
        h.pop_back();
    }
    int m = h.size();
    ll best = 0;
    if (m <= 2) { for (int i = 0; i < m; i++) for (int j = 0; j < m; j++) best = max(best, dist2(h[i], h[j])); }
    else {
        for (int i = 0, j = 1; i < m; i++) {
            P e = h[(i + 1) % m] - h[i];
            while (cross(e, h[(j + 1) % m] - h[i]) > cross(e, h[j] - h[i])) j = (j + 1) % m;   // area grows: move on
            best = max(best, max(dist2(h[i], h[j]), dist2(h[(i + 1) % m], h[j])));
        }
    }
    cout << best << "\n";                                // squared diameter
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

const double EPS = 1e-9;
struct V { double x, y; };
V operator+(V a, V b) { return V{a.x + b.x, a.y + b.y}; }
V operator-(V a, V b) { return V{a.x - b.x, a.y - b.y}; }
V operator*(V a, double t) { return V{a.x * t, a.y * t}; }
double cross(V a, V b) { return a.x * b.y - a.y * b.x; }
struct L { V p, d; double ang; };                 // keeps the left side of p + t*d
V meet(L a, L b) { return a.p + a.d * (cross(b.d, a.p - b.p) / cross(a.d, b.d)); }
bool outside(L l, V q) { return cross(l.d, q - l.p) < -EPS; }   // q strictly right of l
bool byAngle(const L &a, const L &b) {
    if (fabs(a.ang - b.ang) > EPS) return a.ang < b.ang;
    return cross(a.d, b.p - a.p) > 0;             // same direction: inner (more left) line first
}

int main() {
    int k;
    cin >> k;
    vector<L> ls;
    for (int t = 0; t < k; t++) {
        int m; cin >> m;
        vector<V> poly(m);
        for (int i = 0; i < m; i++) cin >> poly[i].x >> poly[i].y;
        for (int i = 0; i < m; i++) {             // counter-clockwise edges
            V d = poly[(i + 1) % m] - poly[i];
            ls.push_back(L{poly[i], d, atan2(d.y, d.x)});
        }
    }
    sort(ls.begin(), ls.end(), byAngle);
    vector<L> u;
    for (int i = 0; i < int(ls.size()); i++)      // drop the outer copies of parallel lines
        if (i == 0 || fabs(ls[i].ang - ls[i - 1].ang) > EPS) u.push_back(ls[i]);
    deque<L> q;
    for (int i = 0; i < int(u.size()); i++) {
        while (q.size() >= 2 && outside(u[i], meet(q[q.size() - 1], q[q.size() - 2]))) q.pop_back();
        while (q.size() >= 2 && outside(u[i], meet(q[0], q[1]))) q.pop_front();
        q.push_back(u[i]);
    }
    while (q.size() >= 3 && outside(q[0], meet(q[q.size() - 1], q[q.size() - 2]))) q.pop_back();
    while (q.size() >= 3 && outside(q[q.size() - 1], meet(q[0], q[1]))) q.pop_front();
    double area = 0;
    if (q.size() >= 3) {
        vector<V> pts;
        for (int i = 0; i < int(q.size()); i++) pts.push_back(meet(q[i], q[(i + 1) % q.size()]));
        for (int i = 0; i < int(pts.size()); i++) area += cross(pts[i], pts[(i + 1) % pts.size()]);
    }
    cout << fixed << setprecision(3) << fabs(area) / 2 << "\n";
    return 0;
}

