#include <bits/stdc++.h>
using namespace std;

struct Edge { int to; long long cap; };
vector<Edge> e;
vector<int> g[205];
int n, m, s, t, dist_[205], cnt[410], cur[205];

void addEdge(int u, int v, long long c) {
    g[u].push_back(e.size()); e.push_back(Edge{v, c});
    g[v].push_back(e.size()); e.push_back(Edge{u, 0});
}
long long dfs(int u, long long f) {
    if (u == t) return f;
    long long used = 0;
    for (int &k = cur[u]; k < int(g[u].size()); k++) {
        int id = g[u][k]; Edge &x = e[id];
        if (x.cap > 0 && dist_[u] == dist_[x.to] + 1) {
            long long got = dfs(x.to, min(f - used, x.cap));
            x.cap -= got; e[id ^ 1].cap += got; used += got;
            if (used == f) return used;
        }
    }
    // no admissible edge left: relabel u
    if (--cnt[dist_[u]] == 0) dist_[s] = n;      // gap: s can no longer reach t
    dist_[u]++; cnt[dist_[u]]++;
    cur[u] = 0;
    return used;
}

int main() {
    cin >> n >> m >> s >> t;
    for (int i = 0; i < m; i++) { int u, v; long long c; cin >> u >> v >> c; addEdge(u, v, c); }
    fill(dist_, dist_ + n + 1, n);               // unreachable: label n
    queue<int> q; dist_[t] = 0; q.push(t);       // one BFS from the sink on reversed edges
    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (int k = 0; k < int(g[u].size()); k++) {
            int v = e[g[u][k]].to;
            if (e[g[u][k] ^ 1].cap > 0 && dist_[v] == n && v != t) { dist_[v] = dist_[u] + 1; q.push(v); }
        }
    }
    for (int v = 1; v <= n; v++) cnt[dist_[v]]++;
    long long flow = 0;
    while (dist_[s] < n) flow += dfs(s, LLONG_MAX);
    cout << flow << "\n";
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

struct Edge { int to, cap; };
vector<Edge> e;
vector<int> g[205];
int S, T, level[205], it[205];
void addEdge(int u, int v, int c) { g[u].push_back(e.size()); e.push_back(Edge{v, c}); g[v].push_back(e.size()); e.push_back(Edge{u, 0}); }
bool bfs(int n) {
    fill(level, level + n, -1); queue<int> q; level[S] = 0; q.push(S);
    while (!q.empty()) { int u = q.front(); q.pop(); for (int k = 0; k < int(g[u].size()); k++) { Edge &x = e[g[u][k]]; if (x.cap > 0 && level[x.to] < 0) { level[x.to] = level[u] + 1; q.push(x.to); } } }
    return level[T] >= 0;
}
int dfs(int u, int f) {
    if (u == T) return f;
    for (int &k = it[u]; k < int(g[u].size()); k++) {
        int id = g[u][k]; Edge &x = e[id];
        if (x.cap > 0 && level[x.to] == level[u] + 1) { int got = dfs(x.to, min(f, x.cap)); if (got) { x.cap -= got; e[id ^ 1].cap += got; return got; } }
    }
    return 0;
}

int main() {
    int n, m;
    cin >> n >> m;
    vector<int> x(n + 1, 0);
    S = 0; T = n + 1;
    for (int i = 0; i < m; i++) {
        int u, v, directed;
        cin >> u >> v >> directed;
        x[u]++; x[v]--;                            // orient u -> v for now
        if (!directed) addEdge(u, v, 1);           // may be flipped later
    }
    int need = 0;
    for (int v = 1; v <= n; v++) {
        if (x[v] % 2 != 0) { cout << "No\n"; return 0; }   // parity cannot be fixed
        if (x[v] > 0) { addEdge(S, v, x[v] / 2); need += x[v] / 2; }
        if (x[v] < 0) addEdge(v, T, -x[v] / 2);
    }
    int flow = 0;
    while (bfs(n + 2)) { fill(it, it + n + 2, 0); while (int f = dfs(S, INT_MAX)) flow += f; }
    cout << (flow == need ? "Yes" : "No") << "\n";
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

const long long INF = 1e18;
struct Edge { int to; long long cap; };
struct Flow {
    vector<Edge> e; vector<vector<int>> g; vector<int> level, it; int n;
    Flow(int n) : g(n), level(n), it(n), n(n) {}
    int add(int u, int v, long long c) { g[u].push_back(e.size()); e.push_back(Edge{v, c}); g[v].push_back(e.size()); e.push_back(Edge{u, 0}); return e.size() - 2; }
    bool bfs(int s, int t) {
        fill(level.begin(), level.end(), -1); queue<int> q; level[s] = 0; q.push(s);
        while (!q.empty()) { int u = q.front(); q.pop(); for (int k = 0; k < int(g[u].size()); k++) { Edge &x = e[g[u][k]]; if (x.cap > 0 && level[x.to] < 0) { level[x.to] = level[u] + 1; q.push(x.to); } } }
        return level[t] >= 0;
    }
    long long dfs(int u, int t, long long f) {
        if (u == t) return f;
        for (int &k = it[u]; k < int(g[u].size()); k++) {
            int id = g[u][k]; Edge &x = e[id];
            if (x.cap > 0 && level[x.to] == level[u] + 1) { long long got = dfs(x.to, t, min(f, x.cap)); if (got) { x.cap -= got; e[id ^ 1].cap += got; return got; } }
        }
        return 0;
    }
    long long maxflow(int s, int t) { long long r = 0; while (bfs(s, t)) { fill(it.begin(), it.end(), 0); while (long long f = dfs(s, t, INF)) r += f; } return r; }
};

int main() {
    int n, m, s, t;
    cin >> n >> m >> s >> t;
    Flow F(n + 3);
    int SS = n + 1, TT = n + 2;
    vector<long long> ex(n + 1, 0);
    for (int i = 0; i < m; i++) {
        int u, v; long long lo, hi;
        cin >> u >> v >> lo >> hi;
        F.add(u, v, hi - lo);                       // the free part
        ex[v] += lo; ex[u] -= lo;                   // the forced part
    }
    int ts = F.add(t, s, INF);                      // let the s-t flow circulate
    long long need = 0;
    for (int v = 1; v <= n; v++) {
        if (ex[v] > 0) { F.add(SS, v, ex[v]); need += ex[v]; }
        if (ex[v] < 0) F.add(v, TT, -ex[v]);
    }
    if (F.maxflow(SS, TT) != need) { cout << "no feasible flow\n"; return 0; }
    long long f0 = F.e[ts ^ 1].cap;                 // flow on t -> s = a feasible value
    F.e[ts].cap = F.e[ts ^ 1].cap = 0;              // remove the t -> s edge
    Flow G = F;                                     // copy for the minimum
    long long mx = f0 + F.maxflow(s, t);
    long long mn = f0 - G.maxflow(t, s);
    cout << mx << " " << mn << "\n";
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

struct E { int u, v; long long w; };

int main() {
    int n, m, r;
    cin >> n >> m >> r;
    vector<E> e(m);
    for (int i = 0; i < m; i++) cin >> e[i].u >> e[i].v >> e[i].w;
    long long ans = 0;
    vector<long long> in(n + 1);
    vector<int> pre(n + 1), id(n + 1), vis(n + 1);
    while (true) {
        fill(in.begin(), in.end(), LLONG_MAX);
        for (int i = 0; i < m; i++)                       // cheapest incoming edge of each vertex
            if (e[i].u != e[i].v && e[i].w < in[e[i].v]) { in[e[i].v] = e[i].w; pre[e[i].v] = e[i].u; }
        for (int v = 1; v <= n; v++) if (v != r && in[v] == LLONG_MAX) { cout << -1 << "\n"; return 0; }
        int cnt = 0;
        fill(id.begin(), id.end(), 0); fill(vis.begin(), vis.end(), 0);
        in[r] = 0;
        for (int v = 1; v <= n; v++) {                    // find cycles among the chosen edges
            ans += in[v];
            int x = v;
            while (vis[x] != v && !id[x] && x != r) { vis[x] = v; x = pre[x]; }
            if (x != r && !id[x]) {                       // x is on a new cycle: label it
                id[x] = ++cnt;
                for (int y = pre[x]; y != x; y = pre[y]) id[y] = cnt;
            }
        }
        if (cnt == 0) break;                              // no cycle: done
        for (int v = 1; v <= n; v++) if (!id[v]) id[v] = ++cnt;
        for (int i = 0; i < m; i++) {                     // contract and re-weight
            int v = e[i].v;
            e[i].u = id[e[i].u]; e[i].v = id[e[i].v];
            if (e[i].u != e[i].v) e[i].w -= in[v];
        }
        n = cnt; r = id[r];
        in.assign(n + 1, 0); pre.assign(n + 1, 0); id.assign(n + 1, 0); vis.assign(n + 1, 0);
    }
    cout << ans << "\n";
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    int n, m, k;
    cin >> n >> m >> k;
    vector<vector<pair<int, int>>> g(n + 1);
    for (int i = 0; i < m; i++) { int u, v, w; cin >> u >> v >> w; g[u].push_back(make_pair(v, w)); g[v].push_back(make_pair(u, w)); }
    vector<int> term(k);
    for (int i = 0; i < k; i++) cin >> term[i];
    const long long INF = LLONG_MAX / 4;
    vector<vector<long long>> f(1 << k, vector<long long>(n + 1, INF));
    for (int i = 0; i < k; i++) f[1 << i][term[i]] = 0;
    for (int S = 1; S < (1 << k); S++) {
        for (int T = (S - 1) & S; T > 0; T = (T - 1) & S)       // merge two parts at v
            for (int v = 1; v <= n; v++) f[S][v] = min(f[S][v], f[T][v] + f[S ^ T][v]);
        priority_queue<pair<long long, int>, vector<pair<long long, int>>, greater<pair<long long, int>>> pq;
        for (int v = 1; v <= n; v++) if (f[S][v] < INF) pq.push(make_pair(f[S][v], v));
        while (!pq.empty()) {                                    // move along edges (Dijkstra)
            long long dd = pq.top().first; int u = pq.top().second; pq.pop();
            if (dd > f[S][u]) continue;
            for (int i = 0; i < int(g[u].size()); i++) {
                int v = g[u][i].first; long long nd = dd + g[u][i].second;
                if (nd < f[S][v]) { f[S][v] = nd; pq.push(make_pair(nd, v)); }
            }
        }
    }
    cout << f[(1 << k) - 1][term[0]] << "\n";
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int n;
vector<int> g[505];
int match_[505], pre[505], col[505], base_[505], vis[505], tick = 0;
queue<int> q;

int find(int x) { return base_[x] == x ? x : base_[x] = find(base_[x]); }
int lca(int x, int y) {                                // meeting point of two alternating paths
    ++tick;
    while (true) {
        if (x) { x = find(x); if (vis[x] == tick) return x; vis[x] = tick; x = match_[x] ? pre[match_[x]] : 0; }
        swap(x, y);
    }
}
void blossom(int x, int y, int b) {                    // contract the odd cycle into base b
    while (find(x) != b) {
        pre[x] = y; y = match_[x];
        if (col[y] == 2) { col[y] = 1; q.push(y); }    // inner vertex becomes outer
        if (find(x) == x) base_[x] = b;
        if (find(y) == y) base_[y] = b;
        x = pre[y];
    }
}
bool augment(int s) {
    for (int i = 1; i <= n; i++) { base_[i] = i; col[i] = 0; pre[i] = 0; }
    while (!q.empty()) q.pop();
    col[s] = 1; q.push(s);                             // 1 = outer, 2 = inner
    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (int k = 0; k < int(g[u].size()); k++) {
            int v = g[u][k];
            if (find(u) == find(v) || col[v] == 2) continue;
            if (!col[v]) {
                col[v] = 2; pre[v] = u;
                if (!match_[v]) {                      // free vertex: flip the path
                    for (int x = v, last; x; x = last) { last = match_[pre[x]]; match_[x] = pre[x]; match_[pre[x]] = x; }
                    return true;
                }
                col[match_[v]] = 1; q.push(match_[v]);
            } else {                                   // outer meets outer: a blossom
                int b = lca(u, v);
                blossom(u, v, b); blossom(v, u, b);
            }
        }
    }
    return false;
}

int main() {
    int m;
    cin >> n >> m;
    for (int i = 0; i < m; i++) { int u, v; cin >> u >> v; g[u].push_back(v); g[v].push_back(u); }
    int ans = 0;
    for (int v = 1; v <= n; v++) if (!match_[v] && augment(v)) ans++;
    cout << ans << "\n";
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
const ll MOD = 1000000007;
ll pw(ll a, ll e) { ll r = 1; a %= MOD; while (e) { if (e & 1) r = r * a % MOD; a = a * a % MOD; e >>= 1; } return r; }

int main() {
    int n, m;
    cin >> n >> m;
    vector<vector<ll>> a(n, vector<ll>(n, 0));
    mt19937_64 rng(20240601);
    for (int i = 0; i < m; i++) {
        int u, v; cin >> u >> v; u--; v--;
        ll r = rng() % (MOD - 1) + 1;              // random value for the symbol x_uv
        a[u][v] = r; a[v][u] = MOD - r;            // skew-symmetric
    }
    int rank = 0;
    for (int col = 0; col < n && rank < n; col++) {
        int piv = -1;
        for (int i = rank; i < n; i++) if (a[i][col]) { piv = i; break; }
        if (piv < 0) continue;
        swap(a[piv], a[rank]);
        ll inv = pw(a[rank][col], MOD - 2);
        for (int i = 0; i < n; i++) {
            if (i == rank || !a[i][col]) continue;
            ll f = a[i][col] * inv % MOD;
            for (int j = col; j < n; j++) a[i][j] = (a[i][j] - f * a[rank][j] % MOD + MOD) % MOD;
        }
        rank++;
    }
    cout << rank / 2 << "\n";
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

const int N = 200005;
int n, m, dfn[N], ord_[N], par[N], sdom[N], idom[N], fa[N], mn[N], timer_ = 0;
vector<int> g[N], rg[N], bucket[N], tr[N];
long long sz[N];

void dfs(int u) {
    dfn[u] = ++timer_; ord_[timer_] = u;
    for (int k = 0; k < int(g[u].size()); k++) { int v = g[u][k]; if (!dfn[v]) { par[v] = u; dfs(v); } }
}
int find(int x) {                               // DSU that keeps the vertex with minimum sdom on the path
    if (fa[x] == x) return x;
    int r = find(fa[x]);
    if (dfn[sdom[mn[fa[x]]]] < dfn[sdom[mn[x]]]) mn[x] = mn[fa[x]];
    return fa[x] = r;
}
void count_(int u) { sz[u] = 1; for (int k = 0; k < int(tr[u].size()); k++) { count_(tr[u][k]); sz[u] += sz[tr[u][k]]; } }

int main() {
    cin >> n >> m;
    for (int i = 0; i < m; i++) { int u, v; cin >> u >> v; g[u].push_back(v); rg[v].push_back(u); }
    dfs(1);
    for (int i = 1; i <= n; i++) { fa[i] = mn[i] = sdom[i] = i; }
    for (int i = timer_; i >= 2; i--) {           // reverse DFS order
        int w = ord_[i];
        for (int k = 0; k < int(rg[w].size()); k++) {
            int v = rg[w][k];
            if (!dfn[v]) continue;                // unreachable predecessor
            find(v);
            if (dfn[sdom[mn[v]]] < dfn[sdom[w]]) sdom[w] = sdom[mn[v]];
        }
        bucket[sdom[w]].push_back(w);
        fa[w] = par[w];
        int p = par[w];
        for (int k = 0; k < int(bucket[p].size()); k++) {   // vertices whose sdom is p
            int v = bucket[p][k];
            find(v);
            idom[v] = (sdom[mn[v]] == p) ? p : mn[v];       // mn[v] stands for "use idom of it" (fixed below)
        }
        bucket[p].clear();
    }
    for (int i = 2; i <= timer_; i++) {           // DFS order: resolve the deferred ones
        int w = ord_[i];
        if (idom[w] != sdom[w]) idom[w] = idom[idom[w]];
        tr[idom[w]].push_back(w);
    }
    count_(1);
    for (int v = 1; v <= n; v++) cout << (dfn[v] ? sz[v] : 0) << (v < n ? " " : "");
    cout << "\n";
    return 0;
}

