const int N = 100005, LOG = 17;
int n, q, a[N], root[N], ls[N * 20], rs[N * 20], cnt[N * 20], tot = 0, K;
int up[N][LOG], dep[N];
vector<int> g[N], vals;

int insert(int pre, int l, int r, int x) {
    int p = ++tot; ls[p] = ls[pre]; rs[p] = rs[pre]; cnt[p] = cnt[pre] + 1;
    if (l < r) { int mid = (l + r) / 2; if (x <= mid) ls[p] = insert(ls[pre], l, mid, x); else rs[p] = insert(rs[pre], mid + 1, r, x); }
    return p;
}
void dfs(int u, int p) {
    up[u][0] = p;
    for (int k = 1; k < LOG; k++) up[u][k] = up[up[u][k - 1]][k - 1];
    root[u] = insert(root[p], 1, K, a[u]);           // parent's version + own value
    for (int i = 0; i < int(g[u].size()); i++) { int v = g[u][i]; if (v != p) { dep[v] = dep[u] + 1; dfs(v, u); } }
}
int lca(int x, int y) {
    if (dep[x] < dep[y]) swap(x, y);
    for (int k = LOG - 1; k >= 0; k--) if (dep[x] - (1 << k) >= dep[y]) x = up[x][k];
    if (x == y) return x;
    for (int k = LOG - 1; k >= 0; k--) if (up[x][k] != up[y][k]) { x = up[x][k]; y = up[y][k]; }
    return up[x][0];
}
int kth(int u, int v, int w, int z, int l, int r, int k) {     // trees u + v - w - z
    if (l == r) return l;
    int mid = (l + r) / 2, c = cnt[ls[u]] + cnt[ls[v]] - cnt[ls[w]] - cnt[ls[z]];
    if (k <= c) return kth(ls[u], ls[v], ls[w], ls[z], l, mid, k);
    return kth(rs[u], rs[v], rs[w], rs[z], mid + 1, r, k - c);
}

int main() {
    cin >> n >> q;
    for (int i = 1; i <= n; i++) { cin >> a[i]; vals.push_back(a[i]); }
    sort(vals.begin(), vals.end()); vals.erase(unique(vals.begin(), vals.end()), vals.end());
    K = vals.size();
    for (int i = 1; i <= n; i++) a[i] = lower_bound(vals.begin(), vals.end(), a[i]) - vals.begin() + 1;
    for (int i = 1; i < n; i++) { int x, y; cin >> x >> y; g[x].push_back(y); g[y].push_back(x); }
    dfs(1, 0);                                         // root[0] = 0: the empty tree
    while (q--) {
        int u, v, k; cin >> u >> v >> k;
        int l = lca(u, v);
        cout << vals[kth(root[u], root[v], root[l], root[up[l][0]], 1, K, k) - 1] << "\n";
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

const int N = 100005;
int n, q;
long long a[N], mx[N * 4], se[N * 4], cntmx[N * 4], sum[N * 4];

void pull(int p) {
    int L = 2 * p, R = 2 * p + 1;
    sum[p] = sum[L] + sum[R];
    if (mx[L] == mx[R]) { mx[p] = mx[L]; cntmx[p] = cntmx[L] + cntmx[R]; se[p] = max(se[L], se[R]); }
    else if (mx[L] > mx[R]) { mx[p] = mx[L]; cntmx[p] = cntmx[L]; se[p] = max(se[L], mx[R]); }
    else { mx[p] = mx[R]; cntmx[p] = cntmx[R]; se[p] = max(mx[L], se[R]); }
}
void applyMin(int p, long long x) {                  // only the maximums are above x
    if (x >= mx[p]) return;
    sum[p] -= cntmx[p] * (mx[p] - x); mx[p] = x;
}
void push(int p) { applyMin(2 * p, mx[p]); applyMin(2 * p + 1, mx[p]); }
void build(int p, int l, int r) {
    if (l == r) { mx[p] = sum[p] = a[l]; se[p] = LLONG_MIN; cntmx[p] = 1; return; }
    int mid = (l + r) / 2; build(2 * p, l, mid); build(2 * p + 1, mid + 1, r); pull(p);
}
void chmin(int p, int l, int r, int x, int y, long long v) {
    if (y < l || r < x || v >= mx[p]) return;          // nothing to change
    if (x <= l && r <= y && v > se[p]) { applyMin(p, v); return; }   // only the max changes: tag here
    push(p);
    int mid = (l + r) / 2;
    chmin(2 * p, l, mid, x, y, v); chmin(2 * p + 1, mid + 1, r, x, y, v);
    pull(p);
}
long long qsum(int p, int l, int r, int x, int y) {
    if (y < l || r < x) return 0;
    if (x <= l && r <= y) return sum[p];
    push(p); int mid = (l + r) / 2;
    return qsum(2 * p, l, mid, x, y) + qsum(2 * p + 1, mid + 1, r, x, y);
}
long long qmax(int p, int l, int r, int x, int y) {
    if (y < l || r < x) return LLONG_MIN;
    if (x <= l && r <= y) return mx[p];
    push(p); int mid = (l + r) / 2;
    return max(qmax(2 * p, l, mid, x, y), qmax(2 * p + 1, mid + 1, r, x, y));
}

int main() {
    cin >> n >> q;
    for (int i = 1; i <= n; i++) cin >> a[i];
    build(1, 1, n);
    while (q--) {
        int t, l, r; cin >> t >> l >> r;
        if (t == 1) { long long x; cin >> x; chmin(1, 1, n, l, r, x); }
        else if (t == 2) cout << qsum(1, 1, n, l, r) << "\n";
        else cout << qmax(1, 1, n, l, r) << "\n";
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

const int N = 1000005;
vector<int> g[N];
int n, len_[N], son[N], ans[N];
int pool[N], *f[N], *ptr = pool;                    // shared memory: long chains are contiguous

void dfs1(int u, int p) {
    for (int k = 0; k < int(g[u].size()); k++) {
        int v = g[u][k]; if (v == p) continue;
        dfs1(v, u);
        if (len_[v] > len_[son[u]]) son[u] = v;
    }
    len_[u] = len_[son[u]] + 1;                     // vertices on the longest downward chain
}
void dfs2(int u, int p) {
    f[u][0] = 1; ans[u] = 0;
    if (son[u]) {
        f[son[u]] = f[u] + 1;                       // long child: shifted view of the same memory
        dfs2(son[u], u);
        if (f[u][ans[son[u]] + 1] > f[u][ans[u]]) ans[u] = ans[son[u]] + 1;
    }
    for (int k = 0; k < int(g[u].size()); k++) {
        int v = g[u][k]; if (v == p || v == son[u]) continue;
        f[v] = ptr; ptr += len_[v];                 // short child: its own block
        dfs2(v, u);
        for (int j = 0; j < len_[v]; j++) {         // merge, cost = short chain length
            f[u][j + 1] += f[v][j];
            if (f[u][j + 1] > f[u][ans[u]] || (f[u][j + 1] == f[u][ans[u]] && j + 1 < ans[u])) ans[u] = j + 1;
        }
    }
    if (f[u][ans[u]] == 1) ans[u] = 0;              // all depths have one vertex: smallest depth 0
}

int main() {
    cin >> n;
    for (int i = 1; i < n; i++) { int x, y; cin >> x >> y; g[x].push_back(y); g[y].push_back(x); }
    dfs1(1, 0);
    f[1] = ptr; ptr += len_[1];
    dfs2(1, 0);
    for (int i = 1; i <= n; i++) cout << ans[i] << (i < n ? " " : "");
    cout << "\n";
    return 0;
}

