const int N = 100005;
int ls[N], rs[N], dis[N], val[N], rt[N];
bool del[N];

int merge(int x, int y) {
    if (!x || !y) return x | y;
    if (val[x] > val[y] || (val[x] == val[y] && x > y)) swap(x, y);   // x = smaller root
    rs[x] = merge(rs[x], y);
    if (dis[ls[x]] < dis[rs[x]]) swap(ls[x], rs[x]);                   // keep it leftist
    dis[x] = dis[rs[x]] + 1;
    return x;
}
int find(int x) { return rt[x] == x ? x : rt[x] = find(rt[x]); }

int main() {
