            if (del[x] || del[y]) continue;
            x = find(x); y = find(y);
            if (x != y) rt[x] = rt[y] = merge(x, y);
        } else {
            if (del[x]) { cout << -1 << "\n"; continue; }
            x = find(x);
            cout << val[x] << "\n";
            del[x] = true;
            rt[x] = rt[ls[x]] = rt[rs[x]] = merge(ls[x], rs[x]);   // old root points to the new root
        }
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
const int N = 400005;
int n, cnt, head[N], to[2 * N], nx[2 * N], ec = 0, sz[N], tot, bestE, bestV;
ll wt[2 * N], K, ans = 0;
bool rem[2 * N], isReal[N];
vector<pair<int, ll>> g[N];

void addE(int u, int v, ll w) {
    to[ec] = v; wt[ec] = w; nx[ec] = head[u]; head[u] = ec++;
    to[ec] = u; wt[ec] = w; nx[ec] = head[v]; head[v] = ec++;
}
void rebuild(int u, int fa) {                    // chain of virtual vertices: degree <= 3
    int tmp = u;
    for (int i = 0; i < int(g[u].size()); i++) {
        int v = g[u][i].first;
        if (v == fa) continue;
        int nn = ++cnt;
        addE(tmp, nn, 0); addE(nn, v, g[u][i].second);
        tmp = nn;
        rebuild(v, u);
    }
}
void getSize(int u, int fa) {
    sz[u] = 1;
    for (int e = head[u]; e != -1; e = nx[e]) if (!rem[e] && to[e] != fa) { getSize(to[e], u); sz[u] += sz[to[e]]; }
}
void findEdge(int u, int fa) {
    for (int e = head[u]; e != -1; e = nx[e]) if (!rem[e] && to[e] != fa) {
        int v = to[e], val = max(sz[v], tot - sz[v]);
        if (val < bestV) { bestV = val; bestE = e; }
        findEdge(v, u);
    }
}
void collect(int u, int fa, ll dist, vector<ll> &vec) {
    if (isReal[u]) vec.push_back(dist);
    for (int e = head[u]; e != -1; e = nx[e]) if (!rem[e] && to[e] != fa) collect(to[e], u, dist + wt[e], vec);
}
void solve(int u) {
    getSize(u, 0);
    tot = sz[u];
    if (tot <= 1) return;
    bestV = INT_MAX; bestE = -1;
    findEdge(u, 0);
    int e = bestE, a = to[e ^ 1], b = to[e];
    rem[e] = rem[e ^ 1] = true;
    vector<ll> A, B;
    collect(a, 0, 0, A); collect(b, 0, wt[e], B);
    sort(B.begin(), B.end());
    for (int i = 0; i < int(A.size()); i++) ans += upper_bound(B.begin(), B.end(), K - A[i]) - B.begin();
    solve(a); solve(b);
}

int main() {
    cin >> n >> K;
    for (int i = 1; i < n; i++) { int u, v; ll w; cin >> u >> v >> w; g[u].push_back({v, w}); g[v].push_back({u, w}); } 
    for (int i = 0; i < 2 * n + 5; i++) head[i] = -1;
    for (int i = 1; i <= n; i++) isReal[i] = true;
    cnt = n;
    rebuild(1, 0);
    solve(1);
    cout << ans << "\n";                         // pairs u < v with dist(u, v) <= K
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
ll n, sq;
vector<ll> primes, vals;                          // vals: all distinct n / i
vector<ll> g0, g1;                                // prime count, prime sum, for each value
vector<int> id1, id2;

int idx(ll v) { return v <= sq ? id1[v] : id2[n / v]; }

ll S(ll v, int j) {                               // sum of phi(i), 2 <= i <= v, smallest prime factor >= primes[j]
    if (j < int(primes.size()) && primes[j] > v) return 0;
    int k = idx(v);
    ll res = (g1[k] - g0[k]);                     // all primes <= v: sum of (p - 1)
    for (int t = 0; t < j; t++) res -= primes[t] - 1;   // minus primes below primes[j]
    for (int t = j; t < int(primes.size()) && primes[t] * primes[t] <= v; t++) {
        ll p = primes[t], pe = p, phiPe = p - 1;  // p^e and phi(p^e)
        while (pe * p <= v) {
            res += phiPe * S(v / pe, t + 1) + phiPe * p;     // phi(p^e) * rest, plus phi(p^(e+1))
            pe *= p; phiPe *= p;
        }
    }
    return res;
}

int main() {
    int T;
    cin >> T;
    while (T--) {
        cin >> n;
        sq = sqrtl(n);
        while (sq * sq > n) sq--;
        while ((sq + 1) * (sq + 1) <= n) sq++;
        primes.clear();
        vector<bool> comp(sq + 2, false);
        for (ll i = 2; i <= sq; i++) if (!comp[i]) { primes.push_back(i); for (ll j = i * i; j <= sq; j += i) comp[j] = true; }
        vals.clear(); g0.clear(); g1.clear();
        id1.assign(sq + 2, 0); id2.assign(sq + 2, 0);
        for (ll l = 1, r; l <= n; l = r + 1) {
            r = n / (n / l);
            ll v = n / l;
            vals.push_back(v);
            g0.push_back(v - 1);                              // pretend all of 2..v are prime
            g1.push_back(v * (v + 1) / 2 - 1);                // 2 + 3 + ... + v (fine for v up to ~4e9)
            if (v <= sq) id1[v] = vals.size() - 1; else id2[n / v] = vals.size() - 1;
        }
        for (int j = 0; j < int(primes.size()); j++) {       // part 1: sieve out composites
            ll p = primes[j];
            for (int i = 0; i < int(vals.size()) && p * p <= vals[i]; i++) {
                int k = idx(vals[i] / p);
                g0[i] -= g0[k] - j;                           // j = number of primes below p
                ll sumBelow = 0;
                for (int t = 0; t < j; t++) sumBelow += primes[t];
                g1[i] -= p * (g1[k] - sumBelow);
            }
        }
        ll primeCount = g0[idx(n)];
        cout << primeCount << " " << (n >= 1 ? S(n, 0) + 1 : 0) << "\n";   // + phi(1) = 1
    } 
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
const ll MOD = 998244353;
ll n, ans = 0;
vector<ll> pr;

ll G(ll m) { m %= MOD; return m * ((m + 1) % MOD) % MOD * ((MOD + 1) / 2) % MOD; }   // sum of g = id

void dfs(int from, ll d, ll hd) {              // d powerful, hd = h(d)
    ans = (ans + hd * G(n / d)) % MOD;
    for (int j = from; j < int(pr.size()); j++) {
        ll p = pr[j];
        if (d > n / p / p) break;
        vector<ll> h(1, 1), pm(1, 1);          // h(p^e) and p^e mod MOD
        ll pe = 1;
        for (int e = 1; pe <= n / d / p; e++) {
            pe *= p;
            pm.push_back(pe % MOD);
            ll v = ll(e) % MOD * pm[e] % MOD;  // f(p^e) = e * p^e
            for (int t = 1; t <= e; t++) v = (v - pm[t] * h[e - t] % MOD + MOD) % MOD;
            h.push_back(v);
            if (e >= 2) dfs(j + 1, d * pe, hd * v % MOD);
        }
    }
}

int main() {
    cin >> n;
    ll lim = sqrtl(n) + 1;
    vector<bool> comp(lim + 1, false);
    for (ll i = 2; i <= lim; i++) {
        if (comp[i]) continue;
        pr.push_back(i);
        for (ll j = i * i; j <= lim; j += i) comp[j] = true;
    }
    dfs(0, 1, 1);
    cout << ans << "\n";
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
typedef vector<ll> Poly;
const ll MOD = 998244353, G = 3;
ll power(ll a, ll b) { ll r = 1; for (a %= MOD; b; b >>= 1, a = a * a % MOD) if (b & 1) r = r * a % MOD; return r; }

void ntt(Poly &a, bool inv) {
    int n = a.size();
    for (int i = 1, j = 0; i < n; i++) { int bit = n >> 1; for (; j & bit; bit >>= 1) j ^= bit; j ^= bit; if (i < j) swap(a[i], a[j]); }
    for (int len = 2; len <= n; len <<= 1) {
        ll w = power(G, (MOD - 1) / len); if (inv) w = power(w, MOD - 2);
        for (int i = 0; i < n; i += len) { ll x = 1; for (int j = 0; j < len / 2; j++) {
            ll u = a[i + j], v = a[i + j + len / 2] * x % MOD;
            a[i + j] = (u + v) % MOD; a[i + j + len / 2] = (u - v + MOD) % MOD; x = x * w % MOD; } }
    }
    if (inv) { ll ni = power(n, MOD - 2); for (int i = 0; i < n; i++) a[i] = a[i] * ni % MOD; }
}
Poly mul(Poly a, Poly b, int keep) {                    // product mod x^keep
    int n = 1; while (n < int(a.size() + b.size())) n <<= 1;
    a.resize(n); b.resize(n); ntt(a, false); ntt(b, false);
    for (int i = 0; i < n; i++) a[i] = a[i] * b[i] % MOD;
    ntt(a, true); a.resize(keep); return a;
}
Poly inverse(const Poly &a, int n) {                   // B with A*B = 1 mod x^n
    Poly b(1, power(a[0], MOD - 2));
    for (int k = 1; k < n; k <<= 1) {                  // Newton: B <- B (2 - A B)
        Poly ak(a.begin(), a.begin() + min(int(a.size()), 2 * k));
        Poly t = mul(ak, b, 2 * k);
        for (int i = 0; i < int(t.size()); i++) t[i] = (MOD - t[i]) % MOD;
        t[0] = (t[0] + 2) % MOD;
        b = mul(b, t, 2 * k);
    }
    b.resize(n); return b;
}
Poly ln(const Poly &a, int n) {                        // needs a[0] = 1
    Poly da(n, 0);
    for (int i = 1; i < min(int(a.size()), n + 1); i++) da[i - 1] = a[i] * i % MOD;   // derivative
    Poly q = mul(da, inverse(a, n), n);
    Poly r(n, 0);
    for (int i = n - 1; i >= 1; i--) r[i] = q[i - 1] * power(i, MOD - 2) % MOD;         // integral
    return r;
}
Poly expo(const Poly &a, int n) {                      // needs a[0] = 0
    Poly b(1, 1);
    for (int k = 1; k < n; k <<= 1) {                  // Newton: B <- B (1 - ln B + A)
        Poly l = ln(b, 2 * k);
        for (int i = 0; i < 2 * k; i++) l[i] = ((i < int(a.size()) ? a[i] : 0) - l[i] + MOD) % MOD;
        l[0] = (l[0] + 1) % MOD;
        b = mul(b, l, 2 * k);
    }
    b.resize(n); return b;
}

int main() {
    int type, n;
    cin >> type >> n;
    Poly a(n);
    for (int i = 0; i < n; i++) cin >> a[i]; 
    Poly r = type == 0 ? ln(a, n) : expo(a, n);
    for (int i = 0; i < n; i++) cout << r[i] << (i < n - 1 ? " " : "");
    cout << "\n";
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
void fwtOr(vector<ll> &a, int s) { int n = a.size(); for (int h = 1; h < n; h <<= 1) for (int i = 0; i < n; i += 2 * h) for (int j = i; j < i + h; j++) a[j + h] += s * a[j]; }
void fwtAnd(vector<ll> &a, int s) { int n = a.size(); for (int h = 1; h < n; h <<= 1) for (int i = 0; i < n; i += 2 * h) for (int j = i; j < i + h; j++) a[j] += s * a[j + h]; }
void fwtXor(vector<ll> &a, bool inv) {
    int n = a.size();
    for (int h = 1; h < n; h <<= 1) for (int i = 0; i < n; i += 2 * h) for (int j = i; j < i + h; j++) {
        ll x = a[j], y = a[j + h];
        a[j] = x + y; a[j + h] = x - y;
        if (inv) { a[j] /= 2; a[j + h] /= 2; }          // exact: values stay integers
    }
}
vector<ll> conv(vector<ll> a, vector<ll> b, int type) {
    if (type == 0) { fwtOr(a, 1); fwtOr(b, 1); } else if (type == 1) { fwtAnd(a, 1); fwtAnd(b, 1); } else { fwtXor(a, false); fwtXor(b, false); }
    for (int i = 0; i < int(a.size()); i++) a[i] *= b[i];
    if (type == 0) fwtOr(a, -1); else if (type == 1) fwtAnd(a, -1); else fwtXor(a, true);
    return a;
}

int main() {
    int k;
    cin >> k;
    int n = 1 << k;
    vector<ll> a(n), b(n);
    for (int i = 0; i < n; i++) cin >> a[i];
    for (int i = 0; i < n; i++) cin >> b[i];
    for (int type = 0; type < 3; type++) {
        vector<ll> c = conv(a, b, type);
        for (int i = 0; i < n; i++) cout << c[i] << (i < n - 1 ? " " : "");
        cout << "\n";
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
const ll MOD = 998244353, G = 3;
ll pw(ll a, ll e) { ll r = 1; a %= MOD; while (e) { if (e & 1) r = r * a % MOD; a = a * a % MOD; e >>= 1; } return r; }

void ntt(vector<ll> &a, bool inv) {
    int n = a.size();
    for (int i = 1, j = 0; i < n; i++) {
        int bit = n >> 1;
        for (; j & bit; bit >>= 1) j ^= bit;
        j ^= bit;
        if (i < j) swap(a[i], a[j]);
    }
    for (int len = 2; len <= n; len <<= 1) {
        ll w = pw(G, (MOD - 1) / len);
        if (inv) w = pw(w, MOD - 2);
        for (int i = 0; i < n; i += len) {
            ll wn = 1;
            for (int j = 0; j < len / 2; j++) {
                ll u = a[i + j], v = a[i + j + len / 2] * wn % MOD;
                a[i + j] = (u + v) % MOD; a[i + j + len / 2] = (u - v + MOD) % MOD;
                wn = wn * w % MOD;
            }
        }
    }
    if (inv) { ll ni = pw(n, MOD - 2); for (int i = 0; i < n; i++) a[i] = a[i] * ni % MOD; }
}
vector<ll> mul(vector<ll> a, vector<ll> b, int lim) {          // a * b mod x^lim
    int n = 1;
    while (n < int(a.size() + b.size())) n <<= 1;
    a.resize(n); b.resize(n);
    ntt(a, false); ntt(b, false);
    for (int i = 0; i < n; i++) a[i] = a[i] * b[i] % MOD;
    ntt(a, true);
    a.resize(lim);
    return a;
}
vector<ll> inverse(const vector<ll> &a, int n) {              // B <- B (2 - A B)
    vector<ll> b(1, pw(a[0], MOD - 2));
    for (int k = 1; k < n; k <<= 1) {
        int m = 2 * k;
        vector<ll> a2(a.begin(), a.begin() + min(m, int(a.size())));
        vector<ll> t = mul(mul(b, b, m), a2, m);
        b.resize(m);
        for (int i = 0; i < m; i++) b[i] = (2 * b[i] - t[i] + MOD) % MOD;
    }
    b.resize(n);
    return b;
}
vector<ll> polySqrt(const vector<ll> &a, int n) {             // B <- (B + A / B) / 2, a[0] = 1
    vector<ll> b(1, 1);
    ll inv2 = (MOD + 1) / 2;
    for (int k = 1; k < n; k <<= 1) {
        int m = 2 * k;
        vector<ll> a2(a.begin(), a.begin() + min(m, int(a.size())));
        vector<ll> t = mul(a2, inverse(b, m), m);
        b.resize(m);
        for (int i = 0; i < m; i++) b[i] = (b[i] + t[i]) % MOD * inv2 % MOD;
    } 
    b.resize(n);
    return b;
}

int main() {
    int n;
    cin >> n;
    vector<ll> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];
    vector<ll> b = polySqrt(a, n);
    for (int i = 0; i < n; i++) cout << b[i] << (i + 1 < n ? " " : "\n");
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

const double EPS = 1e-9;
int n, m;
vector<vector<double>> a;                     // a[0][1..n]: objective; a[i][0]: b_i; a[i][1..n]: row i

void pivot(int l, int e) {                    // row l leaves, column e enters
    double t = a[l][e];
    a[l][e] = 1;
    for (int j = 0; j <= n; j++) a[l][j] /= t;
    for (int i = 0; i <= m; i++) {
        if (i == l || fabs(a[i][e]) < EPS) continue;
        double f = a[i][e];
        a[i][e] = 0;
        for (int j = 0; j <= n; j++) a[i][j] -= f * a[l][j];
    }
}

int main() {
    cin >> n >> m;
    a.assign(m + 1, vector<double>(n + 1, 0));
    for (int j = 1; j <= n; j++) cin >> a[0][j];
    for (int i = 1; i <= m; i++) { for (int j = 1; j <= n; j++) cin >> a[i][j]; cin >> a[i][0]; }   // b_i >= 0 here
    while (true) {
        int e = 0;
        for (int j = 1; j <= n; j++) if (a[0][j] > EPS && (!e || j < e)) { e = j; break; }   // Bland: first positive
        if (!e) break;                                    // optimal
        int l = 0; double best = 1e18;
        for (int i = 1; i <= m; i++)
            if (a[i][e] > EPS && a[i][0] / a[i][e] < best - EPS) { best = a[i][0] / a[i][e]; l = i; } // ratio test
        if (!l) { cout << "Unbounded\n"; return 0; }
        pivot(l, e);
    }
    cout << fixed << setprecision(6) << -a[0][0] << "\n";   // the objective is stored negated
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

const int N = 2000005;
int len_[N], link_[N], nxt[N][26], sz = 1;

int extend(int last, int c) {                    // returns the state for "last + c"
    if (nxt[last][c]) {                          // already exists: reuse or clone
        int q = nxt[last][c];
        if (len_[q] == len_[last] + 1) return q;
        int cl = sz++;
        len_[cl] = len_[last] + 1;
        memcpy(nxt[cl], nxt[q], sizeof(nxt[q]));
        link_[cl] = link_[q];
        for (int p = last; p != -1 && nxt[p][c] == q; p = link_[p]) nxt[p][c] = cl;
        link_[q] = cl;
        return cl;
    }
    int cur = sz++;
    len_[cur] = len_[last] + 1;
    int p = last;
    while (p != -1 && !nxt[p][c]) { nxt[p][c] = cur; p = link_[p]; }
    if (p == -1) link_[cur] = 0;
    else {
        int q = nxt[p][c];
        if (len_[p] + 1 == len_[q]) link_[cur] = q;
        else {
            int cl = sz++;
            len_[cl] = len_[p] + 1;
            memcpy(nxt[cl], nxt[q], sizeof(nxt[q]));
            link_[cl] = link_[q];
            while (p != -1 && nxt[p][c] == q) { nxt[p][c] = cl; p = link_[p]; }
            link_[q] = link_[cur] = cl;
        }
    }
    return cur;
}

int main() {
    int k;
    cin >> k;
    link_[0] = -1;
    for (int t = 0; t < k; t++) {
        string s; cin >> s;
        int last = 0;                            // every string starts at the root
        for (int i = 0; i < int(s.size()); i++) last = extend(last, s[i] - 'a');
    }
    long long distinct = 0;
    for (int v = 1; v < sz; v++) distinct += len_[v] - len_[link_[v]];
    cout << distinct << "\n";
    return 0;
}

