struct V { double x, y, z; };
V operator-(V a, V b) { return V{a.x - b.x, a.y - b.y, a.z - b.z}; }
V cross(V a, V b) { return V{a.y * b.z - a.z * b.y, a.z * b.x - a.x * b.z, a.x * b.y - a.y * b.x}; }
double dot(V a, V b) { return a.x * b.x + a.y * b.y + a.z * b.z; }
double len(V a) { return sqrt(dot(a, a)); }
struct F { int a, b, c; };
int n;
V p[2005];
bool vis[2005][2005];

bool sees(F f, V q) { return dot(cross(p[f.b] - p[f.a], p[f.c] - p[f.a]), q - p[f.a]) > 0; }   // q outside face

int main() {
    cin >> n;
    mt19937 rng(7);
    uniform_real_distribution<double> jitter(-1e-9, 1e-9);
    for (int i = 0; i < n; i++) { cin >> p[i].x >> p[i].y >> p[i].z; p[i].x += jitter(rng); p[i].y += jitter(rng); p[i].z += jitter(rng); }
    vector<F> faces;
    faces.push_back(F{0, 1, 2}); faces.push_back(F{2, 1, 0});   // both sides of the first triangle
    for (int i = 3; i < n; i++) {
        vector<F> keep;
        for (int k = 0; k < int(faces.size()); k++) {
            F f = faces[k];
            bool v = sees(f, p[i]);
            if (!v) keep.push_back(f);
            vis[f.a][f.b] = vis[f.b][f.c] = vis[f.c][f.a] = v;   // record per directed edge
        }
        for (int k = 0; k < int(faces.size()); k++) {           // horizon: visible on one side only
            F f = faces[k];
            if (vis[f.a][f.b] && !vis[f.b][f.a]) keep.push_back(F{f.a, f.b, i});
            if (vis[f.b][f.c] && !vis[f.c][f.b]) keep.push_back(F{f.b, f.c, i});
            if (vis[f.c][f.a] && !vis[f.a][f.c]) keep.push_back(F{f.c, f.a, i});
        }
        faces = keep;
    }
    double area = 0;
    for (int k = 0; k < int(faces.size()); k++) area += len(cross(p[faces[k].b] - p[faces[k].a], p[faces[k].c] - p[faces[k].a])) / 2;
    cout << fixed << setprecision(3) << area << "\n";
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

struct V { double x, y, z; };
V operator+(V a, V b) { return V{a.x + b.x, a.y + b.y, a.z + b.z}; }
V operator-(V a, V b) { return V{a.x - b.x, a.y - b.y, a.z - b.z}; }
V operator*(V a, double t) { return V{a.x * t, a.y * t, a.z * t}; }
double dot(V a, V b) { return a.x * b.x + a.y * b.y + a.z * b.z; }
V cross(V a, V b) { return V{a.y * b.z - a.z * b.y, a.z * b.x - a.x * b.z, a.x * b.y - a.y * b.x}; }
double dist(V a, V b) { return sqrt(dot(a - b, a - b)); }

V circum3(V a, V b, V c) {                      // centre of the circle through a, b, c (in their plane)
    V ab = b - a, ac = c - a, n = cross(ab, ac);
    V t = cross(n, ab) * dot(ac, ac) + cross(ac, n) * dot(ab, ab);
    return a + t * (1.0 / (2 * dot(n, n)));
}
V circum4(V a, V b, V c, V d) {                 // solve 2 (p_i - a) . x = |p_i|^2 - |a|^2
    double M[3][4];
    V ps[3] = {b, c, d};
    for (int i = 0; i < 3; i++) {
        V q = ps[i] - a;
        M[i][0] = 2 * q.x; M[i][1] = 2 * q.y; M[i][2] = 2 * q.z;
        M[i][3] = dot(ps[i], ps[i]) - dot(a, a);
    }
    for (int col = 0; col < 3; col++) {          // Gaussian elimination
        int piv = col;
        for (int r = col; r < 3; r++) if (fabs(M[r][col]) > fabs(M[piv][col])) piv = r;
        for (int j = 0; j < 4; j++) swap(M[col][j], M[piv][j]);
        for (int r = 0; r < 3; r++) if (r != col) {
            double f = M[r][col] / M[col][col];
            for (int j = col; j < 4; j++) M[r][j] -= f * M[col][j];
        }
    }
    return V{M[0][3] / M[0][0], M[1][3] / M[1][1], M[2][3] / M[2][2]};
}

int main() {
    int n;
    cin >> n;
    vector<V> p(n);
    for (int i = 0; i < n; i++) cin >> p[i].x >> p[i].y >> p[i].z;
    mt19937 rng(11);
    shuffle(p.begin(), p.end(), rng);
    const double EPS = 1e-9;
    V c = p[0]; double r = 0;
    for (int i = 1; i < n; i++) {
        if (dist(c, p[i]) <= r + EPS) continue;
        c = p[i]; r = 0;
        for (int j = 0; j < i; j++) {
            if (dist(c, p[j]) <= r + EPS) continue;
            c = (p[i] + p[j]) * 0.5; r = dist(c, p[i]);
            for (int k = 0; k < j; k++) {
                if (dist(c, p[k]) <= r + EPS) continue;
                c = circum3(p[i], p[j], p[k]); r = dist(c, p[i]);
                for (int l = 0; l < k; l++)
                    if (dist(c, p[l]) > r + EPS) { c = circum4(p[i], p[j], p[k], p[l]); r = dist(c, p[i]); }
            }
        }
    }
    cout << fixed << setprecision(4) << r << "\n";
    return 0; 
}

#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
struct P { ll x, y; };
P operator+(P a, P b) { return {a.x + b.x, a.y + b.y}; }
P operator-(P a, P b) { return {a.x - b.x, a.y - b.y}; }
ll cross(P a, P b) { return a.x * b.y - a.y * b.x; }

vector<P> readPoly() {
    int n; cin >> n;
    vector<P> a(n);
    for (int i = 0; i < n; i++) cin >> a[i].x >> a[i].y;   // counter-clockwise
    int k = 0;
    for (int i = 1; i < n; i++) if (a[i].y < a[k].y || (a[i].y == a[k].y && a[i].x < a[k].x)) k = i;
    rotate(a.begin(), a.begin() + k, a.end());              // start at the lowest point
    a.push_back(a[0]); a.push_back(a[1]);
    return a;
}

int main() {
    vector<P> A = readPoly(), B = readPoly();
    int n = A.size() - 2, m = B.size() - 2, i = 0, j = 0;
    vector<P> r;
    while (i < n || j < m) {                                 // merge edges by angle
        r.push_back(A[i] + B[j]);
        ll c = cross(A[i + 1] - A[i], B[j + 1] - B[j]);
        if (c >= 0 && i < n) i++;
        if (c <= 0 && j < m) j++;
    }
    int k = r.size();
    vector<P> s;                                             // drop collinear vertices
    for (int t = 0; t < k; t++)
        if (cross(r[t] - r[(t + k - 1) % k], r[(t + 1) % k] - r[t]) != 0) s.push_back(r[t]);
    ll area2 = 0;
    for (int t = 0; t < int(s.size()); t++) area2 += cross(s[t], s[(t + 1) % s.size()]);
    cout << s.size() << " " << area2 << "\n";                // vertices, twice the area
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int n;
double cx[105], cy[105], cr[105];

double f(double x) {                               // length of the union of chords at x
    vector<pair<double, double>> iv;
    for (int i = 0; i < n; i++) {
        double dx = fabs(x - cx[i]);
        if (dx >= cr[i]) continue;
        double h = sqrt(cr[i] * cr[i] - dx * dx);
        iv.push_back({cy[i] - h, cy[i] + h});
    }
    sort(iv.begin(), iv.end());
    double len = 0, lo = -1e18, hi = -1e18;
    for (int i = 0; i < int(iv.size()); i++) {
        if (iv[i].first > hi) { len += hi - lo; lo = iv[i].first; hi = iv[i].second; }
        else hi = max(hi, iv[i].second);
    }
    return len + hi - lo;
}
double simpson(double l, double r, double fl, double fm, double fr) { return (r - l) * (fl + 4 * fm + fr) / 6; }
double asr(double l, double r, double fl, double fm, double fr, double whole, double eps, int depth) {
    double m = (l + r) / 2, lm = (l + m) / 2, rm = (m + r) / 2, flm = f(lm), frm = f(rm);
    double L = simpson(l, m, fl, flm, fm), R = simpson(m, r, fm, frm, fr);
    if (depth <= 0 && fabs(L + R - whole) <= 15 * eps) return L + R + (L + R - whole) / 15;
    return asr(l, m, fl, flm, fm, L, eps / 2, depth - 1) + asr(m, r, fm, frm, fr, R, eps / 2, depth - 1);
}

int main() {
    cin >> n;
    vector<pair<double, double>> xs;
    for (int i = 0; i < n; i++) { cin >> cx[i] >> cy[i] >> cr[i]; xs.push_back({cx[i] - cr[i], cx[i] + cr[i]}); }
    sort(xs.begin(), xs.end());
    double area = 0;
    for (int i = 0; i < int(xs.size());) {         // each connected x-range separately
        double l = xs[i].first, r = xs[i].second;
        int j = i;
        while (j < int(xs.size()) && xs[j].first <= r) { r = max(r, xs[j].second); j++; }
        double m = (l + r) / 2, fl = f(l), fm = f(m), fr = f(r);
        area += asr(l, r, fl, fm, fr, simpson(l, r, fl, fm, fr), 1e-7, 8);
        i = j;
    }
    cout << fixed << setprecision(3) << area << "\n";
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

struct Edge { int to; long long cap; };
int n, m;
vector<Edge> e;
vector<int> g[505];
vector<long long> orig;
int level[505], it[505];

void addEdge(int u, int v, long long c) {          // undirected: capacity both ways
    g[u].push_back(e.size()); e.push_back(Edge{v, c}); orig.push_back(c);
    g[v].push_back(e.size()); e.push_back(Edge{u, c}); orig.push_back(c);
}
bool bfs(int s, int t) {
    fill(level, level + n + 1, -1); queue<int> q; level[s] = 0; q.push(s);
    while (!q.empty()) { int u = q.front(); q.pop(); for (int k = 0; k < int(g[u].size()); k++) { Edge &x = e[g[u][k]]; if (x.cap > 0 && level[x.to] < 0) { level[x.to] = level[u] + 1; q.push(x.to); } } }
    return level[t] >= 0;
}
long long dfs(int u, int t, long long f) {
    if (u == t) return f;
    for (int &k = it[u]; k < int(g[u].size()); k++) {
        int id = g[u][k]; Edge &x = e[id];
        if (x.cap > 0 && level[x.to] == level[u] + 1) { long long got = dfs(x.to, t, min(f, x.cap)); if (got) { x.cap -= got; e[id ^ 1].cap += got; return got; } }
    }
    return 0;
}
long long maxflow(int s, int t) {
    for (int i = 0; i < int(e.size()); i++) e[i].cap = orig[i];          // fresh graph each time
    long long r = 0;
    while (bfs(s, t)) { fill(it, it + n + 1, 0); while (long long f = dfs(s, t, LLONG_MAX)) r += f; }
    return r;
}

int main() {
    cin >> n >> m;
    for (int i = 0; i < m; i++) { int u, v; long long w; cin >> u >> v >> w; addEdge(u, v, w); }
    vector<int> par(n + 1, 1);
    vector<long long> wt(n + 1, 0);
    for (int i = 2; i <= n; i++) {
        wt[i] = maxflow(i, par[i]);                 // level[] >= 0  <=>  on i's side of the cut
        for (int j = i + 1; j <= n; j++) if (par[j] == par[i] && level[j] >= 0) par[j] = i;
    }
    vector<vector<pair<int, long long>>> tr(n + 1);
    for (int i = 2; i <= n; i++) { tr[i].push_back(make_pair(par[i], wt[i])); tr[par[i]].push_back(make_pair(i, wt[i])); }
    int q; cin >> q;
    while (q--) {
        int a, b; cin >> a >> b;
        vector<long long> best(n + 1, -1);         // smallest edge on the tree path from a
        best[a] = LLONG_MAX; queue<int> qq; qq.push(a);
        while (!qq.empty()) { int u = qq.front(); qq.pop(); for (int k = 0; k < int(tr[u].size()); k++) { int v = tr[u][k].first; if (best[v] < 0) { best[v] = min(best[u], tr[u][k].second); qq.push(v); } } }
        cout << best[b] << "\n";
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

const int N = 200005;
int n, m, dfn[N], low[N], timer_ = 0, sq;
vector<int> g[N], t[2 * N], stk;
int dep[2 * N], up[2 * N][19];

void tarjan(int u) {
    dfn[u] = low[u] = ++timer_; stk.push_back(u);
    for (int k = 0; k < int(g[u].size()); k++) {
        int v = g[u][k];
        if (!dfn[v]) {
            tarjan(v);
            low[u] = min(low[u], low[v]);
            if (low[v] >= dfn[u]) {                 // a block: new square node
                ++sq;
                while (true) { int x = stk.back(); stk.pop_back(); t[sq].push_back(x); t[x].push_back(sq); if (x == v) break; }
                t[sq].push_back(u); t[u].push_back(sq);
            }
        } else low[u] = min(low[u], dfn[v]);
    }
}
void dfs(int u, int p) {
    up[u][0] = p;
    for (int k = 1; k < 19; k++) up[u][k] = up[up[u][k - 1]][k - 1];
    for (int i = 0; i < int(t[u].size()); i++) { int v = t[u][i]; if (v != p) { dep[v] = dep[u] + 1; dfs(v, u); } }
}
int lca(int a, int b) {
    if (dep[a] < dep[b]) swap(a, b);
    for (int k = 18; k >= 0; k--) if (dep[a] - (1 << k) >= dep[b]) a = up[a][k];
    if (a == b) return a;
    for (int k = 18; k >= 0; k--) if (up[a][k] != up[b][k]) { a = up[a][k]; b = up[b][k]; }
    return up[a][0];
}

