typedef long long ll;
typedef pair<ll, int> pli;
const ll INF = LLONG_MAX / 4;

int main() {
    int n, m, k;
    cin >> n >> m >> k;
    vector<vector<pair<int, ll>>> g(n + 1), rg(n + 1);
    for (int i = 0; i < m; i++) { int u, v; ll w; cin >> u >> v >> w; g[u].push_back({v, w}); rg[v].push_back({u, w}); }
    int s = 1, t = n;
    vector<ll> h(n + 1, INF);                          // h(v) = dist(v, t)
    priority_queue<pli, vector<pli>, greater<pli>> pq;
    h[t] = 0; pq.push({0, t});
    while (!pq.empty()) {
        pli c = pq.top(); pq.pop();
        if (c.first > h[c.second]) continue;
        for (int i = 0; i < int(rg[c.second].size()); i++) {
            int v = rg[c.second][i].first; ll w = rg[c.second][i].second;
            if (h[c.second] + w < h[v]) { h[v] = h[c.second] + w; pq.push({h[v], v}); }
        }
    }
    vector<int> cnt(n + 1, 0);
    vector<ll> ans;
    priority_queue<pair<ll, pair<ll, int>>, vector<pair<ll, pair<ll, int>>>, greater<pair<ll, pair<ll, int>>>> q;   // (g + h, (g, v))
    if (h[s] < INF) q.push({h[s], {0, s}});
    while (!q.empty() && int(ans.size()) < k) {
        ll gs = q.top().second.first; int u = q.top().second.second; q.pop();
        if (++cnt[u] > k) continue;
        if (u == t) ans.push_back(gs);
        for (int i = 0; i < int(g[u].size()); i++) {
            int v = g[u][i].first; ll w = g[u][i].second;
            if (h[v] < INF) q.push({gs + w + h[v], {gs + w, v}});
        }
    }
    while (int(ans.size()) < k) ans.push_back(-1);
    for (int i = 0; i < k; i++) cout << ans[i] << (i + 1 < k ? " " : "\n");
    return 0;
}

