void build(int lv, int l, int r) {                 // node covers [l, r], length a power of two
    if (l == r) return;
    int mid = (l + r) / 2;
    long long s = 0, bestTouch = LLONG_MIN, cur = 0, bestIn = LLONG_MIN;
    for (int i = mid; i >= l; i--) {               // suffixes of the left half
        s += a[i]; bestTouch = max(bestTouch, s);
        cur = max(a[i], cur + a[i]); bestIn = max(bestIn, cur);
        touch[lv][i] = bestTouch; inside[lv][i] = bestIn;
    }
    s = 0; bestTouch = LLONG_MIN; cur = 0; bestIn = LLONG_MIN;
    for (int i = mid + 1; i <= r; i++) {           // prefixes of the right half
        s += a[i]; bestTouch = max(bestTouch, s);
        cur = max(a[i], cur + a[i]); bestIn = max(bestIn, cur);
        touch[lv][i] = bestTouch; inside[lv][i] = bestIn;
    }
    build(lv + 1, l, mid); build(lv + 1, mid + 1, r);
}

