using namespace std;

const int N = 100005;
int n, q;
long long a[N], mx[N * 4], hmx[N * 4], add_[N * 4], hadd[N * 4];

void apply(int p, long long ad, long long had) {     // pending (ad, had) arrives at node p
    hmx[p] = max(hmx[p], mx[p] + had);               // old current + best prefix
    hadd[p] = max(hadd[p], add_[p] + had);
    mx[p] += ad; add_[p] += ad;
}
void push(int p) {
    apply(2 * p, add_[p], hadd[p]); apply(2 * p + 1, add_[p], hadd[p]);
    add_[p] = hadd[p] = 0;
}
void pull(int p) { mx[p] = max(mx[2 * p], mx[2 * p + 1]); hmx[p] = max(hmx[2 * p], hmx[2 * p + 1]); }
void build(int p, int l, int r) {
    if (l == r) { mx[p] = hmx[p] = a[l]; return; }
    int mid = (l + r) / 2; build(2 * p, l, mid); build(2 * p + 1, mid + 1, r); pull(p);
}
void update(int p, int l, int r, int x, int y, long long v) {
    if (y < l || r < x) return;
    if (x <= l && r <= y) { apply(p, v, max(v, 0LL)); return; }    // prefix max of one step: max(v, 0)
    push(p); int mid = (l + r) / 2;
    update(2 * p, l, mid, x, y, v); update(2 * p + 1, mid + 1, r, x, y, v); pull(p);
}
long long query(int p, int l, int r, int x, int y, bool hist) {
    if (y < l || r < x) return LLONG_MIN;
    if (x <= l && r <= y) return hist ? hmx[p] : mx[p];
    push(p); int mid = (l + r) / 2;
    return max(query(2 * p, l, mid, x, y, hist), query(2 * p + 1, mid + 1, r, x, y, hist));
}

int main() {
    cin >> n >> q;
    for (int i = 1; i <= n; i++) cin >> a[i];
    build(1, 1, n);
    while (q--) {
        int t, l, r; cin >> t >> l >> r;
        if (t == 1) { long long v; cin >> v; update(1, 1, n, l, r, v); }
        else cout << query(1, 1, n, l, r, t == 3) << "\n";
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

const int N = 100005;
int n, m, val[N], sz[N], cpar[N], dep[N], up[N][17];
bool removed[N];
vector<int> g[N];
vector<long long> F[N], Gt[N];                   // Fenwick trees, 1-based on distance + 1

void addF(vector<long long> &t, int i, long long v) { for (i++; i < int(t.size()); i += i & -i) t[i] += v; }
long long sumF(vector<long long> &t, int i) { if (i < 0) return 0; long long s = 0; for (i = min(i + 1, int(t.size()) - 1); i > 0; i -= i & -i) s += t[i]; return s; }

void dfsL(int u, int p) { up[u][0] = p; for (int k = 1; k < 17; k++) up[u][k] = up[up[u][k - 1]][k - 1]; for (int k = 0; k < int(g[u].size()); k++) { int v = g[u][k]; if (v != p) { dep[v] = dep[u] + 1; dfsL(v, u); } } }
int lca(int a, int b) {
    if (dep[a] < dep[b]) swap(a, b);
    for (int k = 16; k >= 0; k--) if (dep[a] - (1 << k) >= dep[b]) a = up[a][k];
    if (a == b) return a;
    for (int k = 16; k >= 0; k--) if (up[a][k] != up[b][k]) { a = up[a][k]; b = up[b][k]; }
    return up[a][0];
}
int dist(int a, int b) { return dep[a] + dep[b] - 2 * dep[lca(a, b)]; }
int calcSize(int u, int p) { sz[u] = 1; for (int k = 0; k < int(g[u].size()); k++) { int v = g[u][k]; if (v != p && !removed[v]) sz[u] += calcSize(v, u); } return sz[u]; }
int centroid(int u, int p, int total) {
    for (int k = 0; k < int(g[u].size()); k++) { int v = g[u][k]; if (v != p && !removed[v] && sz[v] * 2 > total) return centroid(v, u, total); }
    return u;
}
int build(int u, int parentC) {
    int total = calcSize(u, 0), c = centroid(u, 0, total);
    cpar[c] = parentC; removed[c] = true;
    F[c].assign(total + 2, 0); Gt[c].assign(total + 2, 0);
    for (int k = 0; k < int(g[c].size()); k++) { int v = g[c][k]; if (!removed[v]) build(v, c); }
    return c;
}
void change(int x, long long v) {                // add v at vertex x
    addF(F[x], 0, v);
    for (int c = x; cpar[c]; c = cpar[c]) {
        int p = cpar[c], d = dist(x, p);
        addF(F[p], d, v); addF(Gt[c], d, v);
    }
}
long long query(int x, int k) {
    long long res = sumF(F[x], k);
    for (int c = x; cpar[c]; c = cpar[c]) {
        int p = cpar[c], d = dist(x, p);
        res += sumF(F[p], k - d) - sumF(Gt[c], k - d);   // remove what c's piece already counted
    }
    return res;
}

int main() {
    cin >> n >> m;
    for (int i = 1; i <= n; i++) cin >> val[i];
    for (int i = 1; i < n; i++) { int a, b; cin >> a >> b; g[a].push_back(b); g[b].push_back(a); }
    dfsL(1, 0);
    build(1, 0);
    for (int i = 1; i <= n; i++) change(i, val[i]); 
    while (m--) {
        int t, x, y; cin >> t >> x >> y;
        if (t == 0) cout << query(x, y) << "\n";
        else { change(x, y - val[x]); val[x] = y; }
    }
    return 0;
}

