#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
const int M = 4000005;
int lc[M], rc[M], cnt = 0, n;
ll s[M];
int root[200005];

void add(int &o, int l, int r, int x, ll q) {
    if (!o) o = ++cnt;
    s[o] += q;
    if (l == r) return;
    int md = (l + r) / 2;
    if (x <= md) add(lc[o], l, md, x, q); else add(rc[o], md + 1, r, x, q);
}
int merge(int a, int b, int l, int r) {
    if (!a || !b) return a | b;
    s[a] += s[b];
    if (l == r) return a;
    int md = (l + r) / 2;
    lc[a] = merge(lc[a], lc[b], l, md); rc[a] = merge(rc[a], rc[b], md + 1, r);
    return a;
}
void split(int &a, int &b, int l, int r, int x, int y) {     // move [x, y] of tree a into tree b
    if (!a || y < l || r < x) return;
    if (x <= l && r <= y) { b = a; a = 0; return; }           // whole node moves
    if (!b) b = ++cnt;
    int md = (l + r) / 2;
    split(lc[a], lc[b], l, md, x, y); split(rc[a], rc[b], md + 1, r, x, y);
    s[a] = s[lc[a]] + s[rc[a]]; s[b] = s[lc[b]] + s[rc[b]];
}
ll query(int o, int l, int r, int x, int y) {
    if (!o || y < l || r < x) return 0;
    if (x <= l && r <= y) return s[o];
    int md = (l + r) / 2;
    return query(lc[o], l, md, x, y) + query(rc[o], md + 1, r, x, y);
}
int kth(int o, int l, int r, ll k) {
    if (l == r) return l;
    int md = (l + r) / 2;
    if (s[lc[o]] >= k) return kth(lc[o], l, md, k);
    return kth(rc[o], md + 1, r, k - s[lc[o]]);
}

int main() {
    int m, tot = 1;
    cin >> n >> m;
    for (int i = 1; i <= n; i++) { ll a; cin >> a; if (a) add(root[1], 1, n, i, a); }
    for (int i = 0; i < m; i++) {
        int op, p; cin >> op >> p;
        if (op == 0) { int x, y; cin >> x >> y; split(root[p], root[++tot], 1, n, x, y); }
        else if (op == 1) { int t; cin >> t; root[p] = merge(root[p], root[t], 1, n); root[t] = 0; }
        else if (op == 2) { int x; ll q; cin >> x >> q; add(root[p], 1, n, x, q); }
        else if (op == 3) { int x, y; cin >> x >> y; cout << query(root[p], 1, n, x, y) << "\n"; }
        else { ll k; cin >> k; cout << (s[root[p]] < k ? -1 : kth(root[p], 1, n, k)) << "\n"; }
    }
    return 0;
}

