typedef long long ll;
struct Seg {
    int l, r;
    mutable ll v;
    bool operator<(const Seg &o) const { return l < o.l; }
};
set<Seg> s;

set<Seg>::iterator split(int pos) {               // a segment now starts at pos
    set<Seg>::iterator it = s.lower_bound({pos, 0, 0});
    if (it != s.end() && it->l == pos) return it;
    --it;
    int l = it->l, r = it->r; ll v = it->v;
    s.erase(it);
    s.insert({l, pos - 1, v});
    return s.insert({pos, r, v}).first;
}
ll pw(ll a, ll e, ll m) { ll r = 1 % m; a %= m; while (e) { if (e & 1) r = r * a % m; a = a * a % m; e >>= 1; } return r; }

int main() {
    int n, m;
    cin >> n >> m;
    for (int i = 1; i <= n; i++) { ll x; cin >> x; s.insert({i, i, x}); }
    s.insert({n + 1, n + 1, 0});                   // sentinel so split(r + 1) always works
    for (int k = 0; k < m; k++) {
        int op, l, r; ll x;
        cin >> op >> l >> r >> x;
        set<Seg>::iterator itr = split(r + 1), itl = split(l);
        if (op == 1) { for (set<Seg>::iterator it = itl; it != itr; ++it) it->v += x; }
        else if (op == 2) { s.erase(itl, itr); s.insert({l, r, x}); }
        else if (op == 3) {
            vector<pair<ll, int>> v;
            for (set<Seg>::iterator it = itl; it != itr; ++it) v.push_back({it->v, it->r - it->l + 1});
            sort(v.begin(), v.end());
            for (int i = 0; i < int(v.size()); i++) { if (x <= v[i].second) { cout << v[i].first << "\n"; break; } x -= v[i].second; }
        } else {
            ll y, sum = 0;
            cin >> y;
            for (set<Seg>::iterator it = itl; it != itr; ++it) sum = (sum + (it->r - it->l + 1) % y * pw(it->v, x, y)) % y;
            cout << sum << "\n";
        }
    }
    return 0;
}

