Mat mul(const Mat &x, const Mat &y) {
    Mat r;
    for (int i = 0; i < m; i++) for (int j = 0; j < m; j++) {
        long long s = 0;
        for (int k = 0; k < m; k++) s += x.a[i][k] * y.a[k][j];
        r.a[i][j] = s % K;
    }
    return r;
}

int main() {
    long long n;
    string p;
    cin >> n >> m >> K >> p;
    vector<int> nxt(m + 1, 0);
    for (int i = 1, j = 0; i < m; i++) {              // KMP failure function (0-based pattern)
        while (j > 0 && p[i] != p[j]) j = nxt[j];
        if (p[i] == p[j]) j++;
        nxt[i + 1] = j;
    }
    Mat T;
    for (int i = 0; i < m; i++) for (int j = 0; j < m; j++) T.a[i][j] = 0;
    for (int j = 0; j < m; j++)                       // from state j, try each digit
        for (char c = '0'; c <= '9'; c++) {
            int k = j;
            while (k > 0 && p[k] != c) k = nxt[k];
            if (p[k] == c) k++;
            if (k < m) T.a[j][k]++;                   // state m (full match) is forbidden
        }
    Mat R;
    for (int i = 0; i < m; i++) for (int j = 0; j < m; j++) R.a[i][j] = (i == j) % K;
    for (; n > 0; n >>= 1, T = mul(T, T)) if (n & 1) R = mul(R, T);
    long long ans = 0;
    for (int j = 0; j < m; j++) ans += R.a[0][j];     // start in state 0, end anywhere safe
    cout << ans % K << "\n";
    return 0;
}

