typedef unsigned long long ull;
ull mix(ull x) {                                     // a fixed 64-bit scrambler (splitmix64 style)
    x += 0x9e3779b97f4a7c15ULL;
    x = (x ^ (x >> 30)) * 0xbf58476d1ce4e5b9ULL;
    x = (x ^ (x >> 27)) * 0x94d049bb133111ebULL;
    return x ^ (x >> 31);
}
vector<int> g[55];
int n, sz[55];

ull hashRooted(int u, int p) {
    ull h = 1;
    for (int k = 0; k < int(g[u].size()); k++) { int v = g[u][k]; if (v != p) h += mix(hashRooted(v, u)); }
    return h;
}
int sizes(int u, int p) { sz[u] = 1; for (int k = 0; k < int(g[u].size()); k++) { int v = g[u][k]; if (v != p) sz[u] += sizes(v, u); } return sz[u]; }

int main() {
    int T;
    cin >> T;
    vector<ull> code(T);
    for (int t = 0; t < T; t++) {
        cin >> n;
        for (int i = 1; i <= n; i++) g[i].clear();
        for (int i = 2; i <= n; i++) { int p; cin >> p; g[i].push_back(p); g[p].push_back(i); }
        sizes(1, 0);
        ull best = ULLONG_MAX;
        for (int u = 1; u <= n; u++) {               // centroids: largest piece <= n / 2
            int big = n - sz[u];
            for (int k = 0; k < int(g[u].size()); k++) { int v = g[u][k]; if (sz[v] < sz[u]) big = max(big, sz[v]); }
            if (2 * big <= n) best = min(best, hashRooted(u, 0));
        }
        code[t] = best;
        int first = t;
        for (int s = 0; s < t; s++) if (code[s] == code[t]) { first = s; break; }
        cout << first + 1 << "\n";                   // smallest index of an isomorphic tree
    }
    return 0;
}

