#include <bits/stdc++.h>
using namespace std;

typedef unsigned long long ull;
const ull P = 131, Q = 13331;

int main() {
    int n, m, a, b;
    cin >> n >> m;
    vector<string> t(n);
    for (int i = 0; i < n; i++) cin >> t[i];
    cin >> a >> b;
    vector<string> p(a);
    for (int i = 0; i < a; i++) cin >> p[i];
    ull pb = 1, qa = 1;
    for (int i = 0; i < b; i++) pb *= P;
    for (int i = 0; i < a; i++) qa *= Q;
    ull target = 0;                                 // hash of the pattern
    for (int i = 0; i < a; i++) {
        ull h = 0;
        for (int j = 0; j < b; j++) h = h * P + p[i][j];
        target = target * Q + h;
    }
    vector<vector<ull>> row(n, vector<ull>(m - b + 1));   // row[i][j] = hash of t[i][j..j+b-1]
    for (int i = 0; i < n; i++) {
        ull h = 0;
        for (int j = 0; j < m; j++) {
            h = h * P + t[i][j];
            if (j >= b) h -= pb * t[i][j - b];
            if (j >= b - 1) row[i][j - b + 1] = h;
        }
    }
    int cnt = 0;
    for (int j = 0; j + b <= m; j++) {              // slide down each column of row hashes
        ull h = 0;
        for (int i = 0; i < n; i++) {
            h = h * Q + row[i][j];
            if (i >= a) h -= qa * row[i - a][j];
            if (i >= a - 1 && h == target) cnt++;
        }
    }
    cout << cnt << "\n";
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

const long long MOD = 1000000009;
int main() {
    int n, k;
    cin >> n >> k;
    vector<long long> a(n), b(n);
    for (int i = 0; i < n; i++) cin >> a[i];
    for (int i = 0; i < n; i++) cin >> b[i];
    if ((n + k) % 2) { cout << 0 << "\n"; return 0; }
    int need = (n + k) / 2;
    sort(a.begin(), a.end()); sort(b.begin(), b.end());
    vector<vector<long long>> C(n + 1, vector<long long>(n + 1, 0));
    for (int i = 0; i <= n; i++) { C[i][0] = 1; for (int j = 1; j <= i; j++) C[i][j] = (C[i - 1][j - 1] + C[i - 1][j]) % MOD; }
    vector<long long> fact(n + 1, 1);
    for (int i = 1; i <= n; i++) fact[i] = fact[i - 1] * i % MOD;
    // dp[j] = ways to choose j forced pairs (a beats b) among the a's processed so far
    vector<long long> dp(n + 1, 0);
    dp[0] = 1;
    int smaller = 0;                                  // b's below the current a
    for (int i = 0; i < n; i++) {
        while (smaller < n && b[smaller] < a[i]) smaller++;
        for (int j = i + 1; j >= 1; j--)              // a[i] takes one of the free smaller b's
            dp[j] = (dp[j] + dp[j - 1] * max(0, smaller - (j - 1))) % MOD;
    }
    vector<long long> f(n + 1);
    for (int j = 0; j <= n; j++) f[j] = dp[j] * fact[n - j] % MOD;        // "at least j" (with multiplicity)
    long long g = 0;
    for (int i = need; i <= n; i++) {                 // binomial inversion: exactly `need`
        long long term = C[i][need] * f[i] % MOD;
        g = ((i - need) % 2 ? g - term + MOD : g + term) % MOD;
    }
    cout << g << "\n";
    return 0;
}

