        for (int m = 0; m <= full; m++) if (m >> b & 1) s[m] += s[m ^ (1 << b)];
    double ans = 0;
    for (int T = 1; T <= full; T++) {
        double miss = s[full ^ T];                   // a draw misses every bit of T
        if (1 - miss < 1e-12) { cout << "INF\n"; return 0; }
        double emin = 1 / (1 - miss);                // geometric waiting time
        ans += (__builtin_popcount(T) % 2 ? emin : -emin);
    }
    cout << fixed << setprecision(10) << ans << "\n";
    return 0;
}

