typedef long long ll;
ll f(ll a, ll b, ll c, ll n) {                       // sum_{i=0..n} floor((a i + b) / c)
    if (a == 0) return (b / c) * (n + 1);
    if (a >= c || b >= c)
        return (a / c) * n * (n + 1) / 2 + (b / c) * (n + 1) + f(a % c, b % c, c, n);
    ll m = (a * n + b) / c;
    return n * m - f(c, c - b - 1, a, m - 1);        // swap the roles of the axes
}

