struct C { ll u, v; };
C mul(C x, C y) { return C{(x.u * y.u + x.v * y.v % p * w2) % p, (x.u * y.v + x.v * y.u) % p}; }

int main() {
    int T;
    cin >> T;
    mt19937_64 rng(5);
    while (T--) {
        ll n; cin >> n >> p;
        n %= p;
        if (n == 0) { cout << 0 << "\n"; continue; }
        if (power(n, (p - 1) / 2) != 1) { cout << "Hola!\n"; continue; }   // Euler's criterion
        ll a;
        while (true) {
            a = rng() % p;
            w2 = ((a * a - n) % p + p) % p;
            if (power(w2, (p - 1) / 2) == p - 1) break;                     // a^2 - n is a non-residue
        }
        C r{1, 0}, b{a, 1};
        for (ll e = (p + 1) / 2; e; e >>= 1, b = mul(b, b)) if (e & 1) r = mul(r, b);
        ll x = r.u, y = p - x;
        if (x > y) swap(x, y);
        if (x == y) cout << x << "\n"; else cout << x << " " << y << "\n";
    }
