#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
struct Node { ll x, y, sy, sxy; };                  // #R, #U, sum of y, sum of x*y (over R steps)
Node operator*(Node a, Node b) {
    Node c;
    c.x = a.x + b.x; c.y = a.y + b.y;
    c.sy = a.sy + b.sy + a.y * b.x;
    c.sxy = a.sxy + b.sxy + a.x * b.sy + a.y * (b.x * (b.x + 1) / 2) + a.x * a.y * b.x;
    return c;
}
Node pw(Node a, ll e) { Node r = {0, 0, 0, 0}; while (e) { if (e & 1) r = r * a; a = a * a; e >>= 1; } return r; }

Node solve(ll p, ll q, ll r, ll l, Node U, Node R) {   // y = (p x + r) / q, x = 1..l, 0 <= r < q
    if (!l) return {0, 0, 0, 0};
    if (p >= q) return solve(p % q, q, r, l, U, pw(U, p / q) * R);
    ll m = (__int128(p) * l + r) / q;
    if (!m) return pw(R, l);
    ll cnt = l - (__int128(q) * m - r - 1) / p;
    return pw(R, (q - r - 1) / p) * U * solve(q, p, (q - r - 1) % p, m - 1, R, U) * pw(R, cnt);
}

int main() {
    int T;
    cin >> T;
    for (int i = 0; i < T; i++) {
        ll p, q, r, n;
        cin >> p >> q >> r >> n;
        Node U = {0, 1, 0, 0}, R = {1, 0, 0, 0};
        Node res = solve(p, q, r, n, U, R);
        cout << res.sy << " " << res.sxy << "\n";
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
const ll MOD = 998244353;
ll power(ll a, ll b) { ll r = 1; for (a %= MOD; b; b >>= 1, a = a * a % MOD) if (b & 1) r = r * a % MOD; return r; }

vector<ll> bm(const vector<ll> &s) {
    vector<ll> cur, last;                       // cur: recurrence coefficients c_1..c_L
    int lastFail = -1; ll lastDelta = 0;
    for (int i = 0; i < int(s.size()); i++) {
        ll t = 0;
        for (int j = 0; j < int(cur.size()); j++) t = (t + cur[j] * s[i - 1 - j]) % MOD;
        ll delta = (s[i] - t + MOD) % MOD;      // prediction error
        if (delta == 0) continue;
        if (lastFail < 0) { cur.assign(i + 1, 0); lastFail = i; lastDelta = delta; continue; }
        ll coef = delta * power(lastDelta, MOD - 2) % MOD;
        vector<ll> nxt(i - lastFail - 1, 0);    // shift of the old recurrence
        nxt.push_back(coef);
        for (int j = 0; j < int(last.size()); j++) nxt.push_back((MOD - coef) * last[j] % MOD);
        if (nxt.size() < cur.size()) nxt.resize(cur.size(), 0);
        for (int j = 0; j < int(cur.size()); j++) nxt[j] = (nxt[j] + cur[j]) % MOD;
        if (i - lastFail + int(last.size()) >= int(cur.size())) { last = cur; lastFail = i; lastDelta = delta; }
        cur = nxt;
    }
    return cur;
}

int main() {
    int n, more;
    cin >> n >> more;
    vector<ll> s(n);
    for (int i = 0; i < n; i++) cin >> s[i];
    vector<ll> c = bm(s);
    cout << c.size() << "\n";
    for (int k = 0; k < more; k++) {            // extend the sequence with the recurrence
        ll t = 0;
        for (int j = 0; j < int(c.size()); j++) t = (t + c[j] * s[s.size() - 1 - j]) % MOD;
        s.push_back(t);
        cout << t << (k + 1 < more ? " " : "");
    }
    cout << "\n";
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
typedef vector<ll> Poly;
const ll MOD = 998244353, G = 3;
ll power(ll a, ll b) { ll r = 1; for (a %= MOD; b; b >>= 1, a = a * a % MOD) if (b & 1) r = r * a % MOD; return r; }
void ntt(Poly &a, bool inv) {
    int n = a.size();
    for (int i = 1, j = 0; i < n; i++) { int bit = n >> 1; for (; j & bit; bit >>= 1) j ^= bit; j ^= bit; if (i < j) swap(a[i], a[j]); }
    for (int len = 2; len <= n; len <<= 1) {
        ll w = power(G, (MOD - 1) / len); if (inv) w = power(w, MOD - 2);
        for (int i = 0; i < n; i += len) { ll x = 1; for (int j = 0; j < len / 2; j++) {
            ll u = a[i + j], v = a[i + j + len / 2] * x % MOD; a[i + j] = (u + v) % MOD; a[i + j + len / 2] = (u - v + MOD) % MOD; x = x * w % MOD; } }
    }
    if (inv) { ll ni = power(n, MOD - 2); for (int i = 0; i < n; i++) a[i] = a[i] * ni % MOD; }
}
Poly mul(Poly a, Poly b) {
    if (a.empty() || b.empty()) return Poly();
    int need = a.size() + b.size() - 1, n = 1; while (n < need) n <<= 1;
    a.resize(n); b.resize(n); ntt(a, false); ntt(b, false);
    for (int i = 0; i < n; i++) a[i] = a[i] * b[i] % MOD;
    ntt(a, true); a.resize(need); return a;
}
Poly inverse(const Poly &a, int n) {
    Poly b(1, power(a[0], MOD - 2));
    for (int k = 1; k < n; k <<= 1) {
        Poly ak(a.begin(), a.begin() + min(int(a.size()), 2 * k));
        Poly t = mul(ak, b); t.resize(2 * k);
        for (int i = 0; i < 2 * k; i++) t[i] = (MOD - t[i]) % MOD;
        t[0] = (t[0] + 2) % MOD;
        b = mul(b, t); b.resize(2 * k);
    }
    b.resize(n); return b;
}
Poly modp(const Poly &a, const Poly &b) {            // a mod b
    int n = a.size(), m = b.size();
    if (n < m) return a;
    Poly ra(a.rbegin(), a.rend()), rb(b.rbegin(), b.rend());
    ra.resize(n - m + 1);
    Poly q = mul(ra, inverse(rb, n - m + 1)); q.resize(n - m + 1);
    reverse(q.begin(), q.end());
    Poly qb = mul(q, b), r(m - 1);
    for (int i = 0; i < m - 1; i++) r[i] = (a[i] - qb[i] + MOD) % MOD;
    return r;
}
vector<Poly> tree_;
vector<ll> xs, ans;
void build(int p, int l, int r) {
    if (l == r) { tree_[p] = Poly{(MOD - xs[l]) % MOD, 1}; return; }
    int mid = (l + r) / 2;
    build(2 * p, l, mid); build(2 * p + 1, mid + 1, r);
    tree_[p] = mul(tree_[2 * p], tree_[2 * p + 1]);
}
void down(int p, int l, int r, const Poly &rem) {
    Poly cur = modp(rem, tree_[p]);
    if (l == r) { ans[l] = cur.empty() ? 0 : cur[0]; return; }
    int mid = (l + r) / 2;
    down(2 * p, l, mid, cur); down(2 * p + 1, mid + 1, r, cur); 
}

int main() {
    int n, m;
    cin >> n >> m;
    Poly a(n);
    for (int i = 0; i < n; i++) cin >> a[i];
    xs.resize(m); ans.resize(m);
    for (int i = 0; i < m; i++) cin >> xs[i];
    tree_.assign(4 * m, Poly());
    build(1, 0, m - 1);
    down(1, 0, m - 1, a);
    for (int i = 0; i < m; i++) cout << ans[i] << (i + 1 < m ? " " : "");
    cout << "\n";
    return 0;
}

