#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
int n, k;
ll s[100005], prevRow[100005], curRow[100005];

ll cost(int j, int i) { return (s[i] - s[j]) * (s[i] - s[j]); }
void solve(int l, int r, int optL, int optR) {   // fill curRow[l..r], best j in [optL, optR]
    if (l > r) return;
    int mid = (l + r) / 2, best = optL;
    ll bestVal = LLONG_MAX;
    for (int j = optL; j <= min(mid - 1, optR); j++) {
        if (prevRow[j] == LLONG_MAX) continue;
        ll v = prevRow[j] + cost(j, mid);
        if (v < bestVal) { bestVal = v; best = j; }
    }
    curRow[mid] = bestVal;
    solve(l, mid - 1, optL, best);              // left half: opt <= best
    solve(mid + 1, r, best, optR);              // right half: opt >= best
}

int main() {
    cin >> n >> k;
    for (int i = 1; i <= n; i++) { ll x; cin >> x; s[i] = s[i - 1] + x; }
    for (int i = 0; i <= n; i++) prevRow[i] = (i == 0 ? 0 : LLONG_MAX);
    for (int g = 1; g <= k; g++) {
        curRow[0] = LLONG_MAX;
        solve(1, n, 0, n - 1);
        for (int i = 0; i <= n; i++) prevRow[i] = curRow[i];
    }
    cout << prevRow[n] << "\n";
    return 0;
}

