typedef long long ll;
const ll NEG = LLONG_MIN / 4;
int n;
typedef vector<vector<ll>> Mat;
Mat mul(const Mat &a, const Mat &b) {
    Mat c(n, vector<ll>(n, NEG));
    for (int i = 0; i < n; i++) for (int k = 0; k < n; k++) {
        if (a[i][k] == NEG) continue;
        for (int j = 0; j < n; j++) if (b[k][j] != NEG) c[i][j] = max(c[i][j], a[i][k] + b[k][j]);
    }
    return c;
}

int main() {
    long long L;
    cin >> n >> L;
    Mat A(n, vector<ll>(n, NEG));
    for (int i = 0; i < n; i++) for (int j = 0; j < n; j++) { string s; cin >> s; if (s != "x") A[i][j] = stoll(s); }
    Mat R(n, vector<ll>(n, NEG));
    for (int i = 0; i < n; i++) R[i][i] = 0;            // (max,+) identity
    for (; L > 0; L >>= 1, A = mul(A, A)) if (L & 1) R = mul(R, A);
    ll best = NEG;
    for (int i = 0; i < n; i++) for (int j = 0; j < n; j++) best = max(best, R[i][j]);
    if (best == NEG) cout << "none\n"; else cout << best << "\n";
    return 0;
}

