typedef long long ll;
int n, m;
char g[15][15];

int main() {
    cin >> n >> m;
    int ex = -1, ey = -1;
    for (int i = 0; i < n; i++) for (int j = 0; j < m; j++) { cin >> g[i][j]; if (g[i][j] == '.') { ex = i; ey = j; } }
    unordered_map<ll, ll> cur, nxt;
    cur[0] = 1;
    ll ans = 0;
    for (int i = 0; i < n; i++) {
        nxt.clear();
        for (unordered_map<ll, ll>::iterator it = cur.begin(); it != cur.end(); ++it) nxt[it->first << 2] += it->second;   // new row
        swap(cur, nxt);
        for (int j = 0; j < m; j++) {
            nxt.clear();
            bool down = i + 1 < n && g[i + 1][j] == '.', right = j + 1 < m && g[i][j + 1] == '.';
            for (unordered_map<ll, ll>::iterator it = cur.begin(); it != cur.end(); ++it) {
                ll s = it->first, v = it->second;
                ll L = (s >> (2 * j)) & 3, U = (s >> (2 * (j + 1))) & 3;
                ll base = s - (L << (2 * j)) - (U << (2 * (j + 1)));
                if (g[i][j] == '*') { if (!L && !U) nxt[s] += v; continue; }
                if (!L && !U) { if (down && right) nxt[base | 1LL << (2 * j) | 2LL << (2 * (j + 1))] += v; }
                else if (!L || !U) {
                    ll c = L | U;
                    if (down) nxt[base | c << (2 * j)] += v;
                    if (right) nxt[base | c << (2 * (j + 1))] += v;
                } else if (L == 1 && U == 1) {           // partner 2 of U becomes 1
                    int bal = 0;
                    for (int k = j + 1; ; k++) {
                        ll c = (s >> (2 * k)) & 3;
                        if (c == 1) bal++; else if (c == 2) bal--;
                        if (!bal) { nxt[base - (1LL << (2 * k))] += v; break; }
                    }
                } else if (L == 2 && U == 2) {           // partner 1 of L becomes 2
                    int bal = 0;
                    for (int k = j; ; k--) {
                        ll c = (s >> (2 * k)) & 3;
                        if (c == 2) bal++; else if (c == 1) bal--;
                        if (!bal) { nxt[base + (1LL << (2 * k))] += v; break; }
                    }
                } else if (L == 2 && U == 1) nxt[base] += v;
                else if (i == ex && j == ey && base == 0) ans += v;   // L = 1, U = 2: close the loop
            }
            swap(cur, nxt);
        }
    }
    cout << ans << "\n";
    return 0;
}

