long long A[N], B[N];                            // two Fenwick trees for range add / range sum

void dfs(int u, int p) {
    tin[u] = ++timer_;
    for (int k = 0; k < int(g[u].size()); k++) if (g[u][k] != p) dfs(g[u][k], u);
    tout[u] = timer_;
}
void upd(long long *t, int i, long long v) { for (; i <= n; i += i & -i) t[i] += v; }
long long qry(long long *t, int i) { long long s = 0; for (; i > 0; i -= i & -i) s += t[i]; return s; }
void rangeAdd(int l, int r, long long v) { upd(A, l, v); upd(A, r + 1, -v); upd(B, l, v * l); upd(B, r + 1, -v * (r + 1)); }
long long prefix(int x) { return qry(A, x) * (x + 1) - qry(B, x); }
long long rangeSum(int l, int r) { return prefix(r) - prefix(l - 1); }

