        else if (op == 3) { long long x; cin >> x; rangeAdd(tin[u], tin[u], x); } // one vertex
        else if (op == 2) cout << rangeSum(tin[u], tin[u]) << "\n";              // one vertex
        else cout << rangeSum(tin[u], tout[u]) << "\n";                          // whole subtree
    }
