const int N = 100005, BITS = 6, M = N * (BITS + 2);
int ch[M][2], cnt[M], root[N], tot = 0;

int insert(int pre, int x) {                    // copy the path of x
    int rt = ++tot, cur = rt;
    for (int b = BITS - 1; b >= 0; b--) {
        int c = (x >> b) & 1;
        ch[cur][0] = ch[pre][0]; ch[cur][1] = ch[pre][1]; cnt[cur] = cnt[pre] + 1;
        ch[cur][c] = ++tot;
        cur = ch[cur][c]; pre = ch[pre][c];
    }
    cnt[cur] = cnt[pre] + 1;
    return rt;
}
int query(int u, int v, int x) {                // max x ^ a over versions v minus u
    int res = 0;
    for (int b = BITS - 1; b >= 0; b--) {
        int c = (x >> b) & 1;
        if (cnt[ch[v][c ^ 1]] - cnt[ch[u][c ^ 1]] > 0) { res |= 1 << b; u = ch[u][c ^ 1]; v = ch[v][c ^ 1]; }
        else { u = ch[u][c]; v = ch[v][c]; }
    }
    return res;
}

int main() {
    int n, q;
    cin >> n >> q;
    for (int i = 1; i <= n; i++) { int a; cin >> a; root[i] = insert(root[i - 1], a); }
    while (q--) { int l, r, x; cin >> l >> r >> x; cout << query(root[l - 1], root[r], x) << "\n"; }
    return 0;
}

