void update(int o, int l, int r, int i, int x) {
    if (l == r) { mx[o] = x; return; }
    int m = (l + r) / 2;
    if (i <= m) update(2 * o, l, m, i, x); else update(2 * o + 1, m + 1, r, i, x);
    mx[o] = max(mx[2 * o], mx[2 * o + 1]);
}
int firstAtLeast(int o, int l, int r, int L, int x) {   // first i >= L with a[i] >= x
    if (r < L || mx[o] < x) return -1;
    if (l == r) return l;
    int m = (l + r) / 2;
    int res = firstAtLeast(2 * o, l, m, L, x);
    if (res != -1) return res;
    return firstAtLeast(2 * o + 1, m + 1, r, L, x);
}

