}

#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
const ll INF = LLONG_MAX / 4;
int n;
ll w[505][505], lx[505], ly[505], slack[505];
int matchY[505], pre[505];                       // matchY[j]: left vertex matched to right j
bool visY[505];

void augment(int start) {                         // BFS version, O(n^2) per start vertex
    fill(visY, visY + n + 1, false);
    fill(slack, slack + n + 1, INF);
    int y = 0;
    matchY[0] = start;                            // virtual right vertex 0 holds the new left vertex
    while (true) {
        visY[y] = true;
        int x = matchY[y], nextY = 0;
        ll delta = INF;
        for (int j = 1; j <= n; j++) {
            if (visY[j]) continue;
            ll gap = lx[x] + ly[j] - w[x][j];
            if (gap < slack[j]) { slack[j] = gap; pre[j] = y; }
            if (slack[j] < delta) { delta = slack[j]; nextY = j; }
        }
        for (int j = 0; j <= n; j++) {            // move labels: a new tight edge appears
            if (visY[j]) { lx[matchY[j]] -= delta; ly[j] += delta; }
            else slack[j] -= delta;
        }
        y = nextY;
        if (matchY[y] == 0) break;                // free right vertex reached
    }
    while (y) { matchY[y] = matchY[pre[y]]; y = pre[y]; }   // flip the path
}

int main() {
    cin >> n;
    for (int i = 1; i <= n; i++) for (int j = 1; j <= n; j++) cin >> w[i][j];
    for (int i = 1; i <= n; i++) { lx[i] = -INF; for (int j = 1; j <= n; j++) lx[i] = max(lx[i], w[i] [j]); }
    for (int i = 1; i <= n; i++) augment(i);
    ll total = 0;
    for (int j = 1; j <= n; j++) total += w[matchY[j]][j];
    cout << total << "\n";
    return 0;
}

