bool bfs() {
    queue<int> q;
    bool found = false;
    for (int u = 1; u <= nl; u++) { if (!mL[u]) { dis[u] = 0; q.push(u); } else dis[u] = -1; }
    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (int i = 0; i < int(adj[u].size()); i++) {
            int w = mR[adj[u][i]];
            if (!w) found = true;                       // a free right vertex is reachable
            else if (dis[w] < 0) { dis[w] = dis[u] + 1; q.push(w); }
        }
    }
    return found;
}
bool dfs(int u) {
    for (; it[u] < int(adj[u].size()); it[u]++) {
        int v = adj[u][it[u]], w = mR[v];
        if (!w || (dis[w] == dis[u] + 1 && dfs(w))) { mL[u] = v; mR[v] = u; return true; }
    }
    dis[u] = -1;                                        // dead end for this phase
    return false;
}

