#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
const ll NEG = LLONG_MIN / 4;
const int N = 100005;
struct M { ll a[2][2]; };
M mul(const M &x, const M &y) {                       // (max, +) product
    M r;
    for (int i = 0; i < 2; i++) for (int j = 0; j < 2; j++) r.a[i][j] = max(x.a[i][0] + y.a[0][j], x.a[i][1] + y.a[1][j]);
    return r;
}
int n, q, fa[N], son[N], sz[N], top[N], dfn[N], rk[N], endPos[N], cnt = 0;
ll w[N], g[N][2], f[N][2];
vector<int> adj[N];
M tr[N * 4];

void dfs1(int u, int p) {
    fa[u] = p; sz[u] = 1;
    for (int k = 0; k < int(adj[u].size()); k++) { int v = adj[u][k]; if (v == p) continue; dfs1(v, u); sz[u] += sz[v]; if (sz[v] > sz[son[u]]) son[u] = v; }
}
void dfs2(int u, int t) {
    top[u] = t; dfn[u] = ++cnt; rk[cnt] = u; endPos[t] = cnt;
    if (son[u]) dfs2(son[u], t);
    for (int k = 0; k < int(adj[u].size()); k++) { int v = adj[u][k]; if (v != fa[u] && v != son[u]) dfs2(v, v); }
}
void dp(int u) {                                      // initial f and g
    f[u][0] = 0; f[u][1] = w[u]; g[u][0] = 0; g[u][1] = w[u];
    for (int k = 0; k < int(adj[u].size()); k++) {
        int v = adj[u][k]; if (v == fa[u]) continue;
        dp(v);
        f[u][0] += max(f[v][0], f[v][1]); f[u][1] += f[v][0];
        if (v != son[u]) { g[u][0] += max(f[v][0], f[v][1]); g[u][1] += f[v][0]; }
    }
}
M leafMat(int u) { M m; m.a[0][0] = m.a[0][1] = g[u][0]; m.a[1][0] = g[u][1]; m.a[1][1] = NEG; return m; }
void build(int p, int l, int r) {
    if (l == r) { tr[p] = leafMat(rk[l]); return; }
    int mid = (l + r) / 2; build(2 * p, l, mid); build(2 * p + 1, mid + 1, r); tr[p] = mul(tr[2 * p], tr[2 * p + 1]);
}
void update(int p, int l, int r, int x) {
    if (l == r) { tr[p] = leafMat(rk[l]); return; }
    int mid = (l + r) / 2;
    if (x <= mid) update(2 * p, l, mid, x); else update(2 * p + 1, mid + 1, r, x);
    tr[p] = mul(tr[2 * p], tr[2 * p + 1]);
}
M query(int p, int l, int r, int x, int y) {
    if (x <= l && r <= y) return tr[p];
    int mid = (l + r) / 2;
    if (y <= mid) return query(2 * p, l, mid, x, y);
    if (x > mid) return query(2 * p + 1, mid + 1, r, x, y);
    return mul(query(2 * p, l, mid, x, y), query(2 * p + 1, mid + 1, r, x, y));
}
void topValues(int t, ll &f0, ll &f1) {               // chain product applied to (0, -inf)
    M m = query(1, 1, n, dfn[t], endPos[t]);
    f0 = m.a[0][0]; f1 = m.a[1][0];
} 
void change(int x, ll y) {
    g[x][1] += y - w[x]; w[x] = y;
    while (x) {
        int t = top[x];
        ll o0, o1; topValues(t, o0, o1);
        update(1, 1, n, dfn[x]);
        ll n0, n1; topValues(t, n0, n1);
        int p = fa[t];
        if (p) { g[p][0] += max(n0, n1) - max(o0, o1); g[p][1] += n0 - o0; }   // light edge into p
        x = p;
    }
}

int main() {
    cin >> n >> q;
    for (int i = 1; i <= n; i++) cin >> w[i];
    for (int i = 1; i < n; i++) { int a, b; cin >> a >> b; adj[a].push_back(b); adj[b].push_back(a); }
    dfs1(1, 0); dfs2(1, 1); dp(1); build(1, 1, n);
    while (q--) {
        int x; ll y; cin >> x >> y;
        change(x, y);
        ll f0, f1; topValues(1, f0, f1);
        cout << max(f0, f1) << "\n";
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
const ll MOD = 998244353;
ll C[60][60];
ll power(ll a, ll b) { ll r = 1; for (a %= MOD; b; b >>= 1, a = a * a % MOD) if (b & 1) r = r * a % MOD; return r; }
ll ways(int x1, int y1, int x2, int y2) { if (x2 < x1 || y2 < y1) return 0; return C[(x2 - x1) + (y2 - y1)][x2 - x1]; }

int main() {
    for (int i = 0; i < 60; i++) { C[i][0] = 1; for (int j = 1; j <= i; j++) C[i][j] = (C[i - 1][j - 1] + C[i - 1][j]) % MOD; }
    int k;
    cin >> k;
    vector<int> ax(k), ay(k), bx(k), by(k);
    for (int i = 0; i < k; i++) cin >> ax[i] >> ay[i];
    for (int i = 0; i < k; i++) cin >> bx[i] >> by[i];
    vector<vector<ll>> m(k, vector<ll>(k));
    for (int i = 0; i < k; i++) for (int j = 0; j < k; j++) m[i][j] = ways(ax[i], ay[i], bx[j], by[j]);
    ll det = 1;
    for (int c = 0; c < k; c++) {                 // Gaussian elimination mod p
        int piv = -1;
        for (int r = c; r < k; r++) if (m[r][c]) { piv = r; break; }
        if (piv < 0) { det = 0; break; }
        if (piv != c) { swap(m[piv], m[c]); det = (MOD - det) % MOD; }
        det = det * m[c][c] % MOD;
        ll inv = power(m[c][c], MOD - 2);
        for (int r = c + 1; r < k; r++) {
            ll f = m[r][c] * inv % MOD;
            for (int j = c; j < k; j++) m[r][j] = ((m[r][j] - f * m[c][j]) % MOD + MOD) % MOD;
        }
    }
    cout << det << "\n";
    return 0;
}

