const long long MOD = 1000000007;
int main() {
    int n;
    cin >> n;
    vector<long long> p(n + 1, 0);
    p[0] = 1;
    for (int i = 1; i <= n; i++) {
        long long s = 0;
        for (int j = 1; ; j++) {
            int g1 = j * (3 * j - 1) / 2, g2 = j * (3 * j + 1) / 2;   // generalised pentagonal numbers
            if (g1 > i) break;
            long long t = p[i - g1] + (g2 <= i ? p[i - g2] : 0);
            s += (j % 2 ? t : -t);                                // signs + + - - + + ...
        }
        p[i] = (s % MOD + MOD) % MOD;
    }
    cout << p[n] << "\n";
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
int main() {
    int n;
    cin >> n;
    int N = 1 << n;
    vector<vector<ll>> A(n + 1, vector<ll>(N, 0)), B(n + 1, vector<ll>(N, 0)), C(n + 1, vector<ll>(N, 0));
    for (int s = 0; s < N; s++) { ll x; cin >> x; A[__builtin_popcount(s)][s] = x; }
    for (int s = 0; s < N; s++) { ll x; cin >> x; B[__builtin_popcount(s)][s] = x; }
    for (int r = 0; r <= n; r++)                                   // OR (zeta) transform per rank
        for (int b = 0; b < n; b++) for (int s = 0; s < N; s++)
            if (s >> b & 1) { A[r][s] += A[r][s ^ (1 << b)]; B[r][s] += B[r][s ^ (1 << b)]; }
    for (int s = 0; s < N; s++)
        for (int k = 0; k <= n; k++)
            for (int i = 0; i <= k; i++) C[k][s] += A[i][s] * B[k - i][s];   // multiply by rank
    for (int r = 0; r <= n; r++)                                   // inverse (Möbius) transform
        for (int b = 0; b < n; b++) for (int s = 0; s < N; s++)
            if (s >> b & 1) C[r][s] -= C[r][s ^ (1 << b)];
    for (int s = 0; s < N; s++) cout << C[__builtin_popcount(s)][s] << (s + 1 < N ? " " : "");
    cout << "\n";
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
int n, q, s, idOut[400005], idIn[400005], cntV;
vector<pair<int, ll>> g[2000005];

void build(int p, int l, int r) {                 // node ids: real vertices are 1..n
    if (l == r) { idOut[p] = idIn[p] = l; return; }
    idOut[p] = ++cntV; idIn[p] = ++cntV;
    int mid = (l + r) / 2;
    build(2 * p, l, mid); build(2 * p + 1, mid + 1, r);
    g[idOut[p]].push_back(make_pair(idOut[2 * p], 0LL)); g[idOut[p]].push_back(make_pair(idOut[2 * p + 1], 0LL));   // out-tree: down
    g[idIn[2 * p]].push_back(make_pair(idIn[p], 0LL)); g[idIn[2 * p + 1]].push_back(make_pair(idIn[p], 0LL));       // in-tree: up
}
void link(int p, int l, int r, int x, int y, int u, ll w, bool toRange) {
    if (y < l || r < x) return;
    if (x <= l && r <= y) {
        if (toRange) g[u].push_back(make_pair(idOut[p], w));    // u -> whole node
        else g[idIn[p]].push_back(make_pair(u, w));             // whole node -> u
        return;
    }
    int mid = (l + r) / 2;
    link(2 * p, l, mid, x, y, u, w, toRange); link(2 * p + 1, mid + 1, r, x, y, u, w, toRange);
}

int main() {
    cin >> n >> q >> s;
    cntV = n;
    build(1, 1, n);
    while (q--) {
        int t; cin >> t;
        if (t == 1) { int u, v; ll w; cin >> u >> v >> w; g[u].push_back(make_pair(v, w)); }
        else { int u, l, r; ll w; cin >> u >> l >> r >> w; link(1, 1, n, l, r, u, w, t == 2); }
    }
    vector<ll> dist(cntV + 1, LLONG_MAX);
    priority_queue<pair<ll, int>, vector<pair<ll, int>>, greater<pair<ll, int>>> pq;
    dist[s] = 0; pq.push(make_pair(0LL, s));
    while (!pq.empty()) {
        ll dd = pq.top().first; int u = pq.top().second; pq.pop();
        if (dd > dist[u]) continue;
        for (int k = 0; k < int(g[u].size()); k++) {
            int v = g[u][k].first; ll nd = dd + g[u][k].second;
            if (nd < dist[v]) { dist[v] = nd; pq.push(make_pair(nd, v)); }
        }
    }
    for (int i = 1; i <= n; i++) cout << (dist[i] == LLONG_MAX ? -1 : dist[i]) << (i < n ? " " : "");
    cout << "\n";
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int n, m, k, V, dfn[200005], low[200005], scc[200005], timer_ = 0, sccCnt = 0;
vector<int> g[200005], stk;
bool onStk[200005];
int lit(int v, bool val) { return 2 * v + (val ? 0 : 1); }        // node for "v == val"
void imply(int a, int b) { g[a].push_back(b); g[b ^ 1].push_back(a ^ 1); }   // a -> b and not b -> not a
void tarjan(int u) {
    dfn[u] = low[u] = ++timer_; stk.push_back(u); onStk[u] = true;
    for (int i = 0; i < int(g[u].size()); i++) {
        int v = g[u][i];
        if (!dfn[v]) { tarjan(v); low[u] = min(low[u], low[v]); }
        else if (onStk[v]) low[u] = min(low[u], dfn[v]);
    }
    if (low[u] == dfn[u]) { ++sccCnt; while (true) { int x = stk.back(); stk.pop_back(); onStk[x] = false; scc[x] = sccCnt; if (x == u) break; } }
}

int main() {
    cin >> n >> m >> k;
    V = n;                                          // variables 1..n, prefix variables after them
    vector<pair<int, int>> cls(m);
    for (int i = 0; i < m; i++) cin >> cls[i].first >> cls[i].second;
    vector<vector<int>> groups(k);
    for (int i = 0; i < k; i++) { int s; cin >> s; groups[i].resize(s); for (int j = 0; j < s; j++) cin >> groups[i][j]; }
    for (int i = 0; i < m; i++) {                   // clause a OR b: not a -> b
        int a = cls[i].first, b = cls[i].second;
        imply(lit(abs(a), a < 0), lit(abs(b), b > 0));
    }
    for (int i = 0; i < k; i++) {
        int prevP = -1;
        for (int j = 0; j < int(groups[i].size()); j++) {
            int x = groups[i][j], P = ++V;          // P = some of the first j+1 is true
            imply(lit(x, true), lit(P, true));
            if (prevP > 0) { imply(lit(prevP, true), lit(P, true)); imply(lit(prevP, true), lit(x, false)); }
            prevP = P;
        }
    }
    for (int u = 2; u <= 2 * V + 1; u++) if (!dfn[u]) tarjan(u);
    bool ok = true;
    for (int v = 1; v <= V; v++) if (scc[2 * v] == scc[2 * v + 1]) ok = false;
    cout << (ok ? "YES" : "NO") << "\n";
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
const ll INF = LLONG_MAX / 4;
int main() {
    int n, m;
    cin >> n >> m;
    vector<array<ll, 3>> e(m);
    vector<vector<pair<int, ll>>> g(n + 1);
    for (int i = 0; i < m; i++) { cin >> e[i][0] >> e[i][1] >> e[i][2]; g[e[i] [0]].push_back(make_pair(int(e[i][1]), e[i][2])); }
    vector<ll> h(n + 1, 0);                        // Bellman-Ford from a virtual source: start all at 0
    for (int it = 0; it < n; it++) {
        bool changed = false;
        for (int i = 0; i < m; i++) if (h[e[i][0]] + e[i][2] < h[e[i][1]]) { h[e[i][1]] = h[e[i][0]] + e[i][2]; changed = true; }
        if (!changed) break;
        if (it == n - 1) { cout << -1 << "\n"; return 0; }   // still improving: negative cycle
    }
    for (int s = 1; s <= n; s++) {
        vector<ll> dist(n + 1, INF);
        priority_queue<pair<ll, int>, vector<pair<ll, int>>, greater<pair<ll, int>>> pq;
        dist[s] = 0; pq.push(make_pair(0LL, s));
        while (!pq.empty()) {
            ll dd = pq.top().first; int u = pq.top().second; pq.pop();
            if (dd > dist[u]) continue;
            for (int k = 0; k < int(g[u].size()); k++) {
                int v = g[u][k].first; ll w2 = g[u][k].second + h[u] - h[v];   // reweighted, >= 0
                if (dd + w2 < dist[v]) { dist[v] = dd + w2; pq.push(make_pair(dist[v], v)); }
            }
        }
        for (int v = 1; v <= n; v++) {
            if (dist[v] == INF) cout << "x"; else cout << dist[v] - h[s] + h[v];   // undo the potentials
            cout << (v < n ? " " : "");
        }
        cout << "\n";
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

const int M = 5000005;
int ls[M], rs[M], val[M], pri[M], sz[M], cnt = 0, root[500005];
mt19937 rng(97);

int copyNode(int x) { ++cnt; ls[cnt] = ls[x]; rs[cnt] = rs[x]; val[cnt] = val[x]; pri[cnt] = pri[x]; sz[cnt] = sz[x]; return cnt; }
int newNode(int v) { ++cnt; val[cnt] = v; pri[cnt] = rng(); sz[cnt] = 1; ls[cnt] = rs[cnt] = 0; return cnt; }
void up(int x) { sz[x] = sz[ls[x]] + sz[rs[x]] + 1; }
void split(int t, int k, int &a, int &b) {                 // copy every node we change
    if (!t) { a = b = 0; return; }
    if (val[t] <= k) { a = copyNode(t); split(rs[a], k, rs[a], b); up(a); }
    else { b = copyNode(t); split(ls[b], k, a, ls[b]); up(b); }
}
int merge(int a, int b) {                                  // a, b are already fresh copies
    if (!a || !b) return a | b;
    if (pri[a] > pri[b]) { rs[a] = merge(rs[a], b); up(a); return a; }
    ls[b] = merge(a, ls[b]); up(b); return b;
}
int kth(int t, int k) { while (true) { if (k <= sz[ls[t]]) t = ls[t]; else if (k == sz[ls[t]] + 1) return val[t]; else { k -= sz[ls[t]] + 1; t = rs[t]; } } }

int main() {
    int n;
    cin >> n;
    for (int i = 1; i <= n; i++) {
        int v, op, x, a, b, c;
        cin >> v >> op >> x;
        int r = root[v];
        if (op == 1) { split(r, x, a, b); r = merge(merge(a, newNode(x)), b); }
        else if (op == 2) {
            split(r, x, a, c); split(a, x - 1, a, b);
            if (b) b = merge(ls[b], rs[b]);                // drop one copy (b is a fresh copy)
            r = merge(merge(a, b), c);
        }
        else if (op == 3) { split(r, x - 1, a, b); cout << sz[a] + 1 << "\n"; }
        else if (op == 4) cout << kth(r, x) << "\n";
        else if (op == 5) { split(r, x - 1, a, b); cout << (sz[a] ? kth(a, sz[a]) : -2147483647) << "\n"; }
        else { split(r, x, a, b); cout << (sz[b] ? kth(b, 1) : 2147483647) << "\n"; }
        root[i] = (op <= 2) ? r : root[v];                 // queries do not change the set
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int n;
double x[1005], y[1005], w[1005];

double energy(double px, double py) {            // the function to minimise
    double s = 0;
    for (int i = 0; i < n; i++) s += w[i] * sqrt((px - x[i]) * (px - x[i]) + (py - y[i]) * (py - y[i]));
    return s;
}

int main() {
    cin >> n;
    double cx = 0, cy = 0, W = 0;
    for (int i = 0; i < n; i++) { cin >> x[i] >> y[i] >> w[i]; cx += x[i] * w[i]; cy += y[i] * w[i]; W += w[i]; }
    cx /= W; cy /= W;                             // start at the weighted mean
    mt19937 rng(2024);
    uniform_real_distribution<double> U(-1.0, 1.0), P(0.0, 1.0);
    double cur = energy(cx, cy), bx = cx, by = cy, best = cur;
    for (double T = 100; T > 1e-4; T *= 0.995) {  // annealing
        double nx = cx + U(rng) * T, ny = cy + U(rng) * T, e = energy(nx, ny);
        if (e < cur || P(rng) < exp((cur - e) / T)) { cx = nx; cy = ny; cur = e; }
        if (cur < best) { best = cur; bx = cx; by = cy; }
    }
    for (double step = 1; step > 1e-8; step *= 0.5) {   // final hill climbing from the best point
        bool moved = true;
        while (moved) {
            moved = false;
            double dx[4] = {step, -step, 0, 0}, dy[4] = {0, 0, step, -step};
            for (int k = 0; k < 4; k++) {
                double e = energy(bx + dx[k], by + dy[k]);
                if (e < best) { best = e; bx += dx[k]; by += dy[k]; moved = true; }
            }
        }
    }
    cout << fixed << setprecision(3) << bx << " " << by << "\n";
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
int main() {
    int n, m;
    cin >> n >> m;
    const ll INF = LLONG_MAX / 4;
    vector<vector<ll>> d(n + 1, vector<ll>(n + 1, INF));
    vector<int> deg(n + 1, 0);
    ll total = 0;
    for (int i = 1; i <= n; i++) d[i][i] = 0;
    for (int i = 0; i < m; i++) {
        int u, v; ll w; cin >> u >> v >> w;
        d[u][v] = min(d[u][v], w); d[v][u] = min(d[v][u], w);
        deg[u]++; deg[v]++; total += w;
    }
    for (int k = 1; k <= n; k++) for (int i = 1; i <= n; i++) for (int j = 1; j <= n; j++)
        if (d[i][k] < INF && d[k][j] < INF) d[i][j] = min(d[i][j], d[i][k] + d[k][j]);
    vector<int> odd;
    for (int v = 1; v <= n; v++) if (deg[v] % 2) odd.push_back(v);
    int k = odd.size();
    vector<ll> f(1 << k, INF);
    f[0] = 0;
    for (int S = 0; S < (1 << k); S++) {          // S = already paired odd vertices
        if (f[S] >= INF) continue;
        int i = 0;
        while (i < k && (S >> i & 1)) i++;
        if (i == k) continue;
        for (int j = i + 1; j < k; j++)           // pair the lowest unpaired vertex i with j
            if (!(S >> j & 1)) f[S | 1 << i | 1 << j] = min(f[S | 1 << i | 1 << j], f[S] + d[odd[i]] [odd[j]]);
    }
    cout << total + f[(1 << k) - 1] << "\n";
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

const int N = 100005;
vector<int> ch[N];
int sg[N];

void dfs(int u) {
    sg[u] = 0;
    for (int i = 0; i < int(ch[u].size()); i++) { dfs(ch[u][i]); sg[u] ^= sg[ch[u][i]] + 1; }
}

int main() {
    int n;
    cin >> n;
    for (int i = 2; i <= n; i++) { int p; cin >> p; ch[p].push_back(i); }
    dfs(1);
    cout << sg[1] << "\n" << (sg[1] ? "First" : "Second") << "\n";
    return 0;
}
